window.__D("text/pirush-hamilot/c001",{"p":[[2400650169,"בהשגה שכלי' ולא במהות כלל ולפי\"ז איך אמר מהימנותא שלימתא דמשמע השגה שלימה כמו ראי' המהות ממש וכמו לע\"ל דכתי' כי עב\"ע נראה כו' והאמונה כאלו רואה במהות ממש הוא עכשיו שנק' מהימנותא שלימתא בכל ע\"ס דאצי' ובהנעלם ונפלא מהן שנק' טמירין עילאין כו' כנ\"ל. אך הפי' דמשתעי כמו שמספר דבר שראה במהות שאעפ\"י שמספר דברים בעלמא אבל סיפור זה בא מכח ראי' המהות כו' והוא יתרון המעלה במה דמשתעי כאלו משיגים במהות ובאמת הרי לית מח' כו' וכמ\"ש אין אמ\"ר כו' אבל בחי' קום שהוא אור התעה\"פ העצמי הנ\"ל שמאיר בכנ\"י מצד בחי' עצמי' שרש נשמתם בתענוג העצמי כמ\"ש אז תתענג על ה' למעלה משם הוי' דאבי\"ע והוא גם בפשוטי' וע\"ה בבחי' תענוג עצמי' באלקו' בלי טעם ודעת כלל וזה שוה בגדול ישראל עם הקטן שבקטנים ופחות הערך מאיר בבחי' יחידה שבנפשם בשבת מעצמות התעה\"פ כו' והוא הנק' נשמה יתירה כו' שמקבלים בשבת מאור העצמות בדרך קו כו' כנ\"ל וז\"ש בפע\"ח דבשבת דמאותה הארה עצמי' התענוג בשבת יכולה הנשמה דכ\"א מישראל להשיג ולדבר כל וי\"ו יומין דחול בכל עמקי רזין פנימאין שבכל סתרי ההשתלשלות והיינו מה שנמשך מוחין פנימאין לכל ימי החול מהארת קום של אמ\"ר זה שהוא למעלה מאמ\"ר זה העצמי כו' וד\"ל. (ובכ\"ז יתורץ גם מאמר דבמופלא ממך אל תדרוש משמע שיכול לדרוש רק שאינו רשאי כמ\"ש בע\"ח דבחי' מל' דא\"ס אין רשאין לדבר דמשמע שיכולים לדבר אלא שאין רשאי אבל מצד הארת הקו דאמ\"ר הפנימי' שנגלה בשבת ב\"נ רשאי' למשתעי בדרגין עילאין כאלו אתגליין מטעם הנ\"ל וד\"ל."],[2400650170,"<h3>ובקצה תבל מליהם</h3>\n<b>(מ)</b> ובקצה תבל מליהם. שם בזוהר וז\"ל מרישא דעלמא עד סייפי דעלמא משתעי אינון חכימי ליבא באינון דרגין גניזין אע\"ג דלא אתיידעי. הנה הזוהר מפרש פי' דמליהם לשון תרגום של דיבור וקאי על ב\"נ דמשתעי אינון חכימא לבא באינון דרגין כו' וזה אינו לפי הפשט הכתוב דמליהם זה קאי אדסמיך ליה ברישא דקאמר בכל הארץ יצא קום והיינו קוום דאמ\"ר ודברים הנ\"ל ועז\"א דגם בקצה תבל מליהם ולא על ב\"נ כו' אך לפי פי' הזוהר בקום שהוא הסיבה שיכולי' ב\"נ למשתעי ברזא דמהימנותא כו' ע\"כ מפרש למליהם על ב\"נ דמליהם היינו מה דמשתעי מכח בחי' הארת קום והכל ענין וטעם א' הוא דהיינו מפני בחי' הארת קום בכל הארץ אשר מזה בא השפע והכח לכל בני עלמא דבי\"ע לאשתעי ולכך בקצה תבל מליהם דב\"נ והוא מליהם דאמ\"ר ודברים שיצא קום כו' אמנם י\"ל מהו ובקצה תבל מליהם דמשמע שיש ב' קצות קצה עליון וקצה התחתון וכמ\"ש מרישא דעלמא ועד סייפי דעלמא דסייפי"],[2400650171,"דעלמא נק' קצה תבל האחרון ורישא דעלמא הוא מ\"ש בכל הארץ כו' והיינו מקצה העליון דכתר דא\"ק וע\"י כו' עד קצה האחרון דמל' דאצי' בבי\"ע שנק' קצה תבל משתעי באינון דרגין גניזין וי\"ל דבקצה העליון דכתר שייך לומר דמשתעי בדרגין גניזין להיות ששם נק' סדכ\"ס מופלא ומכוסה כו' אבל בקצה האחרון דתבל איך שייך שם בחי' דרגין גניזין שהרי שם סוף הכל אלא הענין דזהו רבותא טפי דגם בקצה תבל דעשי' משתעי באינון דרגין גניזין באורות הנעלמו' בכתר עליון ואע\"ג דלא אתיידעי גם בכתר בהיות נק' סדכ\"ס מ\"מ בסייפי עלמא רבותא טפי מה שמושג להם אחר ששם הוא תכלית ההסתר דאור האלקי כו' ולפי ששרש זה הכח בא מבחי' גלוי אור העצמות דקמי' כחשיכא כו' העלם וגילוי שוין כו' ע\"כ גם ההעלם נגלה לפניו כו' לכך משתעי ב\"נ מרישא דעלמא עד סייפי דעלמא באינון דרגין וגניזין הכל בשוה מצד הארת קום שמאיר בכל הארץ בשוה מטעם הנ\"ל ולפי\"ז מ\"ש בכל הארץ שמאיר בכולם בשוה היינו בבחי' קום שהוא רק בחי' המשכה היולי' ועצמי' שמשפיע לגדול וקטן בשוה כו' אבל מה דמשתעי חכימי לבא שבא בדיבור והשגה יש בזה חילוקי מדריגו' מראש לסוף שנק' ב' קצוות קצה העליון עד קצה התחתון וז\"ש ובקצה תבל פי' מלתא באפי נפשי' קאמר דמפני כח הקו נמשך כח הדיבור והשגה לחכימא לבא למשתעי מקצה העליון דכתר עד קצה תבל האחרון (וע\"ד שאמר בשלמה וידבר מן הארז אשר בלבנון שהוא גדלות מדות שבכתר עד אזוב אשר בקיר בחי' קטנות המדות דיסוד במל' שנק' קיר כו' כמ\"ש במ\"א וחכמת שלמה נק' ח\"ת ואיך הי' יכול לדבר בארז אשר בלבנון שהוא במדות ושכל דע\"י וא\"א וא\"ק וכה\"ג אלא משום שנא' וה' נתן חכ' לשלמה מהארת עצם אור חכמתו דשוה לפניו ראש וסוף). והנה פי' תבל הוא ארץ מיושבת בבנ\"א וארץ הוא עצם הארץ כמו אנכי עשיתי ארץ וכו' וכתיב דור הולך כו' והארץ לעולם עומדת נמצא חיבור דאדם בארץ נק' תבל כמ\"ש לה' הארץ ומלואה תבל ויושבי בה כו' (והוא בחי' התכללו' דמ\"ה וב\"ן ב\"פ גבו' גבו' עילאה וגבו' תתאה וגבורה גימט' רי\"ו וב\"פ רי\"ו גימט' תב\"ל) וכל הברואי' לבד האדם הארץ הוציאה אותם כמ\"ש תדשא הארץ תוציא הארץ כו' ואדם לוקח עפרו לבד מן הארץ כו' ולמעלה ג\"כ כל המלאכי' עליונים נבראו מן הארץ עילאה כמו העוף ירב זה מיכאל כו' וזהו ובקצה תבל כאשר בא בהשגת אדם דעשי' בגופו בדיבור הוא קצה האחרון לגבי עולמות הרוחני' כו'. ויש עוד פי' מליהם לשון מילוי בהעלם ולא לשון דיבור והענין הוא להיפוך דתבל מצד בחי' אדם שבו שהוא אחרון למע\"ב וקדם לכולם כמ\"ש אחור וקדם צרתני וכידוע דנתחב\"ס דוקא לפי שהאדם אדמה לעליון מפני שהוא בבחי' התיקון"],[2400650172,"שהוא בחי' ההתכללות מכל המדריגות ע\"כ בו דוקא שורה בחי' שלימותא דכולא מבחי' העצמי' דאא\"ס שנק' סדכ\"ס כל בחי' דרגין עילאין גניזין דלא אתיידעי לעלמין כו' ובאדם זה שורה הכל רק שהוא כלול בבחי' העלם הנק' מילוי וז\"ש ובקצה תבל מליהם בחי' המילוי (וכמ\"ש במ\"א באריכות בפי' הזוהר ע\"פ מי ימלל גבו' ה' כו' דארץ בבחי' התיקון פרקין ושייפין ואדם עליה בראתי בבחי' התיקון ואורייתא פרקין ושייפין כו' ע\"כ כל העולם נגלה ע\"י בעסקו בתורה לפי שכלול מהכל והוא פי' גבורות ה' ב\"פ גבו' גימט' תבל כנ\"ל וד\"ל). וז\"ש חכימי לבא משתעי באינון דרגין כו' דהיינו מה שביכולתם לייחד יחודי' עליוני' בימות החול מרישא דעלמא עד סייפא דעלמא שהוא מראשית הקו והחוט שרש הראשון דכל השתלשלות דאבי\"ע עד סייפי עלמא מאור האצי' בבי\"ע שנק' קצה תבל והיינו לפי שכל יחוד הוא בחי' התכללות דמ\"ה וב\"ן בפרט כידוע ולהיות שבחי' אדם הוא בבחי' התכללות כללי גם מכל אורות הנעלמי' שבעצמו' דלא אתיידעי לעלמין באו\"כ באצי' וכמ\"ש שם מ\"ה מלגו דאיהו אורח כל אצי' כו' דהיינו מה שממשיך גם מכל בחי' העלם העצמות שיהי' שורה עכ\"פ ביחודים הללו וכ\"ז לפי שאדם אדמה לעליון שלימות העצמות ממש רק ששורה בו בהעלם ולא בגילוי והיינו פי' מליהם בבחי' מילוי והענין יובן עפ\"י הידוע ומבואר בבחי' אדם העליון שהוא בחי' ז\"א דאצי' שנק' סוף עולם הא\"ס בכלל והגם שנק' סוף אבל נתחב\"ס דוקא ובו מתלבש בהעלם מכל אורות הנעלמי' בעצמות שנק' סדכ\"ס דלא אתיידעי כלל משא\"כ בעליון הימנו כמו או\"א וע\"י כו' ששם העלם העצמות מופלא ונק' סדכ\"ס כו' שנשאר בעצמותו והענין הוא עד\"מ כידוע בבחי' נפה\"א שהרצון למעלה מן השכל ונעלם הימנו לעולם שלעולם לא ישיג השכל את הרצון וכן הרצון לא ישיג לשרשו מקור כל רצון כו' וכן עונג הנגלה ומורגש לא ישיג לעונג הנעלם וכן עונג ורצון הנעלם לא ישיג למקור כל רצון ועונג נעלם שנק' העלם דהעלם כו' אך בהיות הרצון בא לידי סוף מעשה שאז יתלבש בשכל והשכל במדות והמדות הן הנק' סוף גילוי הרצון והעונג מהעלמם הראשון כי המעשה לא תעשה רק ע\"פ קצבת אור המדה שבלב שבהן נגבל שפע כל רצון באופן כך וכך בחסד והתפשטות ואופן כך וכך בצמצום והעדר התפשטו' וכן בבחי' הממוצע כו' וע\"כ נק' סוף כמו שהסוף בו עיקר גילוי ההתחלה ולכך נתחב\"ס דוקא כידוע. אך הנה א\"א לומר שכל מהות אור הרצון והעונג כמו שהוא למעלה בהעלמו דהעלם כנ\"ל בא ומתגלה במדות שנק' סוף כי המדות המה רק הגבלת הרצון אבל זה יתכן לומר שבאופן הגבלת המדות בהם שורה בהעלם כל אור מהות הרצון הנעלם כמו שהוא"],[2400650173,"בעצמו' דוקא רק שנכלל בדרך הגבלת קיצור המהות של המדות וכמו ע\"ד דוגמא השונה לתלמידו בדרך קצרה שאינו מעלים ממנו דבר רק כולל הכל בדרך קיצור ובקיצור דברי' הללו שורה הכל ויוכל להגלות ממש למבין רק לשאינו מבין נעלם הוא וכן עד\"מ המפה הציור שבה בקיצור כולל כל חלקי הארץ באין חסרון והעדר דבר אפי' דבר קטן רק ציורו בקו בעלמא ועיקר המשל בזה ידוע מכח המוליד בדומה לו שיש בהעלם הכל בנולד וכשיגדל יתגלה מעט מעט כמו בצלם יתהלך איש שבהיותו בן ע' שנה יוצא כל העלם חכמתו לגילוי ובקטנותו שורה בו בהעלם כמו בוצין בוצין כו' וכמ\"ש במ\"א ומכל דמיונות האלה מובן בבחי' אדם אדמה לעליון שבו שורה בהעלם כל אורות העצמי' שנק' סדכ\"ס כו' ואין העלם זה כהעלם שבאו\"א וא\"א שנעלם שם אור העצמות לגמרי אבל בבחי' אדם דאצי' שורה בו ממש רק שאינו בא בגילוי גמור באו\"כ ממש וזהו פי' מליהם לשון מילוי בהעלם ומה שבכל הארץ עד אדם שבתבל יצא קום בבחי' המשכה היולית בכלל אבל בקצה תבל מליהם בפרט דהיינו שכל פרטי אורות שבעצמות סתומי' בי' בבחי' מילוי הכל לא נעדר דבר וכו' משום דנתחב\"ס דוקא וז\"ש בתורה ג\"כ משחקת לפניו בתבל ארצו דוקא וכ\"ז שבימי החול יש בחכימא ליבא כח ליחד כל יחודים העליונים שבכל פרטי אורות הנעלמי' שבעצמות מפני שבשבת קבלו מהארת אור העצמו' שהוא מ\"ש בכל הארץ יצא קום כנ\"ל וד\"ל:\n(מא) <b>והנה</b> יש לפרש עוד בביאור המאמר הזה דמרישא דעלמא עד סייפי כו' בהיפוך מפי' הראשון והוא בהיות שהזוהר מפרש מליהם לשון דיבור דוקא והוא מה דבני עלמא יכולי' לדבר בקצה תבל מליהם כו' כנ\"ל וע\"כ מדקדק הזוהר במ\"ש ובקצה תבל שיש בתבל זה ב' קצוות ושניהם נק' קצה תבל א' קצה תבל הא' והב' קצה תבל הב' ומ\"ש ובקצה תבל מליהם היינו בקצה תבל הב' כו' ויובן זה בהקדים המבואר במ\"א בפי' כי שאל נא לימים ראשונים ולמקצה השמים עד קצה השמים כו' קצה השמים לעילא וקצה השמים לתתא שהוא בחי' ע\"ס דעגולי' שנק' שמים שיש בזה ב' קצוות קצה העליון וקצה התחתון והיינו בחי' כתר ומל' שבחי' אור הכתר נק' קצה העליון והוא הרצון והתענוג שבתוכו עיגול הב' דחכ' טעם לרצון כאשר יהי' האופן כו' עד עיגול האחרון הוא סוף מעשה ונק' תחילה וסוף וזהו בחי' ע\"ס דאו\"י כמו שהולך השפע מלמעלה למטה הרי המעשה סוף והרצון תחלה ואמנם בבחי' ע\"ס דאו\"ח ממטה למעלה נהפוך הוא שהמעשה נק' תחילה והרצון נק' סוף והוא כידוע דסוף מעשה עבמ\"ח ורצון תחילה דהיינו תחלה לרצון כי עיקר הרצון לא הי' רק בשביל המעשה כידוע כאשר עלה המעשה תחילה נק' הרצון סוף ונמצא בבחי'"],[2400650174,"ע\"ס דאו\"ח המל' נק' כתר והכתר נק' מל' וכמו ב' קצוות שאין ידוע להחליט שזה הקצה הראשון וזה הקצה הסוף מאחר שב' קצוות הן וכ\"א נק' קצה אלא כשההתחלה מצד זה נק' הקצה הב' סוף וכשההתחלה מצד האחר נק' קצה הזה סוף כו' וא\"כ כשהמעשה עלה תחילה נק' הרצון שהוא הכתר סוף כו' וכך הוא ג\"כ בבחי' ע\"ס דיושר שהוא בחי' התיקון שנק' תבל או ארץ כידוע שזה לא כאופן בתוך כו' כעיגולים דתהו אלא מתלבש ומתכלל זה בתוך זה כמו הרצון מתלבש ומתעלם בשכל והשכל מקיפו והשכל מלובש במדות והמדות במעשה עד שהמעשה מקיף לכולם כו' כמ\"ש במ\"א באריכות. והנה כשבא הדבר בפועל המעשה אז נשלם הרצון דהיינו גם בחי' סוף מעשה שעלה תחילה ברצון נשלם כשבא בפו\"מ דוקא אבל בעוד הסוף מעשה רק ברצון ומחשבה לא נשלם עדיין כי אולי לא יבוא פו\"מ ולא ישאר רק ברצון ושכל כו' ונמצא גם מה שבבחי' עיגולים עלה בבחי' או\"ח שאז הכתר נק' מל' והמל' נק' כתר שזהו סוף מעשה כמו שהוא ברצון תחילה גם הוא עיקר שלימותו בא רק מבחי' המעשה בפו\"מ כמו שהוא בבחי' התיקון דע\"ס דאו\"י שהמעשה אחרון כנ\"ל וד\"ל. וכמו\"כ יובן עוד דגם בבחי' התיקון יש ב' מדריגות דאו\"י ואו\"ח וגם בזה הכתר דתיקון נק' מל' והמל' נק' כתר והענין הוא דבחי' המעשה שעולה ברצון נק' מל' שבכתר שבא אחר הטעם ומדות שברצון אבל עדיין הוא ברצון אמנם בבחי' היושר והתיקון הרי בא ירידת הרצון עד בחי' המעשה בלבד ונק' רצון זה ששייך למעשה בלבד אחר הסתלקות הטעם ומדות שברצון כו' בשם כתר מל' וז\"ש דכתר מל' איהו כתר עליון פי' שנשלם בזה עיקר הרצון שלמעלה מבחי' המעשה שברצון ונמצא הכתר שהוא עיקר הרצון נק' סוף שנשלם ע\"י שלימות הרצון במעשה בפו\"מ ובזה יתרון מעלת או\"ח דתיקון שמשלים גם למקור ועיקר הרצון שלמעלה גם מסוף מעשה שעלה תחילה לרצון הנ\"ל בבחי' עיגולים והוא מצד שלימות הרצון שבמעשה בלבד שנק' כתר מל' דתיקון שמשלים לתחילת הרצון דתיקון שלמעלה גם מתחלה שברצון דתהו שהוא סוף מעשבמח\"ת הנ\"ל והיינו פי' כתר עליון בחי' כשב\"כ שלמעלה הרבה מבחי' מל' שבכתר כו' והיינו מ\"ד ארץ קדמה לשמים דקאי בבחי' מל' דתיקון שנק' ארץ ותבל שקדמה לשמים דתהו לפי שנתחב\"ס עד שהסוף דתיקון דייקא נק' ראש וראש דתיקון נק' סוף ומכש\"כ לגבי ראש דתהו שנק' שמים שהן בבחי' העיגולים דתהו כידוע וד\"ל. ומעתה יתבאר דברי המאמר הזה במ\"ש מרישא דעלמא כו' דמפרש ובקצה תבל זה ב' קצוות דע\"ס דתיקון כי ארץ ותבל הוא בבחי' התיקון ויש בו ב' קצוות דהיינו בב' מדריגות דאו\"י ואו\"ח. והנה בבחי' או\"י הרי בע\"ס דאצי' נק' כתר דאצי' תחילה והמל' דאצי'"],[2400650175,"שבבריאה כו' סוף וא\"כ בחי' קצה הא' דתבל דאצי' הוא בבחי' הכתר דאצי' ובקצה הב' הוא במל' בבריאה ובבחי' ע\"ס דאו\"ח נהפוך הוא דבחי' דקצה האחרון דתבל הוא בחי' כתר דאצי' שנק' סוף לגבי עולם הבריאה ששם קצה הא' כי כתר מל' דאצי' בבריאה נק' ראש וכתר דאצי' נק' סוף מטעם הנ\"ל ונמצא לגבי עולם האצי' נק' עולם הבריאה קצה תבל ולגבי עולם הבריאה נק' כל האצי' קצה תבל ובהיות שהזוהר מפרש מליהם שהוא לשון דיבור דבני עלמא יכולי' לדבר ובני עלמא זה היינו עולם הבריאה שנק' אצלם כתר דאצי' בחי' קצה תבל האחרון שהוא בחי' סוף דאצי' הגם שבאצי' עצמו הוא ראש כו' וזהו שמפרש ובקצה תבל מליהם שבני עלמא יכולים לדבר בע\"ס גם בקצה תבל דאצי' דהיינו בסוף עולם האצי' שהוא בחי' כתר דאצי' שנק' לגבי מלכות דאצי' בבריאה בבחי' סוף כנ\"ל כי מלמטה למעלה כתר מל' דבריאה איהו כ\"ע כו' דהכתר מל' והמל' כתר שנתחב\"ס וסוב\"ת וכמ\"ד ארץ קדמה כנ\"ל וד\"ל וז\"ש מרישא דעלמא שהוא בחי' כתר שבמל' דאצי' שבבריאה דוקא עד סייפי עלמא שהוא בחי' הכתר דאצי' שהכתר נק' מל' כי נעוץ סוב\"ת בבחי' כשב\"כ וזהו היפוך הפי' הראשון דלעיל וד\"ל. ולפי פי' זה יתפרש יותר לנכון כפי הפשט לשון המאמר במ\"ש דחכימא לבא משתעי באינון דרגין עילאין גניזין דלא אתיידעי כו' דהיינו כל בחי' יחודים עליונים שעושים בעסקם בימי החול בדיבור באינון דרגין דע\"ס דאצי' בבחי' העלם העצמות דרצוה\"פ הגנוז בהם שנק' סדכ\"ס [ו]רעדכ\"ר וכה\"ג לפי שבסוף מעשה דוקא נשלם תחילת עיקר הרצון שנק' מקור הרצון רעדכ\"ר או סדכ\"ס כו' ע\"כ חכימא לבא דוקא משתעי כאלו אתגליין ולא הוו טמירין כלל כנ\"ל והיינו מפני שבשבת קבלו הארה עצמי' דאוא\"ס שבמאיר באמ\"ר העליון שנק' קום וכמ\"ש בכל הארץ יצא קום כו' ומ\"ש ובקצה תבל קאי ארישא דיצא קום והוא לפי שבשבת אז עליות העולמות בבחי' או\"ח דתיקון כמ\"ש אשר ברא אלקים לעשות לתקן וכתיב ויכולו השמים כו' כי מכל מלאכתו אשר עשה בבחי' ע\"ס דאו\"י מלמעלה למטה עולה בבחי' או\"ח וכמ\"ש וירא את כל אשר עשה והנה טוב מאד מפני שע\"י סוף מעשה בפו\"מ דוקא נשלם מקור תחילת הרצוה\"פ כו' (וכמ\"ש למעלה בענין ב' שבתות כהלכתן) וזהו מ\"ש בכל הארץ יצא קום מהעלם אור העצמות ממש בבחי' או\"י ואח\"כ ובקצה תבל מלמטה למעלה בבחי' או\"ח נמשך מוחין פנימאין לחכימא לבא בכל ימות החול שיכולין לדבר באינון דרגין עילאין דלא אתיידע לעלמין והוא כל בחי' יחודים עליונים דק\"ש בכ\"י שמקבלים רק מהארת קוום דשבת כמ\"ש בתחילת זה המאמר דבגין דההוא משיכו ונגידו דאתמשיך לתתא אית לון מהימנותא שלימתא בהאי עלמא שהוא יחו\"ע"],[2400650176,"דק\"ש בכל יום לכ\"א מישראל בכל חד לפוש\"ד וכל ב\"נ משתעי כו' כי גם הקטן שבישראל שאין לו רק בחי' נפש דעשי' מקבלים מהארת קום בכל שבת בבחי' נשמה יתירה שלו כנ\"ל וד\"ל:"],[2400650177,"<h3>לשמש שם אוהל בהם</h3>\n(מב) <b>לשמש</b> שם אוהל בהם פי' בזוהר שם וז\"ל. אבל במה אשתמודען לשמש שם אוהל בהם בגין שמשא קדישא דאיהו משכנא מאינון דרגין עילאין קדישין ואיהו נהורא דנטיל כל נהורין גניזין וההוא משיכו דלהון ובגיני' אתחזי' מהמנותא בכל עלמא מאן דנטיל לשמשא כמאן דנטיל לכולהו דרגין בגין דשמשא איהו אוהל דאתכליל בהון ונטיל כולא ע\"כ. פי' אשתמודען היינו בחי' השגת המהות ולא השגת המציאות בלבד דלשון אשתמודע בתרגום היינו כמו הכרה בלה\"ק שמכיר המהות ממש ולא בהשגות המציאות בשכל מרחוק בלבד וראי' ממה שאמר בסמוך ובגיני' אתחזי' מהימנותא כו' פי' אתחזי' בהשגות והכרת המהות ולא בראיי' השכל בהשגות המציאות בלבד (ואעפ\"י שנק' מהימנותא לשון אמונה אבל אמונה זו חזקה היא כמו הראי' במהות ובלשון רז\"ל נק' מכיר את בוראו כידוע) והיינו אתחזי ממש ולא כמ\"ש בכל הארץ יצא קום שאעפ\"י שמחמת זה כל ב\"נ משתעי ברזא דמהמנותא כאלו אתגליי' כו' ואית לון מהימנותא שלימתא כנ\"ל היינו רק בהשגת שכל שבא בדיבור שאינו רק בהשגת מציאות ולא בהשגות והכרת המהות ממש ולזה אמר אבל במאי אשתמודען ממש לשמש שם אוהל בהם בגין שמשא קדישא כו'. וביאור שרש הדברים הנה י\"ל שרש ההפרש בין ראי' השכל לראי' והשגה במהות דלכאורה ענין א' הוא שהרי ידוע שהחכ' הוא בבחי' ראי' כמ\"ש וירא ראשי' כו' והוא בבחי' ראי' שכלי' שאינו רק השגת המציאות וא\"כ גם השגה במהות בחכ' אינו כ\"א עפ\"י ראי' והשגת השכל כמו בר\"מ שאמר בעין השכל אתחזי כו' ולפי זה אין זה השגת המהות ממש כמראה הנביא ולמה חכם עדיף מנביא מאחר שאינו רואה רק ראי' שכלית. אך הנה יש להקדים תחילה שיש שני מיני שפע הא' בחי' שפע העצמי' ומקוריות דהיינו שבחי' העצמיות ומקוריי' נשפע ונמשך שנק' השפעת המהות והעצם והוא כמו השפעה דטיפה במוח האב שבחי' עצמיות שבמוח נמשך ע\"כ מוליד נפש עצמי' בדומה כו' והגם שזה נמשך ונשפע ממוח החכ' שבאב בלבד אבל זהו בחי' עצמו' ומהות דמוח החכ' ולא בחי' התפשטות הארתו בלבד ע\"כ יוליד עצם דבר כו' ולא יופסק כו' והב' בחי' השפע חיצוני' שהוא שפע האור והתפשטות מן העצם בלבד ולא העצם והמהות כלל וכמו שפע התחכמות שכל שנמשך מן מוח דחכ' שנק' אור עצם החכ' בחי' אורו וזיוו המתפשט מבחי' עצמותו ומהותו ע\"כ משפע החיצוני' דהתחכמות וכה\"ג לא יוליד מאומה כו' וזהו ההפרש בין"],[2400650178,"בחי' פנימי' אבא שהוא עצמיות דחכמה לחיצוני' אבא שהוא רק גילוי אור שכל וסברא וכה\"ג כערך ההפרש בין אור למאור העצמי וכך יובן בענין שרש ההפרש בין ראי' דחכ' שבא ע\"י השגת ראי' אור השכל שנק' אור התפשטות מן העצם בלבד שעי\"ז לא ישיג רק השגת שכלי שאינו רק במציאותו ולא במהותו ממש אבל בחי' ההשגה במהות אינו כ\"א ע\"י בחי' עצמי' דחכ' שנק' מאור ולא אור כעצמיות המוח בטיפה כנ\"ל וזהו הנק' ראי' החכ' במהות שזהו ע\"י בחי' עצמי' דאבא שנק' פנימי' אבא והוא מדריג' דמשה דכתי' בי' וירא ראשית כו' (וכמ\"ש במ\"א בענין האספקלריא המאירה כו' שנק' מאור עצמי כמו מאור השמש שלמעלה מבחי' זיוו ואורו וכמשי\"ת בסמוך בביאור זה המאמ') ומה שהחכ' נק' אור ג\"כ נק' ראי' כמו שרואי' לפני אור הנר שמאיר ומתפשט אור הזה אך אינו רק בבחי' התפשטות בלבד וזהו הנק' ראי' אור השכל בהשגה שכליי' לבד שאינו שפע עצמי' כלל (וגם כמו שאמרו איזהו חכם הרואה את הנולד שהוא נעלם מן האדם ה\"ז כמו שרואה ע\"י אור הנר גם במקום חושך ואפילה). אך מ\"ש חכם עדיף מנביא גם בראיי' המהות הוא כשרואה בראי' דעצם ומהות החכמה שנק' מאור ולא אור כמדריגה דמשה שנתנבא בזה בראי' המהות מצד ראי' ע\"י מהות דחכ' משא\"כ שאר הנביאים שנתנבאו בכ\"ה בכ\"ף הדמיון שהוא בהגלות נגלו' אור האלקי לפי הכנת כלי אור השגת שכלם ומחשבתם כמ\"ש ביד הנביאים אדמה כו' וז\"ש בר\"מ דוקא בעין השכל דבליבא אתחזי כולא בראיי' המהות (כמ\"ש במ\"א בפי' אשר ידעו ה' פא\"פ כו' משום דפנימי' אבא הוא פנימי' ע\"י). והנה אחר הקדמה זו יובן כללות ענין המאמר הזה בהתחלתו מ\"ש אבל במה אשתמודען דקאי על אינון נהורין עילאין גניזין דמשתעי ב\"נ כו' במה אשתמודען בהשגת המהות ממש דהיינו שיהי' מהותם ועצמותם מושג (ולא כמראה הנביאים שאף שרואי' במהות אך רק דרך מחזה ואספקלריא כרואה במראה כמ\"ש הן במראה אליו אתוודע כו' ולזה אמר חכם עדיף מנביא שרואה במהות ועצם בלי אמצעי כלל כמ\"ש במשה פא\"פ אדבר בו כו') והשגה זו שמשיגי' במהות היינו במהות ועצמי' דחכ' שנק' מאור ולא אור כנ\"ל שלמעלה מהשגה שכליי' שע\"י אור השכל שהוא רק בחי' התפשטות מן העצם בלבד וממילא אינם משיגים רק במציאות ולא במהות כלל וד\"ל. וז\"ש אבל במה אשתמודען במהות שא\"א להיות ע\"י ראי' שכליי' כמו שאר ב\"נ דמשתעי ברזא דמהימנותא שלימתא שאין זה רק בהשגת השכל שבא בדיבור כאלו משיגים המהות כמ\"ש כאלו אתגליין כו'. הנה לזה אמר לשמש שם אוהל בהם כו' בגין שמשא קדישא דוקא להיות מבואר למעלה בענין בכל הארץ יצא קום דקוום זה הגם שבא מבחי' אור"],[2400650179,"העצמי' דוקא שלפניו נגלה כל העלם היותר עליון כו'. אבל גם זה אינו גורם רק להיות בחי' גילוי אא\"ס בראיי' השכל שנק' אור החכ' בלבד וממילא הרי אינם משיגים במהות ועצם דאינון דרגין עילאין גניזין רק משתעי בהון בשכל שבדיבור כנ\"ל שנק' השגת המציאות אבל במה אשתמודען דרגין עילאין גניזין הללו במהותם ועצמותם לשמש דוקא והוא בחי' עצם החכ' שנק' פנימי' אבא ובחי' ההארת העצמי' דאבא נק' בחי' פנימי' יסוד אבא והוא הנק' בזוהר שמשא קדישא דוקא דקדש בחכ' העצמי' וז\"ש ובגיני' אתחזי' מהימנותא אתחזי ממש כנ\"ל והוא שרש המדריגה דמשה שהוא בבחי' פנימי' יסוד אבא וכמ\"ש פני משה כפני חמה כו' וד\"ל. וז\"ש בגין שמשא קדישא שהוא בבחי' יסוד אבא בבחי' פנימי' ועצמי' שבו שנק' פני חמה דהיינו לא בחי' האור וההתפשטות שלו שנק' זיו השמש בלבד אלא בחי' שמשא עצמו ומהותו וכמ\"ש כי שמש ומגן הוי' אלקים פי' הוי' זה היינו בבחי' הוי' דחכמה עצמה והוא שנק' שמשא קדישא בבחי' קודש העליון דפנימי' אבא שבו וע\"י יוכל לחזות בנועם ה' בבחי' השגת המהות ועצמות דאא\"ס ממש כי עיקר גילוי עצמות דאא\"ס הוא בפנימי' ועצמי' דחכ' שנק' שמשא קדישא והוא בחי' המאור דחכ' (וכמ\"ש במ\"א בפי' ועינינו מאירות בבחי' מאור ולא בבחי' אור כו') ומ\"ש עוד דאיהו משכנא מאינון דרגין עילאין כו' שזהו פי' למ\"ש לשמש שם אוהל בחי' המקיפי' כמשי\"ת היינו בחי' יסוד אבא שנק' משכנא דאינון דרגין כו' ואעפ\"י שבחי' יסוד הוא בחי' ההשפעה למקבלים אין זה בחי' אור וזיו אלא בחי' השפעה עצמיי' כנ\"ל והוא הנק' בחי' פנימי' יסוד וכמ\"ש בסמוך דאיהו נהורא דנטיל כל נהורא שכל האורות העליונים כלולי' בו ומאן דנטיל שמשא כאלו נטיל כולהו דרגין כו'. אך א\"כ י\"ל למה נק' בשם אוהל כמ\"ש לשמש שם אוהל בהם וגם להבין כל פרטי דברי המאמר במ\"ש דאיהו משכנא דאינון כו' ואח\"כ אמר ואיהו נהורא דנטל ומסיים דאיהו אוהל דאתכלל בהון ולא שהן נכללים בו דלכאורה יקשה רישא לסיפא הנה יש להקדים תחילה בפי' ענין יסוד אבא שמלובש ביסוד ז\"א שזהו ענין שמשא קדישא הנזכר כאן:\n(מג) <b>דהנה</b> ידוע בביאור ענין יסוד שנק' צדיק וטוב כמ\"ש אמרו לצדיק כי טוב כו' שזהו בחי' טבע הטוב להיטיב לכל והוא בחי' צדיק שהוא צדקות אהב להחיות רוח שפלים כי הצדקה עצמה היא השפעה שכבר נשפע למקבל וצדיק הוא המשפיע צדקה זו והוא מחמת טבע טובו שמדת טובו גורם שמשפיע וייטיב לאחרים ונמצא הטבתו לאחרים מסתעף מכח מדת עצם טובו דוקא ונק' מה שמטיב הטבות רבות לאחרים בשם חיצוני' כלי יסוד שנק' צדיק כשנק' בשם משפיע צדקה וחסד לדל ועני וכה\"ג אבל עצם מדת טובו שמכח הזה"],[2400650180,"חפץ להיטיב לכל נק' פנימי' ועצמי' יסוד ונק' טוב בעצם שכולל כל מיני הסתעפות ריבוי הטובות שמטיב לאחרים דהיינו כל מה שעתיד להשפיע לכל מכח טבע מדה זו (ובאמת יש בזו עצמו ב' מדריגות זו למעלה מזו דמה שכולל כל מה שעתיד להשפיע לכל אינו רק הכולל כל ההתחלקות ריבוי ההטבות שמתפשטין לזולתו אבל כל מה שכולל כל חלקי פרטי עצם טובו כמו שהוא טרם שמתפשט שייטיב מכח טובו הוא למעלה מהכולל כל הטובות שנק' הטבות כי זהו טוב העצמי שכולל כל מיני טוב שבעצם כמו מדת הטוב בעצם לפיזור ממונו שעצם הטוב הוא בא בדבר פרט במה שמפזר ממונו ומניח א\"ע בשביל זולתו וכן חסד שבגופו וכן חסד וטוב שבשפע שכלו ובטוב מדותיו יש ג\"כ פרטים בריבוי אופנים עצם הטוב שבכל מדה כמו לבזות א\"ע לילך לשפל ופחות הערך ולא להקפיד על בזיונו ולעבור על מדותיו ולרחם על שונאיו וכה\"ג רבים המה ולכך כללות עצם הטוב הוא מה שנתקבצו כל חלקי פרטי העצמי' ביחד (בל\"א נק' גוטער) כולל כל מיני טוב בעצם אך עיקר ענין הטוב בכלל הכולל כל מיני טוב העצמי הוא מה שמפקיר א\"ע בשביל זולתו (בל\"א גוצקייט) שמניח ומצמצם בעצמו ונותן לחבירו (בל\"א ער גיט זיך אוועק) כמו ב' מהלכים בדרך ושניהם צמאים וקיתון ביד א' שאינו מספיק רק לחיותו ומניח חיי עצמו ושותה רק החצי וכה\"ג ואעפ\"י שמן הדין חייך קודמין אבל מצד טבע הטוב העצמי שלא יוכל לראות ברעת חבירו הרי מפקיר א\"ע וטוב לו שימותו שניהם בקיתון זה שאינו מספיק לשניהם משישתה הוא כולו ויחי' וחבירו ימות לעיניו וכה\"ג. וז\"ש בזוהר אך טוב וחסד כו' טוב כד לא אתפשט לתתא וחסד כד אתפשט לתתא היינו מה שמניח א\"ע ועדיין לא בא השפעה לזולתו והוא הנק' טוב בעצם אבל ההטבה לזולתו הוא הנק' חסד המתפשט כו') ונמצא עכ\"פ יובן בבחי' יסוד שנק' צדיק ונק' טוב (שהוא התפשטות שפע ההטבה שנק' צדיק והטוב בעצם שנק' טוב ושניהם בבחי' הכלל שכולל כל פרטי ההסתעפות שבו כנ\"ל) שכל המדות כלולי' בו ונק' משכנא דכל נהורין כו' להיות שכל מדה יש בה מבחי' הטוב דיסוד שהוא ירידת השפע שלה הנק' הטבה בפרט של אותה מדה והטוב בעצם שבאותה מדה כמו יסוד שבחסד יסוד דת\"ת כו' וא\"ל לא הי' נמשך ממנו מאומה (והיינו בחי' ה\"ח שביסוד שנמשך מכל מדה שביסוד לפי שבחי' טוב שביסוד כלול הוא בכל מדה כמ\"ש בע\"ח דוי\"ו דיסוד מאיר בכל מדה כו') כי הרי מה שמטבע הטוב להיטיב שנק' צדיק וטוב הוא רק בבחי' היולי (שנק' בל\"א גוטער או גוצקייט) בלתי נודע עדיין דבר מה בפרט שבו יהי' נק' טוב רק בבחי' המדות פרטי' כמו מדת החסד בממון או חכ' כו'"],[2400650181,"בזה נודע וניכר מציאת טבע הטוב ולזאת הרי אינו רק בחי' היולי וכל האורות כלולים ביסוד להיות פועל טבע טובו על ידם כו' וד\"ל (וז\"ש יקוו המים כו' אל מקום א' שהוא בחי' יסוד שנק' כנישא דכל נהורין שבבחי' טבע הטוב שם הוא ירידת כל מדה מעצמותה למטה שזהו בחי' ה\"ח שבה לירד מגבוה לנמוך כו'. אך בכאן אמר משכנא שהוא בחי' אוהל בחי' מקיף שבו ישכנו כל האורות כמשי\"ת בסמוך). והנה שמשא קדישא הוא בחי' יסוד אבא בבחי' השפעה עצמי' דחכ' שנק' מאור ולא אור כנ\"ל ובחי' אור המאיר הוא בחי' יסוד ז\"א שנק' טוב והאור נק' טוב כמו וירא אלהים את האור כי טוב לפי שמטבע האור להאיר לזולתו ולצאת מעצמו שהוא כטבע הטוב להיטיב לזולתו כמ\"ש אור זרוע לצדיק כו' שמה שמטבע הטוב להיטיב נק' אור זרוע לצ\"ע בחי' יסוד ז\"א וכשהטוב בעצם עז\"נ טוב ה' לכל כידוע וד\"ל. ומעתה י\"ל ענין התלבשות בחי' יסוד אבא ביסוד ז\"א דוקא (כי יסוד אימא מסתיים בחזה כו' ויסוד אבא ארוך ומגיע עד יסוד ז\"א ולכך נק' יוסף יתום מאמו ולא מאביו כמ\"ש בע\"ח) דהנה מבואר למעלה בעיקר ענין טבע הטוב שהוא להניח א\"ע כו' וזהו בחי' פנימי' ועצמי' דיסוד שהוא הנק' עצם הטוב שכולל כל מיני הטבות שעתיד להשפיע כו' ויש בכלל מאתים מנה וכך הוא ממש בבחי' יסוד אבא שהוא בחי' השפעה עצמי' ומקורי' דהיינו שכל העצמי' נמשך משא\"כ שפע חיצוני' דשכל שא\"ז השפע' עצמותו ממש (אבל ענין השפעה דיסוד להיטיב לזולתו הגם שהטבה זו חיצוני' אבל נותן לו כל מה שבעצמי' ממש כמו ממעילו עד חגורו דיהונתן לדוד משום דאהבת נפשו אהבו שהוא האהבה דמשפיע למקבל שנותן המשפיע כל עצמותו עד שלא נשאר לו כלום כמו וכל אשר לאיש יתן בעד נפשו שלא נשאר לו כ\"א גווייתו כמו תושב\"כ לגבי תושבע\"פ שלא נשאר כ\"א אותיות שנק' גווייתו בלא נקודות כו' וכמ\"ש במ\"א) ולכך מגיע בחי' השפע עצמו דיסוד אבא עד יסוד ז\"א דהגם שבחי' יסוד ז\"א הוא רק בבחי' שפע חיצוני' להיטיב לזולתו אבל מצד הנחת עצמותו הוא בא (שנק' בל\"א גוצקייט) כנ\"ל ה\"ז בחי' השפעה עצמי' שנותן כל עצמותו (ער גיט זיך אוועק און לייגט זיך אוועק) כו' ונמצא דהשפעה עצמי' דיסוד אבא הנ\"ל שבא מצד העצם דוקא בבחי' יסוד ז\"א מתלבש רק ששם הוא מצד עצם הטוב הוא הגורם להיות משפיע כל עצמותו (וזהו טיפת יסוד ז\"א שאחוז וקשור בהשפעה עצמי' דטיפה הרוחני' שבמוח שהוא השפעה עצמי' מצד העצם ממש שנק' פנימי' יסוד אבא ויוצא לחוץ מעצמותו למקבל ע\"י יסוד דז\"א שבו הטבע להיטיב לזולתו (בל\"א פון זיך) כו' והבה\"ת דטבע הטוב העצמי גורם התעוררות השפעה העצמי' ממקורו וכמ\"ש צדיק כתמר כו' וכמ\"ש"],[2400650182,"במ\"א בענין והאדם ידע כו') ולפי\"ז יובן ג\"כ בענין אור השמש שמאיר מצד עצם המאור של השמש שנק' הארה עצמי' דוקא עז\"נ באור כי טוב שהוא בחי' יסוד ז\"א שמלובש בו פנימית יסוד אבא כו' מטעם הנ\"ל וד\"ל. ומעתה יתבארו פרטי ד' המאמר שמשא קדישא דאיהו משכנא מאינון דרגין עילאין קדישין היינו בחי' מקיפים דג\"ר דחו\"ב שנמשך בבחי' פנימי' יסוד אבא הכל בא ושורה בבחי' יסוד ז\"א כנ\"ל ולכך נק' משכונא בשם אוהל. וז\"ש לשמש שם אוהל בהם לא כמו בבחי' קום שבכל הארץ בבחי' אור מתפשט אלא בבחי' מקיף דאוהל שכולו שם להיותו בבחי' השפעה עצמי' דוקא וד\"ל. ואיהו נהורא דנטיל כל אינון נהורין הוא בחי' יסוד ז\"א שבטבע הטוב העצמיי שכלולי' בו כל מיני טוב וחסד שבכל אורות הנעלמים שבאין לידי גילוי לירד מגבוה לנמוך ולכך מאן דנטיל שמשא שהוא יסוד ז\"א שבו יסוד אבא שהוא בחי' השפעת כל העצמי' ממש ה\"ז כאלו נטל כולא ממש וד\"ל. ומה שמסיים בגין דאיהו אהל דאתכליל בהון ולא א' דאתכלילו בהון כמו ברישא היינו לפי פשט הכתוב דלשמש שם אהל בהם דמשמע שהשמש עשה בהם אוהל לעצמו א\"כ כמו האוהל המקיף לאדם כך המה מקיפים לשמש שהוא בחי' יסוד וז\"ש דאתכליל בהון כאדם המוקף באוהל והענין הוא משום דגם שכל האורות העליונות העצמיים מתכנשין ושורין ביסוד שהוא רק מצד עצם הטוב להשפיע כל עצמותו כו' אבל בחי' השפעה עצמי' הנעלם שבאה מצד עצם המשפיע א\"א שיבא בגילוי או\"פ כ\"א בבחי' מקיף כאוהל כו' אבל מ\"מ שוכנים בו כולם כא' בבחי' אוהל מקיף א' שנעשה מכללותם יחד וז\"ש דאתכליל בהון ונטיל כולא כו' וד\"ל:"],[2400650183,"<h3>והוא כחתן יוצא מחופתו</h3>\n(מד) <b>והוא</b> כחתן יוצא מחופתו. פי' בזוהר וז\"ל ואיהו נהיר בכל אינון גווני נהורין דלתתא וע\"ד והוא כחתן יוצא מחופתו בנהירו ונציצו דכל נהורין גניזין דכולהו בתיאובתא וברעותא שלים יהבי לי' רעותייהו ונהירו דלהון כמה דלחתן אית לי' רעו ותיאובתא דכלה למיהב לה נבזבזין ומתנן וע\"ד והוא כחתן יוצא מחופתו מאן חופתו דא עדן וכמ\"ש ונהר יוצא מעדן ועדן דא איהו חופה דחפיא על כולא ע\"כ. הנה מ\"ש ואיהו נהיר כו' ר\"ל האי שמשא קדישא שהזכיר קודם שהוא בחי' יסוד אבא שמלובש בבחי' יסוד ז\"א כנ\"ל ועז\"א והוא כחתן יוצא כו' דקאי אדסמיך ליה לשמש שם אוהל כו' דאחר ששם אוהל בהם הוא כחתן יוצא מחופתו דא עדן כו' ויציאה זו שיוצא מחופתו הוא להאיר לכל בנין קומת המל' שנק' גוונין נהורין דלתתא שהן ע\"ס דמל' שנק' נהורין דלתתא ודוקא לאחר ששם לעצמו אוהל בהם שהן בחי' מקיפים דאו\"א ששם לעצמו תחלה ואח\"כ יוצא מחופתו להאיר לכלה בחי' המל' ג\"כ מאותן אורות המקיפי' וז\"ש יוצא מחופתו בנהירו ונציצו דכל נהורין גניזין שהן בחי'"],[2400650184,"המקיפים העליונים הנ\"ל ומה שמתחלה כששם וקיבל בעצמו נק' אוהל וכשיוצא להאיר למל' נק' חופתו זהו בחי' מקיף הכללי דאבא כמ\"ש בסמוך דעדן נק' חופה דחפיא על כולא וזהו המשך דברי המאמר בכלל וביאור הדברים מובן מכל הנ\"ל בשרש בחי' יסוד אבא שמסתיים ביסוד ז\"א שהוא בחי' השפעה העצמי' שגם מבחי' המקיפים דג\"ר דאו\"א נמשכים שם אך הן שוכנים במקיף ובהעלם על בחי' יסוד ז\"א שנק' שמשא כאהל כנ\"ל דאעפ\"י שכל בחי' העלם העצמי' כלולים ביסוד ז\"א שהוא בחי' עצם הטוב כנ\"ל אבל בחי' עצמותו כמו שהוא שוכן בהעלם על בחי' עצם הטוב ומה שאח\"כ הוא שמשפיע כל עצמותו מצד עצם טובו להמקבל זהו מ\"ש כחתן יוצא להאיר לכלה מאותן אורות השפעות עצמי' הפנימי' יסוד אבא שמלובש בו ושם לעצמו לאהל תחלה ואח\"כ כשבא להאיר למל' אזי נק' יוצא מחופתו בנהירו ונציצו דכל נהורין גניזין כי בעצמו הי' כל נהורין הגניזין שורים עליה בהעלם בבחי' אהל אך כשבא להאיר למקבל מעצם טובו נהיר בנהירו ונציצו דאור שפע העצמות שבו הי' בהעלם שהרי נק' אור כמ\"ש למעלה והוא בחי' הארת עצמי' שבא מצד טבע הטוב להיטיב כנ\"ל וז\"ש ואיהו נהיר כל אינון גוונין נהורין דלתתא כמ\"ש באורך נראה אור להאיר למל' שנק' הארה דהארה וזהו ההפרש בין אהל לחופה דבהיותו לבד בלא יחוד עם הכלה נק' אהל כי הכל נכללים בו בהעלם אבל כשבא להתייחד עם המקבל נק' חופתו שאז מאיר בו ממקיף הכללי דאור אבא כדי שיוכל להאיר במל' המקבל וז\"ש והוא כחתן יוצא מחופתו בנהירו ונציצו בגילוי הארת מקיפים עליונים הנק' נהורין גניזין והוא ענין המתנן ונבזבזן שא' בסמוך שנק' קישוטי כלה הכל בבחי' מקיפים שקודם היחוד וזיווג כידוע. אך אם לא שם אהל לעצמו תחלה מכל האורות המקיפים לא הי' לו במה להאיר להכלה להיות קישוטים כו' (כמו עד\"מ בלא שפע עצמיי' אין טבע עצם הטוב מועיל למקבל כלום כו') ולפי שהמל' ללמג\"כ ע\"כ איהו דוקא נהיר לכל אינון גוונין נהורין שבה שהן בנין ע\"ס דכל קומת המל' מכל אותן אורות המקיפים ששם אהל בהם תחלה וד\"ל ומ\"ש דכולהו בתיאובתא וברעותא שלים יהבי' לי' רעותייהו ונהירא דלהון קאי על כל בחי' המקיפים העליונים שנק' נהורין גניזין כנ\"ל. וי\"ל לכאורה מה שכפל הדבר דברעותי' שלים יהבי' לי' רעותייהו הרי רעותייהו הוא הרצון וברעותא שלים היינו ברצון טוב ושלים ואיך יתכן לומר שברצון יתנו רצון כו'. אך הנה ילה\"ק ענין הידוע שבכל השפעה יש רצון ותענוג דהיינו שנתנה ברצון ותענוג דוקא וכל השפעה שלא נתנה ברצון ותענוג אינו השפעה ומתנה כלל וכמו יותר משהעגל רוצה לינק הפרה רוצה כו' הרי רצון ותענוג גדול יש"],[2400650185,"במשפיע בהשפעתו בין בשפע חיצוני' בין בשפע פנימי ועצמי' הכל ע\"י התענוג ורצון באו רק שהתענוג והרצון שבהשפעה החיצוני' אין שם מפנימי' ועצמי' התענוג ובהשפעה דעצמי' שם הוא עצמי' הרצון והתענוג ע\"ד דוגמא שפע האב לבנו שהתענוג והרצון עצמי' בשפעו אליו משא\"כ באותה שפע עצמו לתלמידו ואוהבו שאינו בנו גם שבודאי יש לו רצון ותענוג בהשפעתו אבל אינו בא מבחי' פנימי' ועצמי' כ\"כ כידוע ולפי\"ז כמו שיש ב' מיני שפע פנימי' וחיצוני' הנ\"ל ביסוד אבא כך יש ב' מיני תענוג ורצון בהשפעה זו וזה ידוע ענין התענוג ורצון אשר בא בכל משפיע הוא לבד מרצון ותענוג ששייך לאותו שפע מצד עצמו לבד ע\"ד דוגמא שפע צדקה לעני ודאי מתרצה תחלה לכך מצד הרחמנות כפי האופן שנתעורר ברחמים וחסד כך עולה ברצונו להשפיע לו חסד זה אך מה שיש לו רצון ותענוג בהשפעה זו נבדלת היא לגמרי מפרט רצון זה שיש לו בחסד זה מצד הרחמנות רק שהוא מצד הטבע כל המשפיע שאם אין לו תענוג ורצון להשפיע לא יהי' לו רצון לחסד שבשפע זו כלל והוא בחי' היולי כללי לכל מיני שפע בעולם וכמו שנראה בחוש שאם אדם טרוד בצער לא יהי' לו תענוג להשפיע אז הגם שהי' מהראוי לפי טבע עצם טובו לחפוץ בצדקה לעני מפני הרחמנות לא ישפיע ואם טוב לבו בתענוג דבר מה יותר יהי' לו תענוג להשפיע גם למי שלא יהי' חפץ גם בסיבת עצם טובו א\"כ נבדל בערך התענוג הזה שבמשפיע בהשפעתו הרבה יותר מערך עצם מדת טובו להשפיע כו' וזהו הנק' רצון לרצון ותענוג לתענוג היינו אם ירצה ויתענג אם לא ירצה תלוי במקור הרצון והתענוג באופן שיעור המשכתו כמו בכי טוב לבו או להיפוך כו' וד\"ל. וז\"ש דכולא ברעותי' יהבין רעותייהו פי' רעותייהו הוא בחי' הכתרים דע\"ס שהן בחי' המקיפים כמ\"ש כצינה רצון תעטרנו ומקור הממשיך לרצון וכתר זה הוא רצון לרצון ותענוג לתענוג כנ\"ל וז\"ש בתיאובתא וברעותא שלים יהבין לי' רעותייהו שהוא פנימי' התענוג והרצון שבא בכל משפיע להיות מקור לרצונו בהשפעתו כנ\"ל והיינו דוקא בבחי' המקיפים שיורדין כולם בבחי' יסוד אבא שהוא בבחי' שפע עצמי' כמשל שפע האב לבנו שעצמות התענוג נמשך ברצון ותענוג של ההשפעה משא\"כ לזולתו כו' והנה גם בבחי' יסוד ז\"א שנק' עצם הטוב להיטיב למקבל ג\"כ בחי' רעותא שלים אית לי' למיהב לכלה מתנן ונבזבזן שזה רק מצד אור התענוג והרצון לרצון ותענוג שיהי' לו בקירוב ויחוד אח\"כ ע\"כ תאובתא ורעו אית לי' ביותר ויתן לה מתנות ממש לפ\"ע התענוג ורצון שיש לו בשפע דיחודו כן ירבה המוהר (וכן בשכם לפי שחשקה נפשו ביותר בדינה אמר הרבו עלי מוהר ומתן כו') ולפי הנ\"ל היינו"],[2400650186,"לפ\"ע רב עצם טובו להיטיב כן ירבה תאובתא ורעו למיהב לכלה מתנן לפי שכל השפעה נתנה בתענוג דוקא כו' וד\"ל. אך הנה זאת ההשפעה הבאה בבחי' עצמי' מעצמי' דיסוד אבא הנה לזאת כל נהורין גניזין יהבי' לי' ליסוד ז\"א שנק' שמשא רעותייהו ברעותא שלים מבחי' פנימי' ועצמי' התענוג ולפי שבחי' יסוד ז\"א מביא כל ההשפעה העצמי' למקבל ע\"כ לי' דוקא יהבו רעותייהו וכל נהירו דלהון והיינו דמסיים דבריו כמו דלחתן אית לי' רעו ותיאובתא שהוא מצד עצם טובו להיטיב למיהב נבזבזן שהוא מצד גודל התענוג שבא בהשפעה שחוץ לעצמו למקבל כו' כך גם ביסוד ז\"א נמשך כל רצון המקיפים ברעותי' שלים מזה הטעם עצמו לפי שגם בהשפעה עצמי' יש מעצם התענוג כו' והבה\"ת משום דבחי' יסוד ז\"א בא להשפיע כל עצמותו נמשך לו מעצמות התענוג שמלובש במקבל מהשפעה עצמי' דוקא כנ\"ל שיש בזה שפע עצמי' וז\"ש ברכות לראש צדיק וכמ\"ש למעלה דנטיל כולא כו' וז\"ש יוצא מעדן דא חופה דחפיא על כולא להיות סוף הכל להביא אל המקבל ג\"כ בהשפעה עצמי' דוקא כנ\"ל שיש בזה כל עיקר כללות התענוג העצמי' שנשלם רק בהגיע לבסוף ע\"כ הוא נק' מקיף הכללי דחפיא על כולא וכמ\"ש כי על כל כבוד חופה כו' וכמ\"ש במ\"א וז\"ש מחופתו ל' יחיד שכולל כל התענוגי' פרטי' דרעותי' שלים דיהבי' לי' רעותיי' מפני שכללותם יחד נשלם בהאי חופה שע\"י החתן שהוא בחי' יסוד ז\"א דוקא וד\"ל וכל תיאובת' ורעותי' שלים של כולם נכללים בחופה זו מטעם זה וזהו הנק' עדן כללי דחפיא על כולא וד\"ל:"],[2400650187,"<h3>ישיש כגבור לרוץ אורח.</h3>\n(מה) <b>ישיש</b> כגבור לרוץ אורח. פי' בזוהר ישיש מסט' דאור קדמאה דלא אשתכח בי' דינא כלל כגבור מסט' דגבו' ואע\"ג דגבו' איהו דינא שלים כגבור כתי' ולא גבור בגין דאמתיק דינא בחסד ונטיל כולא כחדא בתיאובתא ורעותא שלים וע\"ד לרוץ אורח כד\"א הנותן בים דרך לאשקאה ולאשלמא נהירא דסיהרא בכל סטרי ולמפתח בה אורח לאנהרא לתתא ע\"כ. פי' מסט' דאו\"ק הוא בחי' אור אבא מקור החסדים וע\"כ א' ישיש בחדוה ועונג מפני שיסוד ז\"א כלול מחסדים דאבא וגבו' דאימא כי בחי' ז\"א עצמו כלול מח\"ג דאו\"א וכידוע דאור אבא מצד עצמו הוא בבחי' החסדי' והוא מוח החכ' שהוא קר ולח מיסוד המים כו' ואור אימא בבחי' הגבו' שהרי מוח בינה חם ויבש והוא בחי' דם הוא הנפש כו' (וכידוע דטבע האב לרחם והאם בדין) כמ\"ש דבינה מינה דינין מתערין כו' וידוע דלובן שמן האב ממנו עצמות ואודם שמן האם ממנה בשר וגידים כו' והן בחי' חו\"ג דאו\"א שבז\"א שנק' בן לאו\"א כידוע וע\"כ גם ביסוד ז\"א כלול מחו\"ג דאו\"א דהיינו גופו של השפעת מ\"ד שלו הוא מבחי' החסדים דאבא שהוא ממוח"],[2400650188,"החכ' שטיפה הרוחני' שבמוח שרשה מיסוד המים והלחלוחי' שבמוח אבא כו' והוא נמשך בקרירות כמים ונק' מ\"ד רק ע\"י בחי' הגבו' שבאין מסט' דאימא שהוא הדם כו' הנה מזה בא סיבת השפעת מ\"ד בבחי' חמימו' רשפי אש שזהו מבחי' הגבו' שביסוד שנק' דינין וא\"ז בחי' דין ממש אלא הוא בחי' גבו' ברשפי אש התגברות החום הטבעי אשר ע\"כ יורד שפע המ\"ד בהתגברות גדולה דהיינו במרוצה מצד החום (וכמו שבכל מקום שיורד בהתגברות נק' גבו' כמו גבו' גשמים שיורדין בגבו' אלא שזהו גבורה שבחסד וכן הוא בחי' יסוד האש שבחום הטבעי שבא מצד הדם כו') והיינו לרוץ אורח שירוץ במהירות כמשי\"ת וסיבת המרוצה אינו רק מצד התאוה שהיא החום וכידוע שאם לא הי' החום לא הי' מוליד כלל לפי שאינו יורה כחץ וכל שאינו יורה כחץ אינו מוליד ולכך נק' יסוד בשם קשת המורה חיצים כידוע. ואעפ\"י שגופו של השפעה הוא מבחי' החסדים דחכ' לא הי' מוליד בלתי שיתוף בחי' הגבו' שביסוד וכל תולדה הוא בחי' כח ההתפשטות יותר והוא כמו בחי' הגבו' שבחסד ולזה א' כאן על בחי' גבו' שביסוד שאינו בחי' דין ממש אלא הוא בחי' גבו' ממותקות בחסדים שהרי מכחם דוקא מוליד וענין ההמתקה זו היא ביסוד דוקא ששם נמתקין גבו' דאימא בחסדי' דאבא. וז\"ש ישיש מסט' דאו\"ק שהיא בחי' חסדי' דאבא שזהו גופו של שרש המ\"ד שביסוד דלא אשתכח בי' דינא כלל וע\"כ אמר ישיש בחדוה ועונג שאין שם בחי' דין כלל. ומ\"ש כגבור מסט' דגבו' היינו מבחי' גבו' דאימא חם ויבש שבא ביסוד בחמימות התאווה כנ\"ל עד שיורה כחץ ומוליד כו'. ולזה מפרש דאע\"ג דגבו' דאימא דאיהו דינא שלים בלא תערובות חסד כלל כי מבינה מינה דינין גמורין מתערין כו' כמו הכעס והרציחה הכל מן רשפי אש הדמים שהוא התגברות החום אבל כגבור כתי' ולא גבור בגין דאמתיק דינא בחסד. פי' שבבחי' יסוד נמתקו הגבו' דאימא בחסדי' דאבא. וז\"ש ונטיל כולא כחדא דקאי על בחי' יסוד דנטיל כולא כחדא חו\"ג דאו\"א בתאובתא ורעותא שלים כו'. ויש להבין שהרי סותר דבריו מן הקצה כו'. בתחלה א' מסט' דאו\"ק דלית ביה דינא כלל. ואח\"כ אמר מסט' דגבו' דינא שלים ואם לפי דאמתיק דינא בחסד איך א' ישיש בלא דין כלל ומהו כגבור אם בחי' הגבו' היפוכו ממש וכו'. אך הנה ילה\"ק ענין א' הידוע שיש בתענוג התכללות מחו\"ג ונק' אמ\"ר אש שבתענוג הוא בחי' הגבו' רשפי אש התלהבות שבתענוג כמו התענוג שבא בהתפעלות יתירה מבשורה טובה מאוד כמו מציאת ממון רב או גדולה יתירה או מבנו הנולד או בשמחת חתונתו שהוא בתענוג המורכב מיסוד האש בהתלהבות אעפ\"י שהוא בחדוה ג\"כ מצד עצם דבר הטוב שהוא מבחי' החסדים"],[2400650189,"שבתענוג שנק' מים והוא כמו שעשועי האב לבנו או לאוהבו הנאמן וכן בהשתעשע החתן עם הכלה לאחר הנשואין שהוא בטוב לב וישיש ויגיל בה הנה זהו מבחי' המים שבתענוג וכן לאחר שיש לו הון רב וכבוד שמשתעשע בהן שכ\"ז בחי' התפשטות החסדים שבתענוג כמו הטיול והמנוחה וכה\"ג כל תענוגי העוה\"ז המושכים את כל הנפש אחריהם עד שתדבק בהן לגמרי שנק' אהבה בתענוגים כמו אהבת האיש לאשתו שלא בשעת היחוד אך אהבה בתענוגים שבשעת היחוד הבאה ברשפי אש התלהבות שנק' חמדה ותאוה כמו חמדה שיחמוד אדם בלבו לכל דבר טוב ותענוגי עוה\"ז זהו בא מבחי' אש שבתענוג ועד\"ז יש כמה מיני התפעלות בתענוג המורכבים מחו\"ג אש ומים והוא בחי' רוח כמו התענוג ברוח גבוה כו' בהתנשאות והתפארות וניצוח וגם התאוה למשגל וממון ומאכלי מעדנים ולבושים נאים ודירה נאה והרחבת ההנהגה וגם בתאוות הממשלה והגדולה או שיהי' הכל משבחי' אותו וכה\"ג הכל מורכב מכמה אופנים שונים מאמ\"ר שבתענוג (ודרך כלל רמזו במ\"ש ג' דברים הקנאה והתאוה והכבוד קנאה מתגבורת אש שבתענוג תאווה להמשיך כל הנפש כמו ותדבק נפשו בדינה מים שבתענוג והכבוד רוח שבתענוג כו' וכמ\"ש במ\"א). וכמו\"כ יובן שיש בתענוג רוחניי שבטיפה רוחני' שמתהוה במוח הרכבה מאמ\"ר שבתענוג מים שבטיפה בא מבחי' מים שבתענוג והוא בחי' חסדי' שבתענוג שהוא המשכות כל הנפש ומזה יבא המשכת העונג המורגש במוח שעיקרו מבחי' החסדים בחלקי המים שבמוח ובחי' אש המורכב בה הוא מבחי' הגבו' שבתענוג והוא התפעלות העונג המורגש במוח בהתלהבות ובחי' רוח שבה הוא הממוצע הכוללם יחד. ואמנם בחי' החסדים שבתענוג גוברים על בחי' הגבו' שהרי מ\"ד נק' בשם מים רק שמורכב בהן בחי' הגבו' מאש שבתענוג ולא בבחי' עצמי' אשר ע\"כ רק סיבת המרוצה של המ\"ד בא מכח האש שבתענוג וגם סיבת התולדה שהיא ע\"י החום שיורה כחץ עיקרו מצד החסדים רק שנמשך בחום והוא כמו חום השמש שמגדל כל תבואה כמ\"ש במ\"א. והתולדה בעצם בא מבחי' הרוח דוקא כי רוח יזרעו רק שא\"א בלי חום כו'. וזה החום מתגבר בהגיע המ\"ד ביסוד לאחר בישול המ\"ד שלזה נק' קשת ושרשו במוח הדעת שאין קישוי אלא לדעת ולכך משמש מת בעריות פטור אעפ\"י שגופה של זרע נשפע כו' וכמ\"ש במ\"א וד\"ל. ונמצא מובן הדוגמא מכ\"ז באור הזרוע לצ\"ע בחי' יסוד שעז\"א ישיש בחדוה שהוא בעונג מורגש שבחי' החסדים שבתענוג הרוחני שבמוח שרשו בלא דין וגבו' כלל רק עצם התענוג המושך את כל הנפש אך החדוה יש בה התפעלות מסט' דגבו' אש שבתענוג המורכב בטיפה והיינו כגבור דאיהו דינא שלים בחי' אש התלהבות ממש אבל בהגיע השפע"],[2400650190,"מ\"ד ביסוד שנמתקו הגבו' שבתענוג בחסדים והוא עיקר התגברות התענוג אשר בכלות השפע דוקא (כמ\"ש במ\"א בענין ותאלצהו) שנק' ששון וז\"ש ישיש ביסוד דוקא וגבו' שביסוד הוא רק התגברות החסדים שבתענוג מכח בחי' הדין דוקא שנהפך לחסד שמוסיף כח חמימות התאווה בחסדים להיות הולכין ונשפעין במרוצה גדולה ולהיות יורה כחץ וע\"כ נק' גבו' ממותקות כמרירות וחריפות הנמתק במתיקות שאז נק' עריבות כידוע. וגם מה שניכר ומורגש בהתפעלות והתלהבות התענוג הוא כלול הכל בבחי' החסדים לא ניכר בבחי' הדין וכעס רק לגבי המנגד שמונע השפע בעת ההיא דוקא כמ\"ש כד ארי' ואריותא קיימין וויי למאן דעבר בינייהו ולהפסיק ביניהון והוא מבחי' הגבורה שביסוד (והוא דוקא בכלות השפע ביסוד אז בחי' הגבו' ודינין לגבי המנגד בדינין גדולי' עד שיבא לכלל קיצור הנפש כמו ותאלצהו בגמר ביאה נשמטה כו'. וכה\"ג יש בבחי' חולת אהבה בתענוגים בתחלה כשלא יוכל לפעול גודל המשכת נפשו וחמדת לבו כמו מעשה בא' שהעלה בלבו טינא כו'. וזהו ג\"כ מבחי' הגבו' ודינין שבתענוג שמצד ההיפוך [לפי] שלפ\"ע גודל התענוג כן יגדל הצער במונעו רק שבסוף ניכר בו יותר כו') וז\"ש נטיל כולא כחדא בתאובתא מבחי' אש שבתענוג ורעותא שלים בבחי' החסדים שבתענוג שנכללים כא' ביסוד דוקא וזהו ישיש כגבור שאם לא בחי' הגבו' שבתענוג לא הי' הששון שהוא בחי' התפעלות יתירה המורגש בתענוג רק שהוא בבחי' התגברות החסדים דתענוג ובחי' הגבו' שבתענוג נמתקים בו. וזהו כגבור ולא גבור כמו במונע המנגד שהוא דינא שלים אלא דאמתיק דינא בחסד כו' וד\"ל:\n(מו) <b>וע\"ד</b> לרוץ אורח כד\"א הנותן בים דרך כו'. פי' בא לפרש בעיקר הטעם דישיש כגבור שהוא רק כדי לרוץ אורח דהיינו בשביל המשכת השפע למקבל בחי' נוק' שהרי כל עיקר תאובתא דדכורא להשפיע אינו רק לנוק' דוקא ובלא נוק' כשהוא לעצמו אינו מתעורר בתענוג להשפיע מ\"ד כלל וכלל וכן בשפע אור שכל וחכ' מרב לתלמידו שאם אין מקבל אינו רוצה להתעורר ברצון ותענוג להשפיע חכ' כלל רק כשימצא מקבלים טובים יתפעל בלבו ומוחו להשפיע כו'. וזה הענין פלאי הוא לכאו' שהרי באמת יש מציאות עונג מורגש בהתפעלות יתירה מצד גופו של השפע מ\"ד כשנשפעת הטיפה רוחני' וגשמי' שבמוח לעצמו כו'. גם בלא תאובתא ותענוג להשפיע להמקבל רק שאינו מתעורר התענוג דהשפעת מ\"ד זה רק בשביל מקבל שהוא הנוק' וכשהוא לעצמו אינו מתעורר בתענוג כלל וכלל. ושרש הדברים שיש בזה ב' ענינים עונג הא' עונג הנמצא במציאות מורגש ביותר בעצם השפע מ\"ד מצ\"ע לבד גם בלא מקבל (שהרי גם בלא הרהור בנוק' כלל ימצא תענוג במציאות טיפה רוחני'"],[2400650191,"במוח הגשמי' כמו הקרי הנמצא מחום הדרך או שאר חום מאכל ומשקה וכה\"ג כידוע). אמנם הוא עונג גשמי' המורגש ביותר שבא מצד הגשמת הנפש בחום הטבעי במאכל ומשקה כו'. אבל רוח התעוררות התענוג שבמשפיע להשפיע מ\"ד בשביל המקבל דוקא ובלא זה לא הי' לו תענוג כלל בעצם השפע זהו עונג הב' הנק' עונג רוחני והוא אשר ימצא בכל משפיע התעוררות התענוג להשפיע שפעו למקבל דוקא והוא המוטבע בכל בריאה שיהי' לו אותו עונג כמו הפרה רוצה להניק כו'. (והיינו ענין הנ\"ל באות מ\"ד) שבכל משפיע מוטבע כח התענוג להשפיע מלבד התענוג השייך לאותו השפע מצד עצמו כמו שפע צדקה לעני שיתענג בשפע זו מלבד התענוג שמתייחס לעצם השפע להחיות לעני כו'. ואם טרוד בצער לא יהי' לו תענוג זה להשפיע ונק' תענוג לתענוג כו'. וכך הוא בהתעוררות התענוג להשפיע לנוק' אם הוא בצער לא יתעורר בתענוג זה כלל לפי שהתענוג הזה להשפיע הוא נבדל מעצם השפע שמתענג במורגש כו'. ע\"כ תלוי בעת טוב לבו שנתעורר בתענוג זה אם מעט או רב כו'. ונמצא מובן מזה בבחי' טבע הטוב להטיב ג\"כ יש בטבע זו עונג להיות משפיע טוב מלבד העונג שבשפע זו מצד עצמו כמו שפע שכל וחכ' עמוקה לתלמיד שמטבע הטוב הנק' משפיע שיהי' לו תענוג להשפיע אור החכ' בראותו תלמיד מבין שיוכל לקבל בכי טוב מלבד שיתענג בשפע השכל מצד עצמו לבד שיש בכל שכל תענוג כידוע ע\"כ לא יתעורר תענוג במשפיע כ\"א כשיש מקבל דוקא אבל לזה העונג המתייחס מצד השפע אור שכל עצמי א\"צ למקבלים כלל כו'. וכך יובן הדוגמא במה שנק' בלשון המקובלים בחי' יסוד שהוא הנק' משפיע טוב למקבל שאור התענוג שיש לכל משפיע להשפיע אינו רק בשביל המקבל דוקא כנ\"ל בתאוות ההשפעה דדכר לנוק' כו'. ומכ\"ז יובן בבחי' צדיק וטוב העליון שנק' משפיע הרי התענוג העליון שבהשפע' הטוב העליון הוא הנבדל מעונג השייך לעצם השפע ועז\"א ישיש כגבור לרוץ אורח דעיקר התענוג דישיש כגבור הוא תענוג העליון הנבדל מעונג שבשפע זו שמצד עצמה והוא רק כדי לרוץ אורח בשביל המקבל שהוא בחי' מל' שרש כנס\"י למעלה שעיקר התענוג בטבע הטוב הוא להטיב דוקא למקבל ולא בשביל עצמו כו'. וז\"ש תחלה ונטיל כולא כחדא בתאובתא ורעותא שלים שהוא התשוקה להשפיע למקבל שזהו מטבע הטוב שנק' בחי' יסוד כו'. וע\"ד לרוץ אורח דוקא שכל המרוצה בהשפעתו במהותו הוא רק למקבל דוקא שנק' אורח וד\"ל. ומ\"ש כד\"א הנותן בים דרך כו'. הנה ידוע דהמל' נק' ים. וכמ\"ש כל הנחלים הולכים אל הים שהים מתקבץ מכל הנחלים ונק' בחי' מקבל מכל שפע מים רבים שבנהרות שיוצאים מג\"ע הארץ"],[2400650192,"כידוע. וכתי' הנותן בים דרך דהיינו מקום מעבר כניסת ההשפעה ששופע והולך מכל הנהרות בים נק' דרך בים (כי מי הים מים מכונסין המה ואשר יקרא בשם דרך בים הוא הילוך כניסת שפע מי הנהר שהולכין בים כנהר קטן שנמשך בנהר גדול שבוקע הילוך שלו ונבדל משאר המים שבנהר) ובאמת הכוונה הוא על קי\"ס שנתן בים דרך לעבור בו ביבשה והוא בחי' גילוי דיבשה בתוך הים עלמא דאתכסי' שעשה מן ההעלם גילוי כמשי\"ת. ולפי\"ז דרך זה מן המשפיע בא במקבל והוא ענין כניסת האור ושפע של המשפיע שנק' גבר במקבל שנק' ים והוא בחי' השפעת הילוך אור השפע דז\"א במל' שנק' עלמה וכמו דרך גבר בעלמה דעלמה הוא בחי' המקבל השפע ודרך גבר הוא כניסת והילוך אור השפע דמשפיע שנק' גבר כך דרך גבר דז\"א במל' שנק' עלמה כו' ומזה מביא דמיון לפי' לרוץ אורח דכאן שזה בחי' שפע אור דמשפיע למקבל עז\"א לרוץ אורח א\"כ אורח זה היינו כמו דרך גבר כו'. ודרך בים שהוא דרכו והילוכו של השפע דמשפיע ולא של מקבל דהיינו בחי' שפע דיסוד ז\"א ולא של בחי' המל' וע\"ז מדקדק הזוהר עוד דא\"א לומר דאורח זה קאי על בחי' שפע דיסוד ז\"א שהרי יש סתירה גדולה לזה ממה שמצינו בכ\"מ דאורח הוא בבחי' הנוק' דוקא. וכמ\"ש בזהר במ\"א בהפרש שבין דרך לאורח שהדרך הוא בדכורא וארח הוא בנוק' כידוע. ואיך יפרש כאן לרוץ אורח בדכורא ולזה מפרש דבריו לתרץ לזה במ\"ש כד\"א הנותן בים דרך. ולאשקאה ולאשלמה נהירו דסיהרא בכל סטרין ולמפתח בה ארח לאנהרא לתתא ע\"כ. כוונתו במאמר זה לומר דאע\"ג דאורח זה מתפרש על בחי' שפע דיסוד ז\"א כמו הנותן בים דרך כנ\"ל עכ\"ז אורח זה בבחי' הנוק' והוא לאשלמא נהירו דסיהרא ולמפתח בה אורח לאנהרא לתתא הרי האורח הזה נפתח בנוק' לאנהרא לתתא בבי\"ע כי כל אורח בנוק' הוא אבל עכ\"ז לרוץ אורח זה קאי ביסוד ז\"א רק שהוא למפתח בנוק' אורח. ולפי\"ז גם הנותן בים דרך יתפרש באופן זה ג\"כ שנותן בים דרך דהיינו במקבל למפתח בה אורח שהרי ממנו מביא ראי' לפי' ירוץ אורח דכאן דהיינו שבתוך הים נותן דרך ולא אל הים שהדרך אל הים היינו כנ\"ל בפי' דרך גבר בעלמה שהוא דרך המשפיע בתוך המקבל ובלרוץ אורח מפרש למפתח בה אורח א\"כ הנותן בים דרך היינו ג\"כ שבתוך הים עושה דרך ונק' דרך של הים ולא יפלא מהיכן יוכל להיות דרך בים עז\"א הנותן בים דרך שהמשפיע הוא העושה זה שהוא הנותן בים דרך זה אבל דרך זה לנוק' הוא שייך כו' וד\"ל. וביאור הדברים ידוע דהמל' ללמג\"כ רק מה שנותן לה המשפיע שהוא בחי' ז\"א דאצי' עד\"מ מאותיות הדיבור שכל המדות והשכל מתגלים בדיבור והכל הולך אחר הפה כמו כל הנחלים הולכים אל הים"],[2400650193,"והים כו'. שהדיבור בית קיבול להכיל הכל. וכמ\"ש בס\"י וקבען בפה כו' כך כל האורות דמדות דאצי' מתגלים בדיבור העליון אך גם בחי' הדבור הוא בבחי' אלקו' ונק' דבר אלקים ולא הי' נמשך מדיבור העליון השתלשלות עולמות מאין ליש. ולזה צ\"ל בחי' המשכה מיוחדת מן המשפיע שיהי' נפתח פתיחת אור השפע לעולמות דבי\"ע מבחי' אותיות דיבור העליון שיאיר אור המל' בבי\"ע ומי הוא העושה הכח הזה במל' שיהי' נק' מאמר פתוח להאיר למטה בבי\"ע בע\"מ וכה\"ג. הנה ז\"ש הנותן בים דרך שדרך זה שנמשך השפע ממל' דאצי' בבי\"ע המשפיע שהוא בחי' ז\"א הוא הנותן בה דרך זה וכן לרוץ ארח למפתח בה אורח זה לאנהרא לתתא והיינו כמו בקי\"ס שעז\"א הנותן בים דרך הרי בעלמא דאתכסייא שהוא מאמר סתום בחי' המל' כמו שמקבלת לעצמה בבחי' האצי' נפתח בה בחי' דרך כיבשה ממש שנק' עלמא דאתגלייא מאמר פתוח וכמ\"ש תוצא הארץ תדשא הארץ כו' שזהו מבחי' יבשה דוקא. וכמ\"ש בזוהר בראשית בפי' ותראה היבשה שנק' ארץ דאפיקת תולדין כו'. והרי מי עשה מבחי' ההעלם שבמל' בחי' גילוי ה\"ז בא דוקא מאור המשפיע שהוא ז\"א שהפך ים ליבשה כו'. וזהו ג\"כ ענין לרוץ אורח למפתח בה אורח לאנהרא לתתא בבי\"ע כנ\"ל וד\"ל:\n(מז) <b>אך</b> הנה עדיין אינו מתיישב לנכון דברי המאמר הזה מאחר שהביא דמיון לפי' לרוץ אורח דכאן ממ\"ש הנותן בים דרך א\"כ לכאורה לפי' הנ\"ל הרי דרך וארח זה שניהם בנוק' הוא רק שהנותן דרך וארח בנוק' הוא הדכר וכמ\"ש הנותן כו' ולרוץ אורח כו'. והיינו בחי' יסוד ז\"א שהוא הנותן דרך בנוק' וגם אורח כו'. ולפי\"ז הדרא קושי' לדוכתי' שהרי מבואר בזוהר במ\"א שההפרש בין דרך לאורח שהדרך בבחי' דכר וארח בבחי' נוק' (כי דרך ל' זכר כמו בדרך אחד כו' ובארח נא' וארחות ה' ובדרך נא' דרכי ה' כו' וכה\"ג). ולפי\"ז אין ההפרש בין דרך לארח ששניהם בנוק' רק שהמשפיע נותן אותם כו'. אך הנה להבין אמיתי' הענין הזה ילה\"ק תחילה ביאור ענין ההפרש שבין דרך לאורח המבואר במ\"א בזוהר והוא שבחי' הדרך הוא דרך הכבושה לכל עובר ושב שכבר נכבשה לרבים ועוברין בה הכל כמו דרך כבושה שהולכין בה רבים מעיר לעיר תמיד והתחברות אנשי מקום זה עם אנשי מקום זה הוא ע\"י דרך הכבושה דוקא שהולכין ושבין בה תמיד (ויכולים גם שאר הרחוקים לכוין הילוכם מעיר לעיר עד בואם למקומם משא\"כ האורח ושביל שמעיר לעיר לא נודע לרחוקים כלל) אבל האורח הוא השביל הקצר שאינו דרך כבוש לרבים רק הולכים בה אנשים לפרקים ועיתים רחוקים כי אינה כבושה עדיין לרבים ואין עוברין בה הכל רק ליחידים שידוע להם. וגם זאת לפרקים כארח הבא לפרקים ועיתים רחוקים. וכמ\"ש נשמו"],[2400650194,"מסילות שבת עובר אורח כו'. והדוגמא מזה יובן למעלה בהפרש שבין דרך לאורח בבחי' מל' דאצי' ג\"כ כשנק' דרך היינו בחי' דרך הכבושה לרבים שהוא בחי' הילוך והשתלשלות אור השפע האלקי' בתמידות ממל' דאצי' לבי\"ע כמו לחדש מע\"ב בכ\"י לכל עולם ועולם לפ\"ע לנשמות בג\"ע דבריאה ולמלאכים ביצירה עד גלגלים דעשי'. וכמו כן עולין בדרך כבושה הנ\"ל מלמטה למעלה כמו בכל חדש ושבת כו'. וכן בכ\"י יש עליות העולמות מעשי' ליצי' כו'. כמו שבדרך הולכין ושבין הכל. וכך כל אור אלקי שבמל' דאצי' הולך ונמשך וכל נברא עולה למעלה כו' וזהו הנק' דרך כבושה לרבים אבל בחי' אורח הוא לפרקים שאין עוברים בה הכל דהיינו שלא בכל פעם מאיר אור המל' בבי\"ע רק לפרקים ועתי' רחוקים כמו בשבת ויו\"ט ובכ\"י בק\"ש ותפלה וכה\"ג שנק' ארח דמל' לפרקי' ורק בחי' אור פרטי שבאצי' ודוקא בר\"ח ושבת וג' מועדים וכה\"ג (וה\"ז כמו יחידים שבעיר שהולכין בארח זה הידוע להם שאין נודע לרוב העולם ואין הולכים בה הרחוקים כלל כו') וזהו עיקר ההפרש שבין דרך לארח והכל בנוק' שהוא בחי' המל' דאצי' והיינו הנותן בים דרך ולרוץ ארח שדרך וארח זה הכל בנוק' בחי' המל' דאצי' והמשפיע שהוא בחי' יסוד ז\"א נותן במל' ב' מדרגות הללו דרך וארח הדרך היא הכבושה לרבים שבמל' בבי\"ע והארח שבה הוא מה שתאיר לפרקים. אך עדיין אין הקושיא דלעיל מתורצת דא\"כ למה הדרך בבחי' דכורא מאחר שגם בחי' דרך הכבושה היא במל' שמאיר בבי\"ע מהו ההפרש בין דרך לאורח שניהם בנוק' רק שהדרך תמיד כבוש לכל והאורח לפרקים כו'. ואמנם באמת בחי' דרך שבנוק' היינו בחי' דכר שבנוק' עצמה והוא בחי' מ\"ה דב\"ן משא\"כ אורח הוא בבחי' נוק' לבד ושניהם באו מכח המשפיע שנותן במל' דרך בחי' דכר שבה ובחי' אורח כו'. ולהבין ביאור זה ילה\"ק ענין א' המבואר בפי' אמת ואמונה כל זאת וקים עלינו כו'. ולמה אמר קיים לשון זכר מאחר שמתחלה א' כל זאת לשון נקבה. והענין הוא להיות ידוע בפי' כי הוי' הוא האלקים דקאי הכל בבחי' המל' ויש בזה ב' פירושי' הא' דאלקים זה הוא כמו שהמל' בחי' מקבל מז\"א לעצמה תחלה בבחי' האצי' ממש ונק' בחי' אלקים לגבי שם הוי' דז\"א וכמ\"ש כי שמש ומגן הוי' אלקים דאלקים הוא בבחי' צמצום דבחי' המקבל בעלותו לקבל משם הוי' דז\"א כמשל תלמיד היושב לפני רבו לקבל שפע לעצמו דאיידי דטריד למבלע לא יוכל לבא בבחי' התפשטות לגבי התחתונים הימנו במדרגה להשפיע להם מה ששואלים ומבקשים ממנו אך לאחר שכבר קיבל לעצמו במילואו אז יוכל לבא בבחי' התפשטות בהשפעה למקבלים ממנו ונק' משפיע לגבי המקבלים אבל באמת מה שהי' תחלה בחי' מקבל"],[2400650195,"וטרוד למבלע לעצמו הוא יותר גבוה במדריגה הרבה ממה שנעשה בחי' משפיע אחר שקיבל לעצמו וע\"ד שא' הוי זנב לאריות ואל תהי ראש לשועלים דמה שהוא טפל לאריות הוא יותר גבוה ממה שהוא ראש לשועלים וכמ\"ש במ\"א בענין ד\"ו פרצופים כו' דבהיות המל' בחי' נקודה תחת יסוד שנק' ד\"ו כו' הוא יותר גבוה ממה שנבנית אח\"כ בבנין שלם בבחי' ראש לשועלים להחיות בע\"ג דבי\"ע כו' (אך מ\"ש בזוהר ע\"פ שחורה אני ונאוה דאזעירת גרמה כנקודה וגבורי כח עושי דברו הוי כמלקדמין זהו בבנין שלם בבחי' אצי' להיות בבחי' פב\"פ באצי' שהוא למעלה מבחי' נקודה שבה באצי'. ונמצא ג' מדריגות יש. א' בחי' המל' בבי\"ע להיות ראש לשועלים. ואז נק' אימא תתאה או מטרוניתא כתר מל' שבבריאה. והב' בחי' כתר דמל' באצי' שהוא בבחי' אצי' בבחי' נקודה וכמו ענין אזעירת גרמה כו' וכמ\"ש בע\"ח בפי' לעולם ה' דברך נצב בשמים כו' בחזה דז\"א שדבוק שם בחי' כתר מל' שנק' דברך כו'. והג' כשניבנית בפרצוף שלם באצי' כו'). והנמשל מזה יובן ג\"כ בבחי' מל' דאצי' שכמו שהיא למעלה באצי' בבחי' מקבל לעצמה (והיינו בחי' ה\"ג שמקבלת לצורך בנין עצמה כו') הוא למעלה הרבה ממה שמתצמצמת להיות כתר לבריאה שנק' מטרוניתא או אימא תתאה שהוא בחי' משפיע בחי' דכר וז\"ש כל זאת בחי' מקבל כמו שנק' אלקים באצי' ואח\"כ נשפלת למטה להיות כתר וע\"י דבריאה אז הוא בבחי' דכר משפיע וזהו וקיים לשון זכר והיינו פי' כי הוי' הוא האלקים בחי' הוי' שבמל' הוא בחי' דכר שבה בהיותה נק' משפיע בבי\"ע ועולה המל' בבחי' אצי' להיות בחי' אלקי' לגבי ז\"א בחי' מקבל כי מה שנק' הוי' בחי' משפיע לגבי העולמות הוא למטה הרבה לגבי עצם מדריגתה כמו שמקבלת לעצמה למעלה בבחי' האצי' כמובן ממשל התלמיד לפני רבו הנ\"ל וזהו שלפעמים נק' המל' נו\"ן כפופה שכפופה לקבל (והוא בחי' ה\"ג שלצורך עצמה כו') ולפעמים נק' נון פשוטה כשמתפשטת בעולמות (והיינו בחי' ה\"ג שלצורך בנין העולמות כמ\"ש במ\"א בענין כוס של ברכה דיתבא על ה' אצבעין בכף היד שכפוף לקבל בה' אצבעות כלפי מעלה ובהיותה בחי' משפיע הרי נא' אף ידי יסדה כו' כמו שפועל אדם בה' אצבעות או כמו שפושט ידו לעני להשפיע שפושט כף ידו) להשפיע והפי' הב' בהוי' הוא אלקים להיפוך דבחי' הוי' שבמל' בחי' משפיע למטה שרשו באלקים דז\"א שלמעלה מבחי' אלקים דמל' בהיותה בבחי' מקבל כי מה שנותן לה המשפיע הכח להיות משפיע למטה בבי\"ע גבוה הרבה ממה שנותן לה כח לקבל לעצמה ויובן זה ממ\"ש במ\"א בפי' ההופכי הצור אגם מים כו' אין צור כאלקינו שהוא בחי' צמצום דמל' בהיותה בבחי' מקבל באצי'"],[2400650196,"ובשעת היחו' דזו\"נ נמתקו הגבו' דנוק' ונהפכו לחסדים ע\"י התגברות בחי' חסדים דז\"א כמ\"ש כי גבר עלינו חסדו ואז נעשה המל' אגם מים מקור החסדים להחיות רוח שפלים דבי\"ע דבאמת זהו היפוך טבעה שאל אישה תשוקתה לעלות באצי' לקבל ונהפך טבעה להיות בבחי' מי החסדים ולירד דוקא ולהשפיע לבי\"ע וזה בא במל' מכח החסדים שמתגברים בז\"א כמ\"ש ההופכי הצור דאלקים להיות אגם מים להשקות כו' דאתבסמת נוק' כו' וכמ\"ש במ\"א. וז\"ש כי הוי' בחי' חסדים שבמל' נעשו מגבו' דאלקי' דז\"א שנהפכו לחסדים שנק' גבו' שבחס' כמ\"ש כי גבר עלינו חסדו כו' (כמו גבו' דאבא נעשו חסדים דאימא וגבו' דאימ' נעשו חסדים דאבא כו' כידוע). ובזה יובן גם כאן ההפרש שבין דרך שהוא בחי' דכר שבנוק' מ\"ה דב\"ן היינו בחי' החסדים שבמל' להיות אגם מים וכמ\"ש והוכן בחסד כסאו עולם חסד יבנה כו' דהגם שבנין המל' עצמה למעלה הוא מבחי' הגבו' דז\"א דוקא שתוכל לקבל כמ\"ש תנו עוז לאלקים כו' וכידוע דאין אשה כורתת ברית אלא למי שעשאה כלי בביאה ראשונה בה\"ג דדכורא מבחי' אלקים דז\"א והוא בחי' ארח שהוא לעשות בית קיבול דיסו' דנוק' כמ\"ש באר חפרוה כו' ואמנם מה שנעשי' אח\"כ בחי' משפיע למטה כמ\"ש אשה כי תזריע וילדה כו' וכה\"ג הוא בחי' דרך שבנוק' שנק' דרך כבושה שנכבשה ע\"י האיש דהיינו בחי' התגברות חסדים דדכו' וז\"ש הנותן בים דרך שיהי' עובר כל שפע ממל' דאצי' לבי\"ע מבחי' יסוד שבה וזהו למעלה מבחי' אורח שהוא בחי' נוק' לחוד ואעפ\"י שא' דאפתח בה ארח לאנהרא לתתא ג\"כ אך זהו לפרקים כמו בשבת ויו\"ט כנ\"ל והיינו כפי' הב' דלעיל דלפי' הא' אורח למעלה מן דרך כנ\"ל:\n(מח) <b>ולהבין</b> בתוס' ביאור ענין דרך ואורח הנ\"ל (באופן אחר) ילה\"ק תחילה ענין המבואר בע\"ח בביאור המאמר דמל' ללמג\"כ כו' דבחי' ה' ספי' הראשונות שבמל' מאירות תמיד מאור דז\"א וה' ספירות האחרונות לפעמים מאירות מאור דז\"א ולפעמים אינן מאירות כו' ע\"ש וביאור הענין הנה ידוע דהמל' נק' סיהרא וז\"א נק' שמשא וכמו שהלבנה מקבלת מאור השמש כך בחי' המל' מקבלת מז\"א שנק' שמשא כמו דסיהרא ללמג\"כ רק מה שמקבלת מאור השמש כך המל' לית לה מגרמה כלום רק מה שמקבלת מז\"א כמ\"ש כי שמש ומגן הוי' אלקים כו' כידוע. והנה ידוע סוף דעת חכמי התכונה האחרונים באופן הילוך השמש והלבנה (בס' נחמד ונעים) שמסיבת אופן מהלכם וסיבובם כך יהי' אופן שינוי שבלבנה במלואה ובפגמה וכן בזמן ליקוי הלבנה מחמת צל הארץ בהעדר אור השמש עליה כי הוחלט הדבר שהלבנה אינה בעצם מהותה בחי' אור ומאיר כלל וכלל גם"],[2400650197,"לא עצם חשוך אלא עצם ספירי אבל אינה אור מאיר לזולתה כלל וכמו שרואין אותה בשעת ליקוי' מפני צל הארץ שנשארת בעצם מראיתה שהוא אדום ואמנם בלתי תבהיק אור וזיו מתפשט כלל והוא אורה העצמי אך מה שתאיר ותבהיק אור המתפשט בארץ א\"ז מאור עצמותה כלל רק אותו האור וזיו של השמש שמאיר בעמדו למולה במהותה העצמי הוא אשר זורח על הארץ וא\"כ אין אור זה שתאיר הארץ רק דרך מעבר עבר בה מאור השמש כמו באור העובר דרך מעבר בזכוכי' בהירה אך א\"כ לא הי' באור זה השתנות כלל מגוף אור השמש המאיר ביום אלא מוכרח לומר שנשתנה הארת השמש בעברו בכלי כדור הלבנה שאינה רק עצם ספירי אדום כו' ולא השתנות גמורה רק שאין האור צח כ\"כ כמו שעבר דרך מסך זך וכה\"ג וז\"ש בזוהר דסיהרא ללמג\"כ שאין הכוונה שאין לה אור עצמה כלל שהרי היא עצם אור ספירי רק שאין לה אור המאיר ומתפשט רק מהאור שקבלה מהשמש הוא המתפשט דוקא ואור זה אינה מאור עצמותה כלל. ובמ\"א מבואר שיש בחכמי התכונה שגוזרי' אומר דהלבנה הוא אור משפיע אור עצמותה על הארץ רק שא\"א לה להאיר כ\"א כאשר קבלה בעצמה אור השמש תחילה ואמנם האור המאיר על הארץ הוא מאור הלבנה דוקא ולזה נשתנה אופן אור הלבנה מאור השמש כי אין זה אור השמש כלל גם לא בדרך הארה דהארה כע\"י מסך כו' (והיינו כמו האשה שמקבלת המ\"ד ואח\"כ תלד מכח עצמה כמ\"ש אשה כי תזריע וילדה כו' וכן הארץ תצמיח מכח עצמה אחר שמקבלת את הגשמים וחום השמש ומזל הרוחני כו'. ולפי\"ז מ\"ש דסיהרא ללמג\"כ היינו רק כח התולדה להוליד אור חדש כ\"א שתחילה מקבלת מן השמש). והנה בענין מולד הלבנה ומלוי הלבנה הוסכם אצלם עפ\"י מופתים חזקים שהלבנה כדור עיגולית וחצי כדור שבה שעומד למול השמש העליון מגיע ומאיר בה אור השמש ע\"כ תאיר שם בכל חצי הכדור הזה אבל חצי התחתון שלה אין אור השמש מגיע לשם כלל ולא תאיר אור בכל חלק חצי כדור זה כלל והנה חצי כדור זה התחתון שאינו עומד למול השמש הוא העומד לצד חלל העולם שאין אור השמש מאיר שם כלל ע\"כ בסוף החודש יחשוך חצי כדור זה לגמרי לצד חלל כל העולם כי הארת אור השמש שמאיר בחצי כדור העליון שעומד למול השמש אינו מגיע לצד חלל העולם כלל ואין מגיע לנו מאור זה כלל רק מחצי כדור התחתון שאינו עומד למול השמש משם מאיר אור לנו אבל הוא חשוך לגמרי בסוף החודש אך בתחילת החודש מתחיל אור השמש להאיר גם במעט מחצי כדור התחתון שבה והתחלתו מאיר בה רק כנקודה בעלמא והוא הנק' מולד הלבנה כידוע עד אשר מעט מעט יתוסף אור השמש להאיר בחצי כדור זה שעומד לנגדנו עד אמצע"],[2400650198,"החודש שיתמלא אור השמש בכל חלק חצי כדור התחתון ונק' מילוי הלבנה כידוע ונמצא חצי כדור העליון שבה מאיר תמיד מאור השמש בלי שינוי כלל אבל חצי כדור התחתון שבלבנה לפעמים מאיר בה בכולה והוא במילוי הלבנה באמצע החודש ולפעמים מאיר רק אפס קצהו ולפעמים חשוך לגמרי והוא בסוף החודש וכך חוזר חלילה בפגימת הלבנה ומילוי הלבנה מידי חדש בחדשו כידוע אבל בחצי כדור העליון שבה מאיר הארת השמש תמיד בלי שינוי כלל וזה אינו מובן שהרי הטעם שחלק חצי כדור מתחיל להאיר מאור השמש מפני שנטה הילוך סבוב הלבנה לגבי מול השמש באופן שיגיע בה אור השמש בחצי כדור זה א\"כ זה המעט שהתחיל להאיר כאן ודאי נעדר הארת אור השמש במיעוט ערך שטח כזה בחצי כדור העליון מאחר שלעולם לא יאיר השמש רק החצי כדור הלבנה העומד למולו בלבד ולפי\"ז בהגיע מילוי דאור בכל חלק חצי הכדור התחתון שזהו מצד עמידתו בחצי כדור זה בלבד לגבי השמש ממילא מוכרח שהחצי כדור העליון שבה חשוך לגמרי בזמן אמצע החודש אך ההכרח לומר שדעת חכמי התכונה הללו סוברים שיוכל אור השמש להאיר גם בחצי כדור שבה העומד לנגדנו וזה יוצא מהכלל שיש צל המחשיך מכל דבר וזה ודאי שאור השמש אינו מאיר רק בחלק מהלבנה שעומד לנגדו וחצי הב' מחשיך ומיצל. ואמנם מבואר בס' נחמד ונעים שהוסכם אצל כל חכמי התכונה האחרוני' כמבואר למעלה כי יש דעה אחרת להיפוך ממש שחצי כדור העליון שבה אשר עומד לנגד השמש מצד קירובו אל השמש לא יאיר בו אור השמש כו' אלא חשוך הוא לגמרי כמו הלבנה ביום שלא תאיר אור כלל וכמ\"ש שרגא בטיהרא מאי אהני כו' כי כל האור המקבל לא יאיר רק בריחוק מקום דוקא מן המשפיע כו' וע\"כ כל שהלבנה מתרחקת יותר יותר תאיר ולזה להיפוך הוא שחצי כדור התחתון אשר לנגדנו להיותו מרחוק מן השמש הוא מאיר מאור השמש והוא באמצע החודש במילואו ובסוף חודש מצד קירוב הלבנה לא תאיר הלבנה אור כלל גם בחצי כדור הב' העומד לנגדנו וכל שנתרחק יותר תקבל יותר אור השמש ודוקא בחצי כדור העומד לנגדנו עד אמצע החודש הלבנה במילואה בחצי כדור הב' מצד ריחוקה אז מהשמש אבל חצי כדור העליון שבה העומד למול השמש חשוך לגמרי תמיד ונמצא זהו היפוך גמור מדיעה ראשונה דלדיעה זו חצי כדור העליון חשוך תמיד וחצי כדור התחתון לפרקים מאיר כולו כו' ולדעה הא' נהפוך הוא שחצי כדור העליון מאיר תמיד והתחתון מאיר בשינוים כו' אך עפ\"י קבלה האלקי' האמיתי' דיעה ראשונה אמיתי' אעפ\"י שגם ע\"פ ספרי הקבלה יוכלו לפרש הדברים למעלה בבחי' לבנה העליונה שעז\"א בזוהר סיהרא ללמג\"כ כו' גם כפי אופן הדיעה השני' הנ\"ל אך יותר"],[2400650199,"אמת כפי הנראה ומובן למעיין היטב בכל ספרי הקבלה ובפרט בזוהר כדיעה הראשונה דוקא. וכ\"ז לפי דעת האומר דגלגל חוזר ומזלות קבועים אבל לפ\"ד האומר דגלגל קבוע ומזלות חוזרים הרי הלבנה והשמש מתגלגלים וא\"א [לומר] בלבנה שחצי כדור העליון שבה עומד תמיד לגבי השמש כי ודאי בסיבובה חצי העליון יורד למטה וחצי התחתון עולה למעלה וכן חוזר חלילה בכל רגע ומה שיש שינוי' במילוי הלבנה ופגימת הלבנה היינו מצד סיבובם והילוכם בריחוק וקירוב זה מול זה אבל לא מצד עמידת הלבנה בחצי כדור העליון למול השמש דודאי אין הפרש בזה בין חצי עליון לתחתון רק בריחוק וקירוב תלי' מילתא:\n(מט) <b>והנמשל</b> מכ\"ז יובן למשכיל למעלה בבחי' שמשא וסיהרא הנזכר בזוהר דבחי' מל' דאצי' נק' סיהרא דללמג\"כ אלא מה שמקבלת מז\"א שנק' שמשא כנ\"ל. והנה בחי' המל' כלולה מע\"ס וחלק העליון שבה היינו בחי' ה\"ס הראשונות שבה שמקבלים תמיד ההארה מז\"א שנק' שמשא וע\"כ מאירים בתמידות בלי שינוי כלל כו' להיותם קרובים ועומדים תמיד למול פני השמש עילאה שהיא בחי' ז\"א כמשל הנ\"ל בחלק חצי כדור העליון דלבנה שעומד תמיד למול השמש שמאיר תמיד מאור השמש בלי שינוי כלל כו' אבל ה\"ס האחרונות שבה אינם מאירות תמיד כי אינם עומדים למול פני שמשא עילאה הנ\"ל והיינו בחי' חלק חצי התחתון שבמל' שאינם מאירים רק לפרקים כמו בלבנה באמצע החודש שנק' מילוי הלבנה ואמנם מ\"ש דסיהרא ללמג\"כ כו' קאי בין בחלק חצי העליון שהן בחי' ה\"ס הראשונות דמל' ובין בחלק חצי התחתון שהן בחי' ה\"ס האחרונות שבה והכל ללמג\"כ רק מה שמקבלת משמשא בחי' ז\"א רק שזה תמיד וזה לפרקים (וכמבואר למעלה במשל הלבנה שאין אורה בארץ רק מאור השמש כך אור המל' להאיר למטה וגם מה שמקבלת לעצמה בה\"ס הראשונות הכל מאור השמש עילאה שהוא בחי' ז\"א ולפי פי' הב' דלעיל דאור הלבנה עצמה מאיר בארץ רק שמקבלת תחילה אור לעצמה כו' כך גם בחי' המל' אינה יכולה להאיר למטה בעולמות אם לא שקבלה תחילה לעצמה כו' ומ\"ש דסיהרא ללמג\"כ היינו כח התולדה וההשפעה למטה כו' כנ\"ל) והנה בה\"ד יובן עפ\"י הקדמה א' הידוע בכל בחי' עו\"ע שהחצי עליון שבעלול דבוק בעילה שלו תמיד וחצי התחתון שבו מאיר למטה כי הטבע דכל עלול למשוך א\"ע אחר העילה שלו בכל בחי' הפנימי' שבו דוקא כמו תלמיד לגבי רבו שפנימי' שלו ברצון ובמוחין ובמדות נמשך אחר רבו לקבל שפע אור חיותו תמיד ולא נשאר בו רק חלק החיצוני ולזה לא יוכל להיות משפיע לשלמטה הימנו רק בחלק החיצוניי שבו כי בחי' הפנימי' שלו כולו דבק"],[2400650200,"ונמשך אחר רבו שטרוד למבלע ולקבל לעצמו לא פליט וזהו הנק' חצי העליון כח\"ב ודעת שכולל פנימי' חו\"ג וחיצוניות חו\"ג הכלול בת\"ת עם בחי' נהי\"מ נק' חצי התחתון שבו (וכמ\"ש ביאור זה במ\"א באריכו' בענין השוחד שהמדות יוכלו להטות השכל מצד שרש פנימיותם שדבוקים ברצון כו'). אך לפי\"ז לא הי' השתלשלות דעו\"ע כלל מאחר שנמשך כל הפנימי' לעילתו אמנם מוטבע בכל עלול שיהי' משפיע בחלק חיצוניי שבו לתחתון הימנו וכידוע דכל חלק חצי התחתון שבעילה מלובש בעלול וכ\"א מלביש לעליון הימנו עד החצי דהיינו חצי העליון דעלול מלביש לחצי תחתון דעילה וחצי תחתון דעילה מתלבש בחצי עליון דעלול שלמטה הימנו שהוא נק' עילה לגבי' כמבואר בפרד\"ס וכמ\"ש במ\"א באריכות. ובזה יובן ג\"כ בה\"ס ראשונות וה\"ס האחרונות דמל' הנ\"ל בהיות ידוע בפי' כי שמש ומגן ה' אלקים דבחי' אלקי' זה הוא בחי' מל' דאצי' שמשפיע לכל העולמות כמ\"ש מל' מל' כ\"ע בכלל והוא בחי' כח והתפשטות האור האלקי להחיותם מאין ליש בע\"ג כו' כי אלקי' לשון כח הוא והוא כח הפועל האלקי בנבראים שנק' סיהרא בכלל ויש בבחי' מל' ע\"ס ובחי' חצי העליון שבה היינו בחי' ה\"ס ראשונות שעז\"נ ואל אישך תשוקתך שהוא כמו תשוקת העלול לגבי עילתו כנ\"ל וכמ\"ש בזוהר בפי' אלקי' אל דמי לך דקרי תדיר נהו\"ת לנהו\"ע ולא שכיך לעלמין וכמ\"ש למען יזמרך כבוד ולא ידום כו' דהיינו בחי' ה\"ג שבמל' לצורך עצמה להעלות מ\"נ בתשוקת הקבלה לעצמה מז\"א שנק' שמשא והוא שם הוי' דאצי' ובחי' אלקי' זה מקור הנבראים שנק' נהו\"ת קארי תדיר בהעלאת מ\"ן לגבי נהו\"ע שהוא שם הוי' דז\"א דאצי' ולא שכיך לעלמין וכמ\"ש אל דמי לך כו' וכן למען יזמרך כבוד שהוא כבוד התחתון בחי' מל' דאצי' שכבוד זה לא ידום בהעלאת מ\"ן וכמ\"ש אש תמיד תוקד על המזבח לא תכבה לעולם שהן ה\"ג דנוק' שמעלה מ\"ן תמיד ונק' עולת תמיד כמ\"ש בזוהר בכמה דוכתי והיינו דוקא בבחי' ה\"ס ראשונות שבה כנ\"ל בכל עלול לגבי עילתו שחצי העליון שבו עולה ונדבק ונמשך אחר עילתו לקבל לעצמו וכמשל התלמיד לפני רבו דטריד למבלע ולקבל בכל פנימי' שבו שהן כח\"ב ופנימי' חו\"ג ע\"י הדעת כו' (שהוא התקשרות השכל וגם פנימי' המדות לגבי המשפיע כנ\"ל) ולא יוכל להיות משפיע למטה רק בחלק חצי התחתון שבו שיורד ומתלבש בעלול שלמטה הימנו כו' וכך בחי' המל' נק' מקבל בחי' נוק' לגבי ז\"א כמ\"ש ואל אישך תשוקתך בה\"ס הראשונות דבוקים תמיד למעלה בהעלאת מ\"ן תמיד ולא שכיך לעלמין וזהו כמו חלק חצי הכדור שבלבנה העליון העומד למול פני השמש תמיד בלי שינוי ואין לה אור עצמי רק מה שמאירה מאור השמש בתמידית כתלמיד לגבי רבו"],[2400650201,"שאין לו קיום מצד עצמו רק תמיד אל המשפיע תשוקתו ודביקותו לקבל ועולה ונכלל במשפיע ממש מבלתי היות בחי' יש ודבר בפ\"ע כלל ע\"כ גם המקבל יאיר בתמידות מהארת המשפיע ששופע בו תמיד (וכמ\"ש במ\"א [בענין] פני משה כפני חמה פני יהושע כפני הלבנה וכתי' ויהושע נער לא ימיש מתוך האוהל אבל מ\"ש ונתת מהודך עליו הוא אשר הי' יהושע איש אשר רוח בו להשפיע לכאו\"א כו' נק' משפיע אחר שקיבל לעצמו באהל משה) אבל בחי' ה\"ס אחרונו' שבמל' הוא אשר בחי' המל' נק' מקור משפיע אור וחיות אלקי לעולמות להיות ראש לשועלים להחיות רוח שפלים יש מאין כו' (וכנ\"ל בפי' אמת ואמונה כל זאת וקיים עלינו כו') וזהו כדמיון חלק חצי כדור התחתון שבלבנה שמאיר על הארץ לגבי חלל העולם שאין אור השמש מגיע לשם כלל רק אחר שקבלה לעצמה בחצי העליון לבד וחצי התחתון חשוך לגמרי ומתחיל להאיר בחצי התחתון ג\"כ מעט מעט עד שתתמלא כולה באמצע החודש אבל בסוף חודש חשוך לגמרי ואין מאיר בעולמות רק בבחי' צמצום והעלם גדול דהיינו רק בבחי' אחוריים דשם אלקים והוא בחיצוני' המדות שאין בהם מאו\"פ דרצון ושכל ומדות כלל (וכמשל הנ\"ל בתלמיד שנק' עלול שחיצוני' שבו מובדל ואין בהם אור הפנימית כלל) והוא הנק' פגימת הלבנה או מיעוט הירח ומה שבאמצע החודש תתמלא היינו שמפני תוקף אור השמש בחצי עליון יומשך גם האור בחצי התחתון מעט מעט עד דקיימא סיהרא באשלמותא בכל חלקי' גם בחצי התחתון באמצע החודש ונק' מילוי הלבנה וכך למעלה סיהרא עילאה היינו כל י\"ס דמל' גם בה\"ס אחרונות שבבי\"ע מאירים מאור השמש שהוא בחי' הוי' דז\"א דהיינו שגם בחי' ההשפעה דמל' בבי\"ע מאיר בה מבחי' הפנימי' כמו בה\"ס הראשונות ולא בבחי' חיצוניות ואחוריים בלבד וכמו בימי שלמה וכה\"ג דקיימא סיהרא באשלמותא שהוא בכל קומת בנין המל' גם [במל'] דמל' דעשי' בהיכל ק\"ק דעשי' הי' מאיר שם הוי' דז\"א כמו בראש הבריאה וכמו בה\"ס ראשונות שבמל' דאצי' בהיותה בבחי' אצי' דמקבלת לעצמה ממש כו' וכן גם עכשיו בכל שבת ויו\"ט יש גילוי אור הוי' גם בסוף מדריגות המל' בעולם העשי' או בניסים וכה\"ג וד\"ל (אבל לפי דעה הב' שבחכמי התכונה שחצי העליון חשוך מפני אור השמש יתפרש להיפוך דמה שנק' משפיע בה\"ס אחרונות יותר נעלה כי הוא תמידי יותר מבחי' ה\"ג שלעצמה בהיותה בקירוב שאז לא קיימא סיהרא באשלמותא בחצי העליון כ\"א מרחוק דוקא אז מאיר אור השמש גם בחצי העליון שבה וזהו נק' באשלמותא כו' וה\"ז כענין פי' הב' בהוי' הוא אלקים דלעיל בסוף אות מ\"ז):\n(נ) <b>ואחכ\"ז</b> יובן בתוס' ביאור שרש ענין ההפרש בין אורח לדרך ומ\"ש הנותן בים דרך"],[2400650202,"ולרוץ ארח דשניהם בנוק' הוא והנותנם הוא בחי' ז\"א כנ\"ל דהנה מבואר למעלה בהפרש שבין דרך לארח שהדרך הוא הכבושה לכל דהיינו שהוא תמידי לכל עובר ושב כו' והיינו ה\"ס ראשונות שבמל' דאצי' שמאירים בתמידות מאור שמשא בחי' ז\"א נק' דרך כבושה שכבר נכבשה מאור המשפיע ששופע עליה בתמידות והוא כמו הארת חצי העליון שבלבנה שנכבשה תמיד מאור השמש וזהו הנותן בים דרך שבחי' דרך כבושה זה שבמל' בה\"ס ראשונות שבה הוא ניתן מכח המשפיע מצד תמידי' אור שפעו וים הוא בחי' מל' דאצי' בבחי' האצי' בחלק חצי העליון שעולה ונכלל במשפיע והוא מ\"ש ואל אישך תשוקתך שזה התשוקה התמידי' שבה אל המשפיע הוא שנק' דרך כבושה שנעשה מסיבת תמידות אור שפע מ\"ד דמשפיע והיינו בחי' רוחא דשביק בגווה באור שפעו שעשאה כלי בביאה כו' וזהו ג\"כ דרך גבר בעלמה בביאה ראשונה שכורתת ברית למי שעשאה כלי בה\"ג דדכורא שקבלה לצורך עצמה כנ\"ל בענין באר חפרוה כו' אלא שהשפעת ה\"ג דדכורא נק' דרך גבר ואחר שנעשה מכח דרך גבר זה בחי' תמידי' תשוקתה אל אישה נק' דרך דנוק' שנתן בה המשפיע והוא הנק' דרך כבושה שעז\"א הנותן בים דרך (ובענין קי\"ס ה\"ז להיפוך שהדרך בים הוא הנק' יבשה עלמא דאתגלייא בחי' ה\"ס אחרונות דמל' שנק' משפיע למעביד תולדין כמ\"ש תוצא הארץ כו' ופסוק זה דנותן בים דרך דוקא בקי\"ס הוא ובכאן הרי עיקר ההפרש בין דרך לאורח דאורח הוא לאנהרא לתתא גם בה\"ס אחרונות להשפיע למטה ודרך הוא ה\"ס ראשונו' שעולה למעלה ואינו יורד למטה כלל והוא היפוך ביאור הנ\"ל (באות מ\"ז) בין דרך לארח שהדרך הוא הנשפע למטה כו' אך מוכרח לומר דב' פי' מחולקים הללו תלוי' בב' פי' מחולקים בקי\"ס שבין הזוהר ובין כהאריז\"ל המבואר במ\"א (כמשי\"ת בעזר\"ה) אבל בחי' ארח היינו בחי' חצי התחתון שבמל' שהן ה\"ס האחרונות שבה שמשפיע למטה בבי\"ע כנ\"ל שלפעמים אינם מאירים כלל כמו ענין פגימת הלבנה בסוף חודש רק בבחי' אחוריי' וחיצוני' בלבד כנ\"ל אבל מפנימי' אור הוי' באלקים שבה\"ס ראשונות אינו מאיר שם כלל אך לפרקים ועיתים מיוחדים כמו במילוי הלבנה באמצע החודש ובמועדים ורגלים וכמו בזמן הבית דקיימא סיהרא באשלמותא גם בה\"ס אחרונות שבה כנ\"ל ע\"כ הארה זו שלפרקים נק' בשם אורח כארח הבא לפרקים משא\"כ מבחי' ה\"ס ראשונות ששם האור דהוי' בתמידות הרי משם אור ושפע פנימי' לנשמות ומלאכים בתמידות כמו בג\"ע דבריאה ויצי' כו' שזיו השכינה מאיר להם בתמידות כו' (ומה שבשבת וחודש ויו\"ט עולין לפני הוי' היינו לפני הוי' ממש בבחי' ז\"א עצמו) מאחר ששם אור השפע דז\"א מאיר תמיד בבחי' פנימי' גם מה\"ס הללו כל אור שנשפע מהם אינו בא רק בבחי' הפנימי' לנשמות וכן"],[2400650203,"גם בשבת ויו\"ט מאיר מפנימי' הוי' דז\"א עצמו וכמו עולי רגלי' בג' מועדי' דכתי' יראה כל זכורך את פני הוי' כו' משום דפני הוי' דז\"א שורה אז בהיכל ק\"ק דעשי' שבבהמ\"ק כו' שאעפ\"י שזהו לפרקים אינו נק' ארח דנוק' כי בבחי' דכורא הוא משא\"כ גילוי אור דמל' בה\"ס אחרונות שבה ג\"כ היינו מה שמאיר גם בחיצוני' מבחי' הפנימי' כמשי\"ת זהו בחי' ארח לנוק' בלבד כו' וזהו פי' אורח שהוא לנוק' בלבד כי הנה בחי' ה\"ס אחרונות שבמל' הוא עיקר ההשפעה שבאה מבחי' המל' בבי\"ע דהיינו לנשמות ומלאכים שבחיצוני' העולמות שיקבלו גם המה מבחי' הפנימי' דוקא ולא מבחי' האחורים וחיצוני' בלבד וא\"ז אלא לפרקים בלבד כנ\"ל ע\"כ נק' אורח והוא לנוק' בלבד דהיינו רק בבחי' השפעה דמל' בעולמות בלבד משא\"כ בחי' דרך שבה\"ס ראשונות הוא מה שאל אישה תשוקתה כו' שאינו בבחי' נוק' לבד אלא הוא כח הדכר שבנוק' כנ\"ל וד\"ל. וזהו שמביא דמיון לפי' לרוץ אורח מנותן בים דרך דהיינו כמו שבחי' אור דה\"ס ראשונות מבחי' ז\"א הוא בא כך בחי' ארח שהן הארת ה\"ס אחרונו' שמאיר ג\"כ מבחי' הפנימי' כנ\"ל שלרוץ ארח זה הוא בא מכח המשפיע בחי' ז\"א שנק' שמשא כשמאיר בכל עיגול כדור הלבנה גם בחצי התחתון שבה כנ\"ל ונמצא הדרך ואורח שהן ה\"ס הראשונות וה\"ס האחרונות שניהם הוא הנותן כא' בבת א' כמו בזמן מילוי הלבנה שהוא בזמן הבית כנ\"ל רק שבנוק' מתחלקים לב' מדריגות דרך וארח וחצי העליון וחצי התחתון כו' וד\"ל. ובכ\"ז יתבאר לשון המאמר הזה במ\"ש וע\"ד לרוץ ארח כד\"א הנותן בים דרך ר\"ל ששרשם מז\"א בהארה א' באים כא' רק שבנוק' מתחלק לב' מדריגות דחצי העליון שבה בבחי' ה\"ס הראשונות נק' דרך לאשקאה לרוות צמאון פנימי' התשוקה דמל' כמ\"ש אל אישך תשוקתך כו' ומ\"ש עוד לאשלמא נהירו דסיהרא בכל סטרין דקדק לומר בכל סטרין לרבות גם בחי' ה\"ס אחרונות שבה ג\"כ שזהו בחי' ארח שהוא לנוק' בלבד כנ\"ל וז\"ש בכל סטרין שבה ואזי בזה יש כח למפתח בה ארח לאנהרא לתתא ג\"כ והיינו גם לבחי' חיצוני' העולמות שיקבלו גם הם מבחי' הפנימי' דוקא כנ\"ל שזהו נק' לאנהרא לתתא דוקא כמ\"ש בתחילת המאמר נהיר לכל גוונין נהירין דלתתא שעז\"א לרוץ ארח דוקא לפי שא\"ז רק לפרקים כמו בזמן הבית ובשבת ובמועדים (וכמו נשמו מסילות שבת עובר ארח דקאי בזמן הגלות וכה\"ג דמל' הוא בהסתר הפנימי' לגמרי כו') ואמר למפתח בה ארח מפני שהכח הפותח בנוק' ארח זה הוא בא מכח המשפיע דוקא והיינו מחמת תוקף גבו' ההשפעה דיסוד ז\"א דנהיר בנוק' כמ\"ש למעלה בפי' ישיש כגבור כו' שמפני תוקף המרוצה יאיר אורו בכל קומת בנין המל' גם בה\"ס האחרונות שבה דהיינו מ\"ש בתחילת המאמר ואיהו נהיר"],[2400650204,"בכל אינון גוונין נהירין דלתתא שמקבלים מחיצוני' ואחוריים שנק' גוונין נהירין דלתתא ג\"כ שיקבלו גם הם מבחי' הפנימי' דוקא משא\"כ בחי' דרך שאינו בא להאיר רק בפנימי' דמל' בה\"ס הראשונות בלבד כנ\"ל ולכך א' לרוץ ארח דוקא ולא דרך אעפ\"י ששרשם א' הוא מבחי' ז\"א כנ\"ל וד\"ל. אך מבואר למעלה בהיפוך בפי' דרך שהוא מ\"ש ההופכי הצור אגם מים דחסדים דדכורא שזהו בחי' דכר שבנוק' להשפיע למטה שהוא למעלה בשרשו מבחי' ה\"ג שלעצמה כו'. ושרש ב' הפי' מחולקים הללו תלוי' בב' פי' דקי\"ס שעז\"א הנותן בים דרך כידוע דבזוהר מפרש שרש קי\"ס בבחי' העלאה מלמטה למעלה שבחי' אור הבריאה עולה למעלה באצי' כמ\"ש במ\"א באריכות בביאור ענין המאמר כד סליק ימא גלגלוהי כו' והיינו בחי' הדרך דיבשה שהוא בים עלמא דאתכסיא שזהו עליות העולמות שמקבלים מה\"ס האחרונות שעלו בבחי' ה\"ס ראשונות שנק' ים וזהו בפי' הנ\"ל דדרך הוא בה\"ס ראשונות שנק' דרך כבושה כו' אבל בכהאריז\"ל מפרשים שרש קי\"ס בבחי' ירידה והמשכה מן ההעלם לגילוי שזהו בחי' לידה כו' דהיינו שבחי' האצי' שנק' העלם נעשה בבחי' גילוי דדרך ביבשה וז\"ש הפך ים ליבשה שמעלמא דאתכסיי' דוקא בה\"ס ראשונות נעשה בחי' עלמא דאתגליא כו' וכענין ברוך ה' מן העולם ועד העולם (וכדמיון הניסים שלמעלה מן הטבע המאיר בטבע לעשות היפוך הטבע וזהו דרך גבר בעלמה כו' וכמ\"ש במ\"א בפי' מאמ' הזוהר ע\"פ שאל לך אות העמק שאלה כו' והוא כי הנה העלמה הרה כו') וזהו בחי' דרך שבים שמשפיע למטה דוקא ונק' דרך כבושה לרבים דוקא בנהירין דלתתא בבחי' ה\"ס אחרונות עד מ\"ח צירופים האחרונים דאלקים כו' ולפי\"ז בחי' ארח הוא בה\"ס ראשונות דמל' שהוא לפרקים בכל יחוד דזו\"נ בלבד כמו במועדים וכמו בזמן הבית שהי' יחוד פב\"פ כו' וארח זה לנוק' בלבד היינו רק מה שמקבלת בשביל עצמה ולא לצורך השפע לעולמות (והוא ג\"כ עליות הנשמות מג\"ע לג\"ע כו' שנק' ארח לפרקים משא\"כ זיו המל' התמידי בג\"ע נק' דרך כו') ולפי\"ז לא יתפרש לשון מאמר זה במ\"ש לאשקאה ולאשלמא בב' מדריגות אלא קאי אלרוץ ארח דוקא שהוא לאשקאה להמתיק הגבו' דנוק' בחסדים דדכורא כמ\"ש ההופכי כו' שיהי' נק' בבחי' דכר להשפיע למטה לאנהרא בכל סטרין דוקא ומ\"ש למפתח בה ארח לאנהרא לתתא זהו מפרש לבחי' דרך שא' תחילה ולא בבחי' ארח דלנוק' בלבד וד\"ל:"],[2400650205,"<h3>מקצה השמים מוצאו</h3>\n(נא) <b>מקצה</b> השמים מוצאו. פי' בזוהר (שם) וז\"ל. מקצה השמים מוצאו. מסייפי אילין שמים עילאין דקאמרן איהו נפיק בגין דבסופא דגופא איהו נפיק. ובההיא אתר אשתמודע בין דכר לנוק'. ודא"],[2400650206,"הוא דכתי' ולמקצה השמים ועד קצה השמים. קצה השמים דא עלמא עילאה ולמקצה השמים דא מלכא דשלמא דיליה כמה דהאי נטיל כל נהורין וכולהו בי' אוף הכי האי נטיל כל נהורין וכולהו בי' ע\"כ. פי' מסייפא אילין שמים עילאין הוא בחי' יסוד אימא דאימא עילאה דאצי' דהיינו בחי' נה\"י דבינה שנק' סופא דשמים עילאין (כי בחי' שמים עילאין הוא בחי' ג\"ר דאו\"א וסיומם בנה\"י דבינה דוקא כי הבינה הוא בחי' ההשגה ליש וביסוד אימא נקלט במוח ההשגה לבחי' יש יותר וזהו הסיום של כל אורות הנעלמים דא\"א וע\"י כו' שבג\"ר דחו\"ב שנק' אין הנעלם כשבא לכלל בחי' יש היותר אחרון שבבינה שהוא בחי' יסוד אימא). והנה שרש ענין זה המאמר מדבר במקור ושרש הראשון דבחי' גילוי המוחין דאבא ביסוד ז\"א שנק' שמשא שזהו לאחר בקיעת יסוד אימא דוקא שנק' סופא דגופא שמשם תולדות ז\"א כמשל הבן הנולד מרחם אמו כו'. דהיינו לאחר בקיעת יסוד אימא אבל קודם שנבקע יסוד אימא הרי בחי' החסדים דאבא סתומים ונעלמים עדיין ביסוד אימא ולאחר שנבקע יסוד אימא אזי דוקא יוצאים חסדים ואורות דאבא בגילוי לז\"א והוא בחי' יסוד ז\"א שנק' שמשא דנפיק בסופי' דגופא ונק' סייפא דשמים עילאין שהוא לאחר בקיעת יסוד אבא ונגלה אז אור דאבא בז\"א. וזהו פי' מקצה השמים מוצאו דהיינו שרש הראשון בגילוי אור אבא ביסוד ז\"א הוא בקצה השמים דיסוד אימא שנק' עלמא עילאה (דיסוד אבא ארוך משל אימא דיסוד אימא מסתיים בחזה דז\"א וזהו דבינה עד הוד דז\"א אתפשטת ולא עד יסוד כי ביסוד דאימא החסדים סתומים ולאחר בקיעת יסוד אימא יוצא אור אבא ומגיע ליסוד ז\"א וז\"ש ומרדכי יצא כו' וכן אך יצא יצא יעקב כו'. וזהו שיסוד ז\"א נק' יתום מאמו ולא מאביו כידוע). ולהבין ביאור כ\"ז הנה ידוע דאור אימא הוא בחי' בינה שהוא מוח ההבנה וההשגה להשיג כל המושכל בעומק ואורך ורוחב וכלול מע\"ס ג\"ר ומדות כו'. וכללות ענין הבינה הוא רק בחי' מקבל מאור אבא כי עיקר ההשגה אינה רק בחי' בית קיבול בהתפשטות אורך ורוחב ועומק לבחי' אור אבא שהוא בחי' נקודת אין דחכ' שבהעלם כידוע שהחכ' נק' אין והבינה נק' יש והמדות שבהשגות הבינה ג\"כ שכליים והשגו' שבמוח הן ונק' מדות שבשכל כמו הדבר המושג לחיוב או לזכות במוח והן חג\"ת דאימא ונו\"ה כו'. עד בחי' יסוד אימא שזהו בחי' ההתקשרות להתקשר ולקלוט היטב את אור ההשגה והסברא גם שכבר משיגה במוח בכי טוב בעומק גדול רק שלא נקלט דבר המושג ומושכל בבחי' התקשרות היטב במושכל בעומקו עד שכל כלי מוחו ממולא מן כל העומק של אותו הסברא והמושכל וכאשר קולט היטב בהתקשרות גדולה עד שכל מוחו ממולא ממנה בלי יוכל להשיב מאומה"],[2400650207,"לשואלו דבר כו' זהו הנק' יסוד אימא בחי' כלי הקליטה לקלוט ולהתקשר היטב בהשגת דבר מה (ובל\"א פאר קלעפט אין שכל [שטארק] און פאר נומען גוט און פאר טראגין און דער הערט זייער גוט אין מוח) ונק' אודנין דשמעין והמה אודנין דלבא, בינה לבא, ששם מסתיים בחי' יסוד אימא (וכל מי שיש בו כלי הקליטה במוח הנק' יסוד אימא ביותר לעומק הוא יעמוד [יותר] על תמצית ועומק המושג יותר (שהוא אין דחכ' שבבינה שזהו חכם בבינה ע\"ב דס\"ג וגם עד כתר דחכ' אין דחכ' שבהעלם כו' ועד בחי' חכ' שבכתר שנק' ח\"ס ועד בחי' הכתר עצמו עד כתר שבכתר לפי שנתחב\"ס וכמ\"ש בסוף המאמר דכמה דהאי נטיל כל נהורין כו'. דקאי ביסוד אימא שזהו סוף ההשפעה דאין שבא בבחי' גילוי היש כנ\"ל) וכל מי שאין בו כלי הקליטה כ\"כ לעומק (ער פאר נעמט ניט טיף נאר פון אויבין און ער איז ניט צוא גיקלעפט גוט און ער איז ניט קולט גוט) לא יעמוד על עומק המושג כלל ויוכל לבוא לידי טעות והיפוך המכוון כו'. והנה ענין בקיעת יסוד אימא היינו כאשר לא יכיל כלי המוח להעומק של המושכל כי עומק המושכל גובר יותר על ערך כלי הקליטה שבמוחו עד שלא יכילנו ויסבלנו וכענין המאמר לאו כל מוחא סביל דא הנה זהו הנק' בקיעה כמשל חבית המלאה שכאשר תתמלא יותר ממדתה ופיה סתום הנה אז תבקע מפני שלא תכיל מה שבתוכה וכך כלי הקליטה שבמוח נק' יסוד אימא כאשר לא יכיל לעומק השפע של ההשגה שבתוכו (והוא סתום ונק' מ\"ם סתומה להיותה מגעת ועולה בבחי' ההעלם בעצמותו ופנימי' דכח\"ב כנ\"ל. שזהו מדרך הקליטה לעלות לעומק הראשון יותר כנ\"ל). הנה אז יבקע וענין הבקיעה הוא תוקף היציאה והגילוי של העלם שבבינה ברעש ותגבורת גדולה כמו בקיעת החבית שהמים היוצאים בבקיעה יוצאים בתוקף וכח ותגבורת גדולה והסימן לזה הוא מה שאנו רואים במי שלא יכול כלי מוחו להכיל ההשגה שבמוחו יבוא לכלל התפעלות יתירה במוח מפני שלא יכיל המוח ויוצא אור תוקף התפעלות זו ללב להתפעל שם בגילוי אופן תנועות משונות שלא עפ\"י הדרגה וכן יצא להתפעל במח' בתנועות משונות בהתפעלות יתירה במח' עד שיבוא התפעלות תקיפה וחזקה גם בדיבור לדבר דברים בריבוי יותר ובהתפעלות יתירה שלא כרצונו בישוב ונחת אלא במהירות ימהר להשיב דברים רבים שלא בהדרגה עד שגם בתנועות הגוף יעשה בהתפעלות בידיו ורגליו מיד שיתפעל ביותר במוח מצד העדר כלי קליטתו כשלא יוכל להכיל ההשגה שזהו נק' בקיעת יסוד אימא אבל כשכלי קליטתו מכיל לכל עומק המושכל אז אדרבא לא יבוא לכלל התפעלות במוח במציאות גילוי תנועות בלב ומחו\"ד ותנועות הגוף אלא נראה כמו טרוד בכלי מוחו בישוב ושתיקה בלי יוכל להשיב דבר לשואלו מפני טרדתו לקלוט"],[2400650208,"ולקבל העומק שזהו היפך התפעלות בריבוי תנועות שבא מקוצר המשיג [ועומק המושג] וכל שהמשיג עמוק מן המושג יותר יתקבל בישוב ושתיקה (בל\"א פאר נומען גוט אין מוח און פאר טראגין און אריין גילייגט שטארק וכה\"ג). והגם שבטרדת הקליטה נראה ג\"כ התפעלות בתנועות כמרוצה ברגליו וידיו מתנענעים כידוע זהו להיפך מצד עומק הקליטה וטוב הקבלה בפנימי' כלי מוחו כשמכיל היטב היפוך הבקיעה כשלא מכיל שיצא כל ההשגה רק בהתפעלות הזאת שיצא חוץ לשכל בלב או במחו\"ד ותנועות הגוף כבקיעת המים מן החבית (בל\"א עש גייט דער שכל לחוץ מיט איין התפעלות תנועה כו'). והדוגמא מכ\"ז יובן למעלה בביאור בחי' בקיעת יסוד אימא בחי' בינה דאצי' שלעוצם ריבוי המוחין ביותר מכפ\"ע כלי הקליטה דבחי' יסוד אימא שלא יכילנו ויסבלנו אז נבקע יסוד אימא ויוצא האור בתוקף ותגבורת ללב שהן בחי' המדות דז\"א כידוע ולמח' ג\"כ באה בהתפעלו' אור שלא כפי המדה ועד שבא בדיבור ג\"כ שהוא בחי' המל' ומשם לבחי' המעשה כו'. אבל אם הי' יסוד אימא סתום כי יכול כלי הקליטה להכיל אדרבה הי' הכל עולה למעלה בהעלם העצמי' בלתי נגלי' אור למטה במדות כלל ולא במחו\"ד שהן עלמא דאתכסיא ועלמא דאתגליא כמבואר במשל הקולט היטב שטרוד בישוב ושתיקה ולא ישיב לשואלו מאומה כו' וד\"ל:\n(נב) <b>ומעתה</b> י\"ל ביאור ענין שרש הראשון לגילוי בחי' המוחין דאבא בז\"א לאחר בקיעת יסוד אימא דוקא כנ\"ל. דהנה לכאורה מובן מתוך כל הנ\"ל בבחי' בקיעת יסוד אימא שמה שיוצא לחוץ מצד שלא יכיל כלי הקליטה הנה א\"ז מאור הבינה עצמה מאחר שלא יכילנו בכלי המוח הרי מה שיוצא לחוץ מן ההשגה ללב ומח' וכה\"ג אין זה השגת שכל כלל אלא נק' נובלות שנופל מצד עוצם ריבוי המוחין דוקא כידוע והיינו מה שמרבה דברים או מהרהר בריבוי אותיו' המח' וכה\"ג שבאים בבחי' נובלות מפנימי' ההשגה שלא יכיל המוח. (וזשארז\"ל ג' נובלות הן נובלות חכ' ש\"מ תורה ונובלות בינה שלמעלה שכינה כי עולם הדיבור נק' שכינה תתאה בחי' רחל ועולם המח' נק' שכינה עילאה בחי' לאה ושרש התו' וריבוי שלהם בא מצד בחי' נובלות דבינה שלמעלה ע\"ד שאמרו נשים דברניות הן כמ\"ש במ\"א. וכמו עד\"מ עומק המושג וקוצר המשיג שיוצא בבחי' נובלות כנ\"ל וכן אורייתא שהוא בז\"א מחכ' עילאה נפקת מנובלות חש\"מ אין דחכ' כשגובר על כלי יסוד אבא (כמ\"ש במ\"א)). והנה לפי\"ז לכאורה יש להפליא על אשר אנו רואים שימצא בדיבור ריבוי התחדשות מאד בשכל וסברא [שכבר השיג] ביותר הרבה מכפי שהשיג וזה בא ממילא ומאליו בלי יגיעה לזה בתחילה כלל בשכלו וגם שלא ברצונו במח' תחילה יבוא החידוש הרב כשיבוא לדבר בדיבורו דוקא כשנבקע בחי' יסוד אימא שהוא מקוצר המשיג ועומק"],[2400650209,"המושג שיצא בחי' נובלות להרבות דברים במהירות כנ\"ל אזי יש התחדשות שכל רב בדיבור בכפלי כפליים מכפי השגתו הראשונה אבל כאשר יכיל כלי הקליטה שבמוחו לעמקות ההשגה ויטרד בה שלא ירבה בדיבור אדרבא ימעט מאד בדיבור וכאשר ישיב דבר לשואלו יכלכל דבריו בעומק במדה ושיעור בישוב ונחת במשפט השכל כפי אופן שעור השגתו במוחו ולא יוסיף התחדשות מאומה בדיבור (ומ\"ש ומתלמידי יותר מכולן היינו מצד הקושיות והשאלות שתלמיד מחכים את רבו ממקור החכ' כו') כי דבור זה בא אחר המח' בתחילה שבדעת ומח' ידבר כל דיבור בפרט אבל בבחי' בקיעת כלי הקליטה לעומק המושג וקוצר המשיג ירבה דברים כו'. הנה הדיבור יבוא בלא מח' ורצון בתחילה אז דוקא יבוא חידושי' גדולים כמעט שכל וחכ' חדשה לגמרי שלא הי' ביכולתו להשיג כלל. וזה פלא גדול לכאורה דאם בכלי הקליטה לא הכיל לעומק ההשגה איך בדיבור יבוא גם חידוש בעומק השכל כו'. אך הענין הוא דכשלא נבקע יסוד אימא הרי בחי' יסוד אבא סתום ונעלם בתוך יסוד אימא כנ\"ל. (ולכך הי' משה כבד פה כו'. כבד פה בתושבע\"פ שזהו עולם הדיבור מל' קרינן ליה וכבד לשון בתושב\"כ כו'. דתושב\"כ שבז\"א מנובלות חש\"מ ותושבע\"פ בחי' הדיבור שנק' שכינה מנובלות בינה ש\"מ ושרש משה בפנימי' יסוד אבא פנימי' בינה כו' כשהוא סתום ונעלם וכמ\"ש במ\"א בענין ולא ידע איש את קבורתו כו' ומ\"ש משה זכה לבינה הוא שער הנו\"ן כו'. לכך הי' כבד פה וכבד לשון כו' רק ה' א' לו מי שם פה לאדם כו' וכמ\"ש במ\"א וד\"ל). וביאור ענין יסוד אבא היינו בחי' הברק' הארת אור אין דחכ' כשיוצא מן ההעלם לגילוי בהשגה דבינה שנק' יש והיא נקודה היולי' דחכ' שסתום ונעלם בבינה כידוע בענין נקודא בהיכלא כו'. וכל חידוש שכל והשגה בהכרח יבוא ממקור הראשון דוקא שהוא הנק' משכיל מקור נעלם לגילוי נקוד' דיסוד אבא כידוע בענין והחכ' מאין תמצא מאין דח\"ס שנק' תעלומות חכ' ונק' קדמות השכל כו'. וכאשר בחי' יסוד אבא סתום בבינה היינו ביסוד אימא בכלי הקליטה שבה ואז לא יהי' החידוש השכל כלל בדיבור כנ\"ל אדרבה הרי אמרו דברי חכמים בנחת כו'. וכל שהוא חכם יותר יותר יהי' מתון בדיבור עד שא' סייג לחכ' שתיקה ומלה בסלע ומשתוקא בתרין כו'. אך בזאת יש יתרון מעלה בבקיעת יסוד אימא שעי\"ז יוצא בחי' נקודת האין דחכ' שבבינה לידי גילוי לחוץ מהעלמו בהשגה דבינה ששרשו בבחי' אין דמקור החכ' שנק' תעלומות חכ' או ח\"ס וכה\"ג שמשם נובע כל חידוש אור השכל כנ\"ל. ולזה כאשר ירבה לדבר דברים מצד נובלות דבינה שם ימצא ריבוי התחדשות השכל וההשגה ממקורו מצד כח אור דיסוד אבא שיצא חוץ ממקומו שהי' בהעלם ביסוד אימא והגם שהנובלות בא מצד"],[2400650210,"שלא יכיל ההשגה לעומקה ואיך יבא בדיבור חידוש בעומק המושג הענין הוא כידוע דשרש סיבת יציאת הנובלות הוא בא מצד התגברות בריבוי שפע המוחין ביותר מכדי שיוכל שאת בכלי מוחו וענין ריבוי השפע של המוחין היינו ריבוי עומק המושג שלמעלה מהכיל בכלי מוח הבינה וע\"כ לא יוכל לקלוט ויוצא לחוץ כנ\"ל. ואין זה רק מסיבת תגבורת אור עליון יותר מהשגה הראשונה והוא מבחי' פנימי' אור אבא שגובר על כלי הקבלה דבינה והיינו כמבואר במ\"א בסיבת כל נובלות שבאה רק מצד תגבורת שפע מאור העליון ביותר כמשל חבית המלאה ביותר כו'. וכמשל האור הנשפע ביותר לחכם גדול מאוד שירבה דברים בדברי מותרות ונובלות חכ' שנק' משלים וחידות כמשלי שלמה וכג' מאות משלים דר\"מ כו'. (ולזה הטעם מ\"ש נובלות חש\"מ תורה ונובלות בינה ש\"מ שכינה לשבח קאמר דנובלות זו מצד תגבורת אור עליון יותר שיוצא מבחי' חכ' הנעלמה והקדומה כו' ומה שהי' משה כבד פה ולשון וה' אמר לו מי שם פה כנ\"ל היינו ע\"י בחי' נובלות חש\"מ ובש\"מ כו'. וכמ\"ש במ\"א בביאור הפסוק הנה ה' יוצא ממקומו שהוא גילוי יסוד אבא מהעלמו ביסוד אימא כו' שמזה נתנה תושב\"כ ותושבע\"פ כו' וד\"ל). ולהיות כי הדיבור שרשו בפנימי' אור אבא כידוע בענין אבא יסד ברתא (שהוא מקדמות השכל שנק' ח\"ס כו' כמ\"ש במ\"א בענין צפרא כו'). לזה הטעם יהי' הריבוי של חידוש השכל ממקורו שלמעלה מהכיל בכלי המוח בינה כשבא בדיבור דוקא אך מצד שרש הדיבור בחכ' גם בכל פעם הי' בדיבור תוס' אור חידוש השכל ואינו כן אלא רק בהיות בקיעת כלי הקליטה דמוח הבינה דוקא ולא כשהוא סתום שאז אדרבה לא יוסיף חידוש בדיבור כלל ע\"כ מוכרח לומר דגם ששרש הדיבור במקור החכ' אבל אין מקור החכ' מאיר בתוס' אור בדיבור כ\"א כשיוצא בחי' יסוד אבא מהעלמו ביסוד אימא לחוץ דוקא שהוא לאחר בקיעה דיסוד אימא כשאין כלי הקליטה מכיל שיצא נובלות בדיבור כנ\"ל ולא מצד עצם הנובלות אלא מצד שרש סיבת הנובלות שבא מסיבת התגברות ריבוי המוחין כו'. אשר ע\"כ יוצא אור אבא לחוץ (כי יסוד אבא ארוך כנ\"ל). ובכ\"ז מבואר לשון המאמר בתחילתו דמסייפא דאילין שמים שהוא בקיעת יסוד אימא איהו נפיק כי בחי' יסוד אבא הוא שיוצא חוץ ממקומו ומגיע בבחי' יסוד ז\"א וזהו בגין דבסופא דגופא נפיק כו'. (ואפשר לפרש דשמשא ביסוד אבא ונפיק בסופא דגופא ביסוד ז\"א ותחילת יציאתו בבקיעת יסוד אימא). וזהו מקצה השמים יסוד אימא [עלמא] עילאה. ולמקצה השמים מלכא דשלמא דיליה בחי' יסוד ז\"א וכמה דהאי נטיל כולא וכולהו ביה שכולם הולכים לסוף ההתגלות דיש שבבינה בבחי' יסוד אימא שקולט הכל כנ\"ל כך האי יסוד ז\"א נטיל"],[2400650211,"כולא כל גילוי האורות היוצאים מיסוד אימא בז\"א ע\"י יסוד אבא וכולהו בי' שכולם כלולים בו ונק' כנישו דכל נהורין כמ\"ש יקוו המים כו' אל מקום א' כו' כידוע וד\"ל:"],[2400650212,"<h3>ותקופתו על קצותם</h3>\n(נג) <b>ותקופתו</b> על קצותם. דסחרא בכל אינון סטרין קדישין (דאתחזון) לאתנהרא ולאתשקאה ולנצצא מיני' ע\"כ. פי' מתחלה אמר בשרש מוצאו דבחי' יסוד ז\"א שנק' שמשא דנפיק בסופא דגופא בקצה השמים עילאין בבקיעת יסוד אימא (דהיינו בחזה דת\"ת דז\"א שב' שלישי' העליונים מכוסי' ושליש ת\"ת האחרון האחרון מגולה בחסדים [מגולים] שבוקעים מאור אימא והיינו מזרח שהוא בבחי' ת\"ת שמשם זורח השמש וכמ\"ש וזרח השמש כו' הולך אל דרום כו') ועתה מדבר בהקפתו על כל קצוות דשמים דהיינו שהוא מקיף וסובב לכל בחי' ו\"ק דז\"א מזרח ומערב צו\"ד כו' כמ\"ש הולך אל דרום כו'. ולכאורה אינו מובן דאיך ביכולתו להקיף כל קצוות דשמים עילאין מאחר ששרש תחלת מוצאו אינו רק מסייפי דשמים עילאין שהוא בסיום יסוד אימא כו'. אך הענין הוא משום דביסוד ז\"א מלובש מבחי' יסוד אבא שהי' נעלם באימא ושרש מוצאו דיסוד אבא הוא בבחי' יסוד דע\"י שבפנימי' אבא כו' שכולל לכל ו\"ק דשמים עילאין שהן מדות שבחו\"ב אש ומים כו'. לזה יש גם ביכולת יסוד ז\"א להקיף כל קצוות דשמים דז\"א ממזרח למערב כו' שהן בבחי' ו\"ק דז\"א כי כוללם יחד וכמ\"ש למעלה דנטיל כולא וכולהו בי' כו' וד\"ל. ובה\"ד ידוע בענין התלבשות יסוד אבא ביסוד ז\"א דוקא כי בחי' יסוד אבא הוא הברקת נקודת המושכל כמו שהוא בעצם טרם שיבוא בהשגה והסבר וכאשר נעלם בהשגה דבינה אינו מאיר במדות שבלב רק מאשר בא האור בהתפעלות המדות שבבינה ע\"י בחי' יסוד אימא הנק' כלי הקליטה שבמוח כנ\"ל. אך לאחר שיצא מהעלמו ללב כנ\"ל הרי עיקר משכנו ביסוד ז\"א שהוא בחי' התקשרות הלב והרגשתו במושכל נקודה זאת דיסוד אבא שזהו כמו ענין ראיית הלב שרואה בבחי' ראי' דנקודת חכ' וכמ\"ש ולבי ראה הרבה חכ' והוא עין השכל דבלבא כו' (דכמו שהלב שומע בבינה שבלב שהוא מבחי' יסוד אימא ונק' אודנין דלבא כנ\"ל כך הלב רואה ראי' השכל והוא בחלל הימני שמקבל ממוח החכ' ממש. וכמ\"ש לב חכם לימינו כו' ונק' חכם לב והוא מה שהלב רואה ראיית השכל שבבחי' יסוד אבא כמו שהוא ממש במוח החכ' טרם שיתעלם בהסבר והשגה דבינה וכמו בכל לבי דרשתיך וכה\"ג וכמ\"ש במ\"א וכן לבי ובשרי ירננו כו' וכמו הניגון שיוצא מהבל החזה ובו מלובש תמצית נקודת הכוונה הפנימי' שבמוח החכ' כו'. וז\"ש בר\"מ דבעין השכל דבלבא אתחזי כו'. ואמנם א\"א שיתלבש נקודת יסוד אבא רק ביסוד ז\"א שהוא בחי' התקשרות המורגש שבלב ולא במדות שבלב כי"],[2400650213,"המדות שבלב מקבלים עדיין מהתבוננות דבינה דבינה עד הוד אתפשט' להוליד המדות שבלב אך כשנבקע יסוד אימא זהו מה שמסתלקים לנה\"י דאימא למעלה והוא ענין ביטול כל ההשגה שבאריכות ונעשה קיצור מופלג רק להיות למוחין בהתפעלות המדות ומזה הטעם יכלה גם התלהבו' התפעלו' הלב בעת הסתלקו' אור ההשגה כו' אך בחי' יסוד [אבא] שהוא עצם המושכל מתחיל להאיר אז בבחי' יסוד שבמדות שבלב דוקא אחר כלות כל התפעלות המדות שבלב שבא מכח ההשגה כי אין אור אבא יוצא רק אחר הסתלקות אור אימא בבקיעת היסוד (כמבואר במ\"א בפי' חגרה בעוז מתניה כו' דנה\"י דבינה מסתלקי' וז\"ש וראיתן על האבניי' שהירכיי' מצטננות בשעת לידה כמ\"ש בע\"ח ונמשכי' נה\"י חדשי' שבאי' מבחי' גדלות ג\"ר דבינה כו' וז\"ש כאן ותקופתו על קצותם לפי שמוצאו מקצה השמים שהוא יסוד דאימא). ובכ\"ז יובן הטעם למ\"ש בפי' ותקופתו על קצותם דמקיף לכל ו\"ק דשמים עילאי' דזהו מצד שרשו ביסוד אבא שכולל ו\"ק דאבא והתלבשות דיסוד אבא הוא ביסוד ז\"א דוקא כנ\"ל. ע\"כ גם בחי' יסוד ז\"א שנק' שמשא תקופתו על כל ו\"ק דז\"א כי הוא מצד הארת יסוד אבא שבו מקיף הוא לכולם יחד וכמו שנראה בחוש שבהתפעלות הראי' שבשכל שמורגש בלב כולל כל מיני התפעלות המדות שבלב אוי\"ר שמסתעפי' מן ההשגה דבינה בהקפה א' לכולם יחד כו' וד\"ל. וז\"ש דסחרא בכל אינון סטרין קדישין שהן מזרח מערב כו'. ושרש ו\"ק דז\"א הוא בו\"ק דאבא שנק' סטרין קדישין ונק' קצותם דשמים עילאין (וכפי המבואר במ\"א בפי' צדיק כתמר יפרח כו'. דיסוד ז\"א שרשו הראשון ביסוד דע\"י עד יסוד דא\"ק ולמעלה מעלה ביסוד דמל' דא\"ס זהו פי' תקופתו על קצותם שסובב מקצה השמים דלעילא בטה\"ע שנק' שמי השמים עד קצה התחתון בבחי' יסוד דמל' שבמערב והוא לפי שמקצה השמים שרש מוצאו ע\"כ תקופתו כו'). ומ\"ש לאתנהרא ולאתשקאה ולנצצא מיני' הזכיר ג' מדרגות לאתנהרא בבחי' חב\"ד ולאתשקאה בבחי' חג\"ת ולנצצא בבחי' נה\"י והן ג' מדרגות חב\"ד חג\"ת נה\"י שבכל ספי' וגם ביסוד יש ג' מדרגות הללו שהן מושכל מורגש ומוטבע בחי' המושכל שביסוד [חז'] ז\"א הוא ראי' השכל שבלב. והמורגש הוא חג\"ת הוא התפעלות שכלי שבלב. ומוטבע הוא בלא התפעלות מורגשת כלל אך שנמשך לבו אחר השכל אלקי שרואה לבו בלא הרגשה מצד טבע הלב וכנראה בחוש שגם באיש פשוט כמו בחי' טבעי' בהבל לבו להמשיך אחר כל מושכל אלקי שבלבבו יכיר כו' אעפ\"י שאין מבין בהשגת שכל כלל וכלל כו' וד\"ל. ומ\"ש לאתנהרא כו'. הכוונה להאיר ולהשפיע למקבל ואמר ג' מדרגות באופן ההשפעה למקבל לאנהרא ולאתשקאה ולנצצא כו'. הענין הוא דכל בחי' הארה והשפעה למקבל א\"א כ\"א ע\"י בחי' הכלים"],[2400650214,"דוקא והיינו ג' מיני כלים לנגד ג' מיני אורות חב\"ד חג\"ת נה\"י. והנה ידוע דמריבוי האורות מתהווה הכלים וכל שהאור אינו מאיר בריבוי רק במיעוט אין הכלי שלו רק במיעוט וכל שיתרבה האור יתרבה הכלי כי האו\"כ הוא כמו חומר וצורה כו' כידוע שהכלי הוא בחי' הישות כו' וכל שהצורה נתוסף אורה בהכרח שיוכן לה חומר בריבוי והוספה לפ\"ע תוס' האור וראי' לזה מימים ושנים של התינוק שיתרחב חומר הכלי מוח ולב לפ\"ע הרחבת הצורה שהוא גידול אור השכל והמדות כמ\"ש לפי שכלו יהולל איש. וכמ\"ש במ\"א (ואעפ\"י שמבואר בע\"ח דבנין הכלים נבדל מבנין האורות וכמ\"ש למעלה בביאור המאמר אינהו מנהרי בגרמייהו כו'. גם זה אמת דהחומר נבנה תחלה בשביל השראת הצורה אבל אם לא הצורה לא הי' בנין החומר כלל וכמו יצי' האדם בבטן שהוכנו בט\"ח מעט מעט כל איבריו לפ\"ע הצורה הנגדלת בעיבור ט\"ח כו') ודוקא בחי' תוס' וריבוי האור גורם ריבוי הכלים (ע\"ד דוגמא כאשר התינוק יגדל בשכלו יותר מוכן חומר כלי מוחו להיות קולט היטב וכן במדות שבלב כו'). והנה ידוע שיש ג' כלים פנימי' ואמצעי' וחיצוני'. פנימי' הכלי לקבל אור דחב\"ד. ואמצעי' לקבל אור דחג\"ת וחיצוני' לקבל נה\"י. ונק' סת\"ר סו\"ף תו\"ך רא\"ש וכמו אור החסד או אור החכ' שכלול מג' אורות חב\"ד חג\"ת נה\"י בהכרח שימצא ג' מיני כלים שהן בחי' חומר לקבלת הצורה לחב\"ד דחסד וחכ' והחומר שלו הוא נק' פנימי' הכלי' כמו אותיות המח' לגבי השכל או חסד שבלב ולבחי' אור חג\"ת דחכ' או חסד יש כלי אמצעי חומר מיוחד לבחי' צורה דחג\"ת שבשכל וחסד והוא כמו אותיות הדבור ולצורה הג' שהוא נה\"י דשכל וחסד שהוא אור הנמשך ונשפע למקבל כו' יש כלי חיצוני' שהוא החומר חיצוני מיוחד אל זה דוקא. וכך יובן בג' מדרגות דחב\"ד חג\"ת נה\"י דיסוד ז\"א שהוא בא להאיר במל' בכל ע\"ס דמל' והיינו מלמ\"ד כלים דז\"א שכלולים ביסוד ז\"א בבחי' חומר לג' אורות חב\"ד כו' שבו כנ\"ל (והן שלשים הגבורים שהיו לדוד שעזרו לבחי' המל' בלא לב ולב. שזהו מאור יסוד אבא שביסוד ז\"א כו'. וזהו האשה נקנית בג' דרכים דיסוד ז\"א ובבחי' הכלים המה שלשים מעלות כו'. וכשהן בחג\"ת דז\"א נק' ששים גבורים כו') וכידוע. וז\"ש לאנהרא למל' בבחי' כלים דחב\"ד דיסוד ז\"א בפנימי' הכלים שבמל' שנעשה בחי' נשמה דבריאה וגם לאתשקאה בבחי' אמצעי' הכלי' דחג\"ת דיסוד כו' ולהיות בבחי' רוח דיצי' ולנצצא מיני' בבחי' חיצוני' הכלים דנה\"י דיסוד שנעשה בחי' נפש דעשי' ואין לך איש מישראל שאין לו נפש דעשי' עכ\"פ שהקב\"ה נותן כו'. ששרשו הוא בחיצוני' הכלי' דנה\"י דיסוד ז\"א שהרי ידוע כללי' הו\"ק דז\"א כולל ס\"ר שרשים דנש\"י כידוע. וזהו ותקופתו על קצותם שאור"],[2400650215,"השמש שהוא אור הזרוע לצדיק יסוד ז\"א בחי' סוכ\"ע דמל' דאצי' בבי\"ע היא שמאיר עד גם היותר אחרון שבישראל ששרשו רק בבחי' עקביים שהוא מל' דמל' דעשי' כי כל ישראל בני מלכים מבחי' מל' ול' כלים שביסוד נעשי' נר\"נ בבי\"ע ולזה הטעם האוכל חמץ ונכרתה הנפש מיום הראשון עד יום כו' וכמ\"ש במ\"א וד\"ל ולהיפוך גם הקל שבקלים לא נפסק אור שרש נשמתו לגמרי דאע\"פ שחטא ישראל הוא גם ישראל מומר וכה\"ג כידוע ולכך כל ישראל יש להם חלק לעוה\"ב אפי' פושעי ישראל וכמ\"ש במ\"א ע\"פ אספו כו' כידוע וד\"ל:"],[2400650216,"<h3>ואין נסתר מחמתו</h3>\n(נד) <b>וזהו</b> אין נסתר מחמתו. פי' בזהר שם וז\"ל. ואין נסתר לית מאן דמתחפיא מההוא נהירו דהא לכולא אנהיר בכללא חדא לכל חד וחד כמה דאתחזיי' לי' ע\"כ. כי הנה מבואר למעלה בתחלת המאמר דבחי' אור עליון דבחי' יסוד ז\"א שנק' שמשא נהיר לכל אינון גוונין נהורין דלתתא דהיינו בכל קומת בנין המל' בבי\"ע עד צמצום היותר אחרון [שבסוף] העשי' ע\"כ א' לית מאן דמתחפי' מיני' בהסתר וצמצום דשם אלקי' דמל' גם בצמצום דאלקי' היותר אחרון אין נסתר ממנו להיות ידוע דשם אלקי' הוא בחי' הצמצום וההסתר ע\"ש הוי'. כמ\"ש כי שמש ומגן הוי' אלקים והיינו בחי' צירופי אותיות שכח אור אלקי מוסתר בהן להתהוות נברא בע\"ג מאין ליש נפרד כו'. וכל שהאותיו' באים ויורדים למטה בצירופים שונים יותר נסתר ונתמעט שם הארת אור אלקי' דהוי' דאצי' וכידוע שיש ק\"ך צירופי' בשם אלקים ומ\"ח צירופים האחרונים משם שורש יניקת הע' שרים דעשי' שמקבלים מבחי' אחוריי' דשם אלקים שמוסתר שם בתכלית ההסתר. וכמ\"ש במ\"א בענין ומופתים באדמת בני חם כו'. וזהו גווני נהורין כי המל' נק' בחי' מראה וגוון בבחי' הארה דהארה לגבי שם הוי' דאצי' וכמ\"ש מראה דמות כבוד הוי' וכמ\"ש בזוהר בבחי' שם ב\"ן נ\"ב גוונין כו'. וגוונין נהורין דלתתא היינו בחיצוני' הכלים דע\"ס דעשי' גם שם מאיר אור דצ\"ע בחי' יסוד ז\"א כי אין נסתר מחמתו לפי שאין ההסתר הזה בא רק מצד בחי' הצמצום דשם אלקים כו'. אבל א\"ז הסתר כלל לגבי עצם האור דהוי' כו' (וכמ\"ש במ\"א בביאור ענין כהדין קמצא דלבושי' כו'. וכמשלים וחידות שאינם מעלימי' לגבי המשפיע) וז\"ש ולית מאן דמתחפי' ע\"י צמצום אלקים מהאי נהירו דשמשא (וראי' ממה שמצינו ביוסף שהוא בבחי' יסוד צ\"ע והי' איש מצליח וה' עמו בכל אשר עשה גם בהיותו בבה\"ס ובגלות מצרים הגם שהי' שכינה שהיא בחי' המל' בתכלית ההסתר. אבל בחי' יסוד ז\"א הוא מאיר בגילוי ואין מסתיר לפניו כלל גם בבחי' גלות שהוא עת אשר שלט האדם כו' בהסתר דב\"ן דנוגה כו'. שהרי הי' יוסף איש מצליח כו' וכך כל צדיק שבכל דור ודור כו'). (ושרש הדברים גם מה שבחי' יסוד דוקא אין נסתר מחמתו יותר משאר אורות דאצי' שהן באי' בהעלם כו'"],[2400650217,"לפי שנק' סיומא דגופא ששם גמר כל השפעות היותר עליונים כי נעוץ כו'. ונגלה בו אור העצמות ששם גם חושך לא יחשיך כו' (וכמו בעצם הטוב להיטיב מתגלה כל בחי' עצמותו ולא נשאר לעצמו כלום כו'). וכמ\"ש במ\"א בפי' הזהר ע\"פ בקר אערך לך ואצפה דוד אתקין האי חופאה לחפי' האי בוקר דיוסף כו' דלא יכיל למסבלי' כו' והוא בחי' המל' בחי' דוד שעושה חופאה להלביש ולהעלים אור העליון דיסוד ז\"א שהוא בוקר דיוסף והיינו ע\"י תו\"מ בגשמי' כו'. ומבואר שם הטעם משום שנתגלה בסוף עיקר ההתחלה כו'. ולזה א' כאן דלית מאן דמתחפי' כו' גם בבחי' הצמצום היותר אחרון דבחינת אלקים כו' מטעם הנ\"ל. וכמו שיהי' לע\"ל דכתי' ונגלה כבוד הוי' וכמארז\"ל שיוציא חמה מנרתיקה שהוא שם אלקים שנק' מגן ונרתק להסתיר לשם הוי' דשמשא ואז וודאי אין נסתר מחמתו כלל וכידוע שלע\"ל יהי' אור הוי' מאיר בכל השתלשלות דבי\"ע בהשוואה א' בלי חילוק מדרגות כלל מפני שאין חילוק מדרגות בא רק מצד ההסתר אם מעט או רב כידוע. ולע\"ל יהיה הוי' א' ושמו א' דיחו\"ת ויחו\"ע שוין להיות שוין בקומתן וכמ\"ש והי' אור הלבנה כאור החמה כו' ע\"כ יהי' אור א' שוה לכולם. כמ\"ש קטן וגדול שם הוא וכתיב כולם ידעו אותי מקטנם כו' וידע כל פעול כו' וכמ\"ש וראו כ\"ב כו'. וכן ונהרו אליו כל הגוים כו' ובא במערות צורים כו' וכה\"ג לפי שיהי' גילוי אור דסוכ\"ע שהוא בחי' יסוד ז\"א בלי נרתק דשם אלקים וכך הוא גם עכשיו בהיות הנרתק דשם אלקים אין נסתר מחמתו כו' כמ\"ש אני ראשון כו' ומבלעדי אין אלקים כו' וד\"ל. וז\"ש הטעם בכאן דהא אנהיר לכולא בכללא חדא שהוא בלי חילוק מדרגות כלל מטעם הנ\"ל. ומ\"ש לכל חד וחד כמה דאתחזי' ליה אין זה כסותר דבריו דגם שיהי' בחילוק מדריגות לכ\"ח וחד כמה דאתחזי' ליה דוקא אבל לא מחמת סיבת הצמצום אם מעט אם רב כו' מאחר שאין נסתר מחמתו כלל רק מצד עצם אור עליון זה שיומשך עכ\"ז לכאו\"א כפי מדריגתו וכמו שבמ\"ת הי' גילוי אור כללי לכללות נש\"י ואעפ\"כ משה קיבל כפי מדריגתו ואהרן כפי מדרגתו וכך בכל א' מישראל לפ\"ע כו'. וכן לע\"ל דכתי' וא' ביום ההוא הנה אלהינו זה שכ\"א מראה באצבעו כו' כמ\"ש עין בעין נראה כו' עכ\"ז יהי' נראה לכא\"א כפי מדרגתו דוקא וז\"ש דאנהיר בכללא היינו כמו דקמי' כחשיכה כאורה הכל שוין כו' רק שנגלה בכ\"א לפ\"ע ולא מצד הצמצום כלל (כמו מצד האי חופאה דאתקין דוד כו' שהוא קיום המצות של כ\"א לפ\"ע עכשיו שבודאי מאיר אור אור עליון דצ\"ע בכאו\"א מישראל גם במי שאין לו רק נפש דעשי' ואין הצמצום האחרון דנוגה שבנפשו הבהמית מסתיר כלל לגבי אור זה מטעם הנ\"ל ועכ\"ז מאיר בכ\"א לפ\"ע במעשיו ממש כו'). והפשוט בפי' ואין נסתר מחמתו היינו מצד תקיפות האור כי כחו חזק ורב עד שאין נסתר לפניו גם היותר"],[2400650218,"חשוך כמשל האור הגדול שמאיר גם בחשך ואפילה גדולה לא יסתירנו כו' (וכמו ויאמר אל בלעם כו' ונק' תוקפא דשמשא כמו בצהרים כחום היום כו' תגבורת החסדים ביותר). ומ\"ש עוד בזהר וכדין תורת הוי' תמימה משיבת נפש. פי' וכדין לאחר שחתן יוצא מחופתו שזהו שמשא בחי' יסוד אבא שביסוד ז\"א להאיר למל' בכל קומתה עד שאין נסתר מחמתו כלל אזי דוקא תורת ה' תמימה בלי חסרון דתור' הוי' זהו בתושבע\"פ דוקא שמקבל מתושב\"כ כידוע דאורייתא שהוא תושב\"כ בז\"א דמחכ' עילאה נפקא ונק' פנים מאירות כפני חמה שמאיר בפני לבנה וכמו שידוע בכל הלכות דתשבע\"פ דא' מנלן אמר קרא מ\"ט דר' פלוני א\"ק כו' וכמ\"ש במ\"א באריכות וידוע דשיתא סדרי משנה הן בבחי' ו\"ק דנוק' דז\"א סדר זרעים בחסד דנוק' כו' שמקבלים מתושב\"כ שהוא בחי' ז\"א וע\"כ נקרא תורת הוי' תמימה דז\"א ותושבע\"פ מל' קרינן לה שם הוא עיקר הבירור דעה\"ד טוב ורע כשר ופסול טמא וטהור כו' שהן בו' סדרי משנה וכתי' תנו עוז לאלקים שהוא שם ב\"ן ח\"ת דמל' דתושבע\"פ שנק' אלקי' שיהי' בכוחו לברר הכל ולא יהי' בחי' הסתר כלל מסט' דטמא ופסול כו' ואין בכח ועוז לאלקי' רק מבחי' שם הוי' דתושב\"כ שבז\"א להיות נק' תמימה כידוע דבכח הדכר לברר כי האיש דרכו לכבוש כו'. ולזה אמר וכדין דוקא כשישיש כגבור לרוץ אורח להאיר בתושבע\"פ מל' קרינן לה עד שאין נסתר לפניו כו' אזי נק' תורת ה' תמימה משיבת נפש שמשיב נפש בעלי' כמו א\"ח מי ימצא כו' בטח בה לב בעלה כו' והוא ענין שבת וינפש דשבת בא אחר בחי' הבירורים דחול שבח\"ת דמל' אתברירו בבחי' שם ב\"ן דתושבע\"פ דוקא כנ\"ל רק הכח והעוז ניתן לה משם הוי' [דז\"א] וז\"ש משיבת נפש בשבת שבת להוי' כו' וד\"ל. ועוד יתפרש בפי' תורת הוי' כו' שא' ע\"ז וכדין שהוא בתושב\"כ בהוי' דז\"א דוקא כי גם בתורת הוי' דז\"א שהוא תושב\"כ יש ג\"כ ששה מדות והן ו\"ק דז\"א וכמ\"ש להבדיל בין טמא לטהור כו'. ואע\"פ דאורייתא מחכ' עילאה נפקת אבל ביומין דחול יורדין לברר בירורים כו' דבחכ' אתברירו היינו בח\"ע כו' והוא מ\"ש מקצה השמים כו'. ותקופתו על קצותם בו\"ק דז\"א שבכל יומין דחול הוא בא בהסתר לברר כו' אך בשבת בא בגילוי אור דוקא לפי שבשבת הרי בחי' ז\"א דאצי' מקבל מבחי' פנימי' דאו\"א עצמם כנ\"ל בפי' השמים מספרים כו' ואז נק' תורת הוי' דז\"א בשם תמימה בשלימות המוחין דאו\"א עצמן כמו שהם בבחי' הכתר שהוא בחי' הטעמי' כידוע בענין טנת\"א כו'. וכמו הטעמים שבתושבע\"פ מ\"ט דר' פ' כו' שהוא שלימות המוחין דמדות כשר ופסול שבלא טעם עדיין כו' וד\"ל. וז\"ש וכדין אחר שמאיר יסוד אבא ביסוד ז\"א בגילוי בשבת שמאיר שם מבחי' פנימי' ג\"ר דאו\"א תורת ה' תמימה משיבת נפש דכנס\"י שהוא בחי' נשמה יתירה שנמשך בגילוי לכאו\"א"],[2400650219,"מישראל משום שנא' כי בו שבת וינפש בבחי' עצמי' אא\"ס שבג\"ר דאו\"א הוא שמאיר בכאו\"א מישראל כי שבת וישראל ותורה שרש א' להם דתלת קשרין כו'. דס\"ר נש\"י קשורים בס\"ר אותיות דתושב\"כ ושבת הוא אות ביני ובין בנ\"י כי הכל שרש א' בבחי' העצמי' דוקא ולזה א' משיבת נפש בחי' נשמה יתירה שבכאו\"א מישראל שזהו עיקר האות דבנ\"י והוא ע\"י הארת אור דיסוד ז\"א בכל ניצוץ אלקי שבכאו\"א מישראל גם במי שאין לו רק נפש דעשי' מטעם הנ\"ל דס\"ר נשמות שרשם בו\"ק דז\"א כו' וד\"ל:\n(נה) <b>תורת</b> ה' תמימה משיבת נפש עדות ד' נאמנה כו'. ז\"ל הזוהר שם וכד כולהו אשתלימו ואתנהירו מגו שמשא כדין סיהרא מתעטרא בגוונא דאימא עילאה שלימא בנ' תרעין ודא איהו דכתי' תורת ה' תמימה דהא כדין איהו שלימא תמימה מכל סטרין ברזא דחמש דרגין כגוונא דאימא עילאה דאינון חמש רזא דחמשין תרעין ובג\"כ איהו אתי' בחמש חמש תיבין בגין לאשלמא לרזא דחמשין תורת ה' תמש\"נ הא חמש עדות ה' נאמנה מ\"פ הא חמש. פקודי ה' ישרים מ\"ל הא חמש מצות ה' ברא מ\"ע הא חמש יראת ה' טהורה ע\"ל הא חמש. משפטי ה' אמת צ\"י הא חמש. וכולהו אתיין בחמש חמש לאתכללא בגוונא דאימא עילאה וע\"ד הוי' שית זמנין לקבל שית סטרין עילאין דאינון רזא דשמא עילאה ע\"כ. והנה תחילה י\"ל כללות ענין המאמר שהוא בענין נו\"ן תרעין דבינה אימא עילאה ואח\"כ ית' פרטי דבריו דהנה ידוע בענין נש\"ב שהן מבחי' ה' חסדים דאימא שכ\"א כלול מיו\"ד ע\"כ הן נו\"ן וה\"ח הללו היינו מחסד עד הוד דבינה עד הוד אתפשטת ויש יו\"ד שערים בחסד וי' שערים בגבו' כו' עד יו\"ד שערים שבהוד כו'. ואח\"כ כל הנש\"ב באים ונמשכים ביסוד ז\"א בה\"ח שביסוד ומשם נמשכים כל אלה הנש\"ב במל' דאצי' ונק' תרעין תתאין ונש\"ב עצמן נק' תרעין עילאין כמ\"ש שאו שערים ראשיכם ב\"פ. הא' על נש\"ב שנק' תרעין עילאין והב' על נ\"ש שבמל' אימא תתאה ששם אמר ה' צבאות כו' וכמ\"ש בזוהר והיינו כללות ענין דכאן במ\"ש דסיהרא שהוא בחי' המל' מתעטרא בגוונא דאימא עילאה בחי' בינה בנש\"ב דיוצאין ביסוד ז\"א ונמשכים לבחי' המל' וז\"ש כאמה בתה כו' והוא מ\"ש דאשתלימו ואתנהרו מגו שמשא דוקא שהוא מפני שהמל' מקבלת נ' תרעין בגוונא דנש\"ב מבחי' יסוד ז\"א דוקא כנ\"ל. ולהבין בה\"ד הנה תחילה י\"ל שרש ענין נש\"ב להיות ידוע שאור החכ' נתחלק לל\"ב נתיבות ונק' ל\"ב נ\"ח כו' (וכמו ל\"ב חוטי דציצית וכמו ל\"ב ויאמר דמע\"ב דאבא אמר לאימא) וכמו\"כ יש ל\"ב שבילין שמתפתחים כו' והן ל\"ב חדרים שבמוח שנתחלק ע\"י הדעת וכמ\"ש בדעת חדרים ימלאון. וי\"ל למה החכ' נתחלק ללב\"נ והבינה"],[2400650220,"נתחלקת לנ\"ש ואם מפני ה\"ח שבאימא מחסד עד הוד כו' הרי גם בחכ' [יש] בחינת חסדים יותר כידוע דאור אבא מקור החסדים כו'. אך הנה ידוע שהחכ' נקרא אין והבינה נקרא יש כי חכמה כ\"ח מ\"ה שהוא בבחינת ההעלם עדיין רק שבא לידי גילוי מן ההעלם בבינה שהוא בבחי' השגה ותפיסה בהסבר הדבר לאורך ורוחב כו'. אמנם הנה בחינת גילוי ההעלם דחכמה אינו כמו גילוי ההשגה והתפיס' דבינה עצמה שנקרא יש גמור שמושג ומובן בהשגת דבר מה במוח הבינה אלא זהו רק בחינת המשכה מצומצמת מאוד מה שבא כח ההעלם דנקודת חכ' לידי התפשטות חוץ ממקומו בבינה (ובחינה הנקרא שביל דקיק דבי' עייל אבא לאימא הוא שער החמשים כמ\"ש במ\"א בענין ולא ידע איש את קבורתו לעליונים נדמה להם למטה כו' בחי' ממוצע כו') כי אינו עדיין בבחינת [גילוי] השגה כלל רק הוא בחינת המשכת מ\"ה ואין דחכמה כשנמשך בבינה שנקרא יש שהרי אנו רואים שכל מושכל שבנקודה דחכ' בא בהשגות שונות זמ\"ז בכמה מיני הסבר והמושכל א' הוא רק שהי' תחילה בהעלם בלתי נמשך לבוא כלל בהשגה (כמו שכל הנעלם מכל רעיון בהשגה והוא בחינת ח\"ס דלא מתחלק כלל לל\"ב כו') וזהו ל\"ב נתיבות דחכ' שהן כמו נתיב קצר שהילוכו בהעלם וצמצום גדול ואמנם מה שיש בכח דבינה להשיג בהשגה והסבר אינו רק מהמשכת כח מ\"ה [זה] דנתיבות חכמה שנמשך שם (וכמו ל\"ב ויאמר שהן ל\"ב נ\"ח בבינה שנקרא אלקים דאבא א' לאימא ואימא נקרא אומנא הבונה כו' כמ\"ש בזוהר בראשית) והוא קוצו של יו\"ד התחתון שעז\"א הבן בחכמה וחכם בבינה שממנו נעשה צורת ה' בהשגה לאורך ורוחב כמ\"ש במ\"א) והטעם למספר ל\"ב דוקא משום דהוי' ואדני ח' אותיות בחסד וח' אותיות בגבורה וד\"ע דמזווג חכמה לבינה כולל ב\"פ י\"ו שהוא ב\"פ חו\"ג שבחו\"ב שכ\"א כלול מח' אותיות (כמ\"ש במ\"א בענין מצנפת ואבנט דכה\"ג שהי' ארכו ל\"ב אמה מטעם זה כו'). (וכמו בד\"ת המחלק למוחין דחו\"ב לחו\"ג שכולל ב\"פ י\"ו מטעם הנ\"ל והן ל\"ב חדרים שבמוח כמ\"ש במ\"א בענין ד' בתים דתפילין ונקרא ל\"ב שבילין דמתפתחין כו') אבל ענין נש\"ב הוא מצד התחלקות ההשגות שמתחלקים בז' מדות דבינה שנקרא בשם מדות שבשכל שכל המסביר בטוב טעם לזכות ולחוב וז' פעמים זיי\"ן הן מ\"ט וכמ\"ש בזוהר ע\"פ נודע בשערים בעלה באינון שערין דבינה ששרש מדות דז\"א שבלב נודע בשערים דבינה שהן המדות שבשכל ובחינת התפעלות המוח לחו\"ג מצד השגות שכלי' מחולקים לחו\"ג כו' וכ\"ז נקרא שער כמו שער שבו נכנס ובו יוצא כו' אך כל אלה השערים הוא בא בבחינת השגה נגלי' דוקא ובהיותם בהשגה שבמוח בינה עדיין נקרא תרעין עילאין (והשרש שלהם הן בחי' ה\"ח דאימא כי גופו של אור הבינה הוא"],[2400650221,"רק בחינת כח ההשגה עצמה טרם שמתחלקת להשגות ששייך לחוץ מן עצם המושג והוא להטות כלפי חסד או כלפי דין וע\"כ יש יו\"ד שערים של חסד וי' שערים של דין כו' עד י' שערים של הוד כי עיקר המדות הן חמשה חג\"ת ונו\"ה ויסוד הוא רק בחינת המעבר שבו עובר כל שפע המדות כידוע וזהו שאח\"כ נמשכין הנש\"ב ביסוד ז\"א כו'. ואמנם עכ\"ז הן מ\"ט שערים במספר מכוון לנגד ז\"מ שבבינה בה' מדות כ\"א כלול מו\"ס הן נ' יו\"ד שערים לחסד כו' דהיינו גם מבחינת כח\"ב או חב\"ד של כל מדה משא\"כ בז\"מ שבבינה אין שם בחינת ג\"ר דכל מדה כו'. ע\"כ כל מדה אינה כלולה רק מז' והן זפ\"ז שהוא מ\"ט אך כללותם הוא בה\"ח דאימא בלבד והן ה' תיבין כמשי\"ת) (וכמ\"ש בענין לך ה' הגדולה כו' כי כ\"ל ל\"ך נש\"ב וכל הוא בהמשכתם ביסוד ז\"א שנקרא כל דאחיד כו') אך הוא בחינת נש\"ב שביסוד טרם בואם לבחינת המל' הגם שנמשכו ויצאו מבחינת בינה במדות דז\"א עדיין הוא בבחי' תרעין עילאין (כמ\"ש לך ה' הגדולה כו') (ועז\"א שאו שערים ראשיכם כו' וכן נודע בשערים בעלה כו' וכן בשבתו עם זקני ארץ הן בחינת אורות דאו\"א עצמן) אבל בבחינת המל' שזהו בחי' הדיבור שבא בהתגלות יש ודבר בדוגמא לדיבור האדם שמגלה מצפון השכל שבמוח ומדות שבלב כו' כידוע נקרא תרעין תתאין כו' וד\"ל. ומעתה יתבארו פרטי דברי המאמר במ\"ש וכד כולהו אשתלימו ואתנהירו מגו שמשא היינו כאשר נש\"ב שביסוד מאירים במל' להיות בבחינת ומדריגה דתרעין עילאין ממש וכמ\"ש כאמה בתה דהדיבור אעפ\"י שהוא בחינת יש ודבר נבדל מן העצמות אבל ע\"י הארת יסוד אבא שביסוד ז\"א נמשך מאור נש\"ב עצמן בדיבור ג\"כ (ע\"ד הנ\"ל בראי' השכל שבלב שאז גם בחי' ה\"ח דאימא שהן נש\"ב שבמדות דבינה מתגלי') (והוא ע\"י הדעת שמחלק לל\"ב חדרים במוח ומתפשט בלב ונק' מפתחא דכליל שית כו' ולכך שית זמנין ה' תיבין שהן שית סדרין עילאין בחינת ו\"ק דאימא שכלולים בדעת דאבא כו'). וז\"ש סיהרא מתעטרא בגוונא דאימא עילאה שלימא בנ' תרעין ולא כמו שהן בצמצום בדיבור שנקרא תרעין תתאין כו' ודא הוא תורת ה' כו' ה' תיבין עד משפטי ה' כו' והוי' שית זמנין כנ\"ל בא לתרץ בזה דהלא שרש הנש\"ב אינו רק ה\"ח ולמה א' שית זמנין ה' תיבין ומתרץ משום דהוי' באור אבא דוקא ולפי שגילוי נש\"ב במל' ע\"י אור אבא שביסוד ז\"א שהוא בחינת ו\"ק שבו (ע\"י בחי' דעת דאבא שביסוד הנקרא מפתחא דכליל שית כו') ע\"כ הן שית זמנין הוי' דאינון רזא דשמשא עילאה בבחינת ו\"ק דאבא עצמו וד\"ל (ושית זמנין ה' תיבין הן ל' מעלות דמל'). ומ\"ש משה זכה לבינה היינו לשער הנ' שהוא ממוצע בין חו\"ב כנ\"ל ושרשו ביסוד אבא דפני משה כפני חמה ולכך"],[2400650222,"כל ו' פסוקים הללו מדברים בשבח תושבע\"פ שהרי הזכיר המצוה והיראה שהוא במל' והוא מ\"ש דסיהרא מתעטרא כו' והוא ע\"י שמשא דוקא שהוא פני משה. כמ\"ש והוא כחתן כו'. וכמ\"ש במ\"א בענין תורה צוה לנו משה כו' וד\"ל (וכמו בה\"ח דאימא שהן נש\"ב א' כאמה בתה כך בבחי' ה\"ג מנצפ\"ך דאימא א' כאמה בתה וכמאמר אמה אוזיפת מאנהא לברתא וכמ\"ש במ\"א וד\"ל):\n(נו) <b>והנה</b> להבין בתוס' ביאור מ\"ש במאמר זה בענין [ה' תיבין] דתורת ה' כו' בגין דאשתלימו ואתנהירו משמשא נקרא תמימה דוקא כו' דהנה לכאורה נראה מפשט המאמר הזה שניתוסף שלימות בנש\"ב דמל' דלכך נקרא תמימה יותר מנש\"ב עצמן ובאמת כל עיקר הנ\"ש דמל' אינו בא רק מכח הנ\"ש דבינה והיינו מ\"ש דסיהרא מתעטרא בנו\"ן תרעין ומ\"ש שלימו מכל סטרין משמע שניתוסף בה שלימות מכל סטרין יותר ממה שקבלה וזה אא\"ל שיהי' יתרון למקבל יותר מן המשפיע שלא א' רק כאמה בתה ולא יותר ממנה וגם לא נמצא במל' רק נ\"ש ולא יותר אך עיקר הכוונה בשלימות זאת הוא מצד הארת אור יסוד אבא שביסוד ז\"א שיצא אחר שנבקע יסוד דאימא דוקא כנ\"ל באריכות הוא הגורם בחי' תוס' שלימות בנ\"ש דמל' וזהו שלימו מכל סטרין פי' גם מו\"ק דאבא שכלולי' ביסוד אבא ומאיר בכל ו\"ק דז\"א כנ\"ל בפי' ותקופתו על קצותם א\"כ הרי המל' שלימו מכל סטרין דאו\"א וז\"א כו' ולכך נקרא אז תורת ה' תמימה משא\"כ בנש\"ב עצמן הרי אור אבא שם בהעלם ביסוד אימא ולא בגילוי כי אין אור אבא מתגלה רק אחר יציאתו ממקומו ביסוד אימא לאחר בקיעת יסוד אימא כנ\"ל וד\"ל. ולהבין בה\"ד הנה תחילה ילה\"ק במ\"ש כאן שית זמנין ה' תיבין כו' לפי שהוא מדבר כאן בבחי' תושבע\"פ דוקא שהן ש\"ס משנה ואם מדבר בתושב\"כ הרי הם חמשה חומשי תורה והן נש\"ב יו\"ד שערים דחסד בספר בראשית כו' עד ספר דברים בהוד זה משה וכו' וראי' לזה ממ\"ש לשון נוק' תורת ה' מצות ה' יראת ה' רק מפני שמקבלת תושבע\"פ מתושב\"כ לכך נזכר הוי' דאבא בכל פסוק ופסוק והן בחי' ו\"ק דאבא ולזאת נק' תורת ה' תמימה בתוספות אור שלימות יותר מנש\"ב דה\"ח דאימא כנ\"ל וד\"ל. ויובן זה עפ\"י המבואר במ\"א באריכות בשרש ענין תושב\"כ ותושבע\"פ (שנק' ספר וסיפור) שתושב\"כ נק' פנים מאירות ותושבע\"פ נק' פנים מסבירות שבודאי אין דין והלכה בתושבע\"פ שאין לה ראי' מתושב\"כ לכך נקראת תושב\"כ פנים מאירות כפני חמה שמאירים בלבנה כו'. אבל אנו רואים שנמצאו בתושבע\"פ הרבה דינין והלכות בפרט שלא נודעו כלל בתושב\"כ גם לא ברמז ודרש כמו הלכות תפילין הגם שכל דין והלכה שבאו דרך פרט בהלכות"],[2400650223,"תפילין ודאי יש לו מקור ושרש ברמז ודרש מתושב\"כ אבל יש דינין הרבה מחודשים בתושבע\"פ שאין להם רמז כלל בתושב\"כ וזהו הנק' פנים מסבירות מב' טעמים הא' שבתושבע\"פ בדיבור פה בא הדבר בתוס' וריבוי גדול מאוד כמו פסוק וקשרתם כו' דתושב\"כ נדרש בתושבע\"פ כל הלכות תפילין וכן בסוכות תשבו שבעת ימים כל מס' סוכה וזהו שנק' הסבר שבא שם בריבוי גדול על דיבור א' אך עכ\"ז יש לכל ריבוי מקור ושורש כמו טיפת מ\"ד שמתגדל ולד ברמ\"ח איברי' בט\"ח או מזריעת חטה א' ריבוי שבולת או מענף קטן אילן גדול שכ\"ז בחי' התפשטות והתרחבות המקור כו' וכמו תלמיד שמקבל מרבו רק דיבור א' ודורש מזה תילי תילים הלכות וכך ר\"ע דרש ע\"כ קוץ וקוץ תילי תילי' של הלכות וכה\"ג וגם שנקרא חידוש רק עכ\"ז יוכל להיות שכל ריבוי המחודש אין כל חדש בו שכלול הכל במקור א' שהוא הרמז שבקוץ ותגין שבתושב\"כ וכה\"ג וכמ\"ש בהלכות שבת שהן כהררין התלוי' בשערה כו'. אך הטעם הב' שנק' מסבירות הוא מה שנמצא דיני' מחודשים לגמרי שאין להם מקור כלל שזה בא מכח דתושבע\"פ עצמה שלא באמצעות תושב\"כ כלל וזה פלא גדול וכה\"ג מצינו שיוכלו הסנהדרין לפסוק דין מכח עצמם כמו אל השופט אשר יהי' כו' וכן לעשות מועדים דכתי' אלה מועדי ה' אשר תקראו אתם אפי' מוטעין ועשו חג הפסח ביום המוקדם או ביום המאוחר האוכל בו חמץ ענוש כרת וביום שראוי להיות חג הפסח ואכל חמץ אינו ענוש כרת כלל וכה\"ג וכמ\"ש במ\"א באריכות וד\"ל. והנה להבין שרש הטעם לכ\"ז הנה מבואר למעלה באריכות בענין ותקופתו על קצותם דבחי' אור אבא מתגלה אחר בקיעת יסוד אימא דוקא כנ\"ל שזהו הטעם למה שאנו רואים שימצא בדיבור גילוי שכל מחודש לגמרי שלא הי' בדעתו ושכלו עליו כלל רק בהרחבת הדיבור בא ריבוי החידוש ממילא ומאליו כו' וזהו מצד בחי' יסוד אבא שבחזה כו' לאחר שנסתיים יסוד אימא דוקא כנ\"ל כי בהיות יסוד אבא מלובש ביסוד דאימא הרי שם הוא בהעלם ולא בגילוי אז אין שום חידוש שכל בא בדיבור כלל וכלל לפי שכאשר כלי הקליטה שבמוחו יכיל לעומק אור ההשגה דבינה הרי נקודת אין דחכ' נשאר בהעלם בבינה לכך לא ימצא שום חידוש רק כפי אופן הקליטה שבמוח כך יכוין לדבר לא יוסיף ולא ולא יגרע כו' אבל כשלא יכיל כלי הקליטה יפול נובלות שהן ריבוי דברים ואז יוצא בחי' נקודה דחכ' בגילוי בדיבור ויבוא בו חידוש רב שלא הי' במוח ההשגה כלל וכלל ונמצא יש כאן ב' דברים הא' הוא ריבוי ההסבר דברים שבא בדיבור כאשר נבקע יסוד אימא וממילא יבוא הדבר הב' שהוא רוב החידוש שמצד הדיבור בעצמו והוא מכח אור הנקודה דחכ' כח מ\"ה שבדיבור שלמעלה מן עצם ההשגה דבינה"],[2400650224,"גם למעלה מאור שפע דחכ' שבבינה שנשאר שם בהעלם כו'. ובכ\"ז יובן גם כאן בתושב\"כ ותושבע\"פ דתושב\"כ שרשו בחכ' דאור אבא שמלובש ביסוד אימא (וזהו ג\"כ באמת שרש משה שהי' כבד פה כו' ששרשו ביסוד אבא שמלובש ביסוד אימא בהעלם כמ\"ש במ\"א) והן ה' חומשי תורה שהן בחי' ה\"ח דבינה שמקבל מאור אבא כמו ויאמר הוי' דחכ' אל משה יסוד אבא לאמור בבינה כו' שהן אותיות התושב\"כ שנק' ספר כו' והוא ענין נש\"ב (ומשה לא זכה לשער הנו\"ן בחייו הגם שקיבל התורה כמשרז\"ל ע\"פ ותחסרהו מעט מאלקים שחסר לו שער הנו\"ן לפי ששער הנו\"ן בו הוא בחי' גילוי אור אבא מהעלמו בבינה וז\"ש ולא ידע איש כו' שהוא משה כו' כמ\"ש בזוהר בראשית ע\"פ לא טוב היות כו' ומבואר במ\"א) אבל תושבע\"פ הוא בחי' פנים מסבירות שבא בריבוי גדול בדיבור (ונק' נובלות חכ' של מעלה מאור אבא כענין נשים דברניות הן כנ\"ל) ויש בזה ב' דברים הנ\"ל א' עוצם הריבוי אך שמקבל ממקורו מטיפת אור אבא שבאימא שהוא ברמז בתושב\"כ שנק' ספר והב' דינין מחודשים לגמרי והוא כמו שכל וחכ' המתחדש בדיבור מצד שנגלה בו אור נקודה דחכ' כמו שהוא למעלה מן ההשגה דבינה דהיינו למעלה גם מבחי' ההשפעה דחכ' בהעלם דבינה שנק' ל\"ב נ\"ח כנ\"ל ולזאת יש יתרון מעלה בתושבע\"פ יותר מתושב\"כ כמ\"ש אשת חיל עט\"ב נקבה תסובב גבר וכמ\"ש במ\"א בענין ערבים עלי ד\"ס יותר מיינה ש\"ת כו' מפני שהחכ' שבדיבור שנק' ח\"ת שרשה נעלה יותר מאור ח\"ע שנק' ספר כשהוא בהעלם באותיו' דבינה בתושב\"כ וז\"ש חכמות נשים בנתה ביתה ונק' סופרים בבחי' סופר למעלה מספר וסיפור (דבחי' הדעת נק' סיפור כמשי\"ת בסמוך וסופר הוא בבחי' דעת דאבא דכליל שית כו'). ומעתה יתבאר שרש ענין זה המאמר בפי' תורת ה' תמימה שלימא מכל סטרין שזהו דוקא ע\"י גילוי אור אבא שיצא מהעלמו בבינה כו' דהיינו בגילוי יסוד אבא בדיבור דתושבע\"פ מל' קרינן לה שיש בה תוס' שלימות יותר מגופו של נש\"ב עצמן בב' דברים. הא' הריבוי הגדול והב' בחי' החידוש הרב מצד שרשו בפנימי' אבא יותר וד\"ל. ולזה א' כאן ה' תיבין שית זמנין ולא ה' זמנין נגד ה' חומשי תורה לפי שמדבר בתושבע\"פ שהן ש\"ס משנה והוי' בכל פסוק שהוא הוי' דאור אבא שבא בגילוי לאחר בקיעת יסוד אימא בדיבור דתושבע\"פ דוקא שהוא גבוה יותר מהוי' דתושב\"כ שהיא בהעלם בבינה כנ\"ל ולזה בא לפרש המשך הפסוקים דמשום דתקופתו על קצותם בכל ו\"ק דז\"א שהוא ו\"ק דאבא שכלולי' ביסוד אבא בגילוי בתושבע\"פ דוקא ע\"כ נק' תורת ה' תמימה כו' ועכ\"ז ה' תיבין בכל פסוק רק שניתוסף פסוק ששי לפי שהן בו\"ק דאבא כו', והיינו ש\"ס משנה שהן בו\"ק דנוק', חסד דנוק' סדר זרעים, גבו'"],[2400650225,"סדר מועד, ת\"ת סדר נשים, נצח סדר נזיקין, הוד סדר קדשים, ויסוד סדר טהרות, ויתפרשו לפי סדר הו' פסוקי' הללו תורת ה' כו' סדר זרעים עדות ה' כו' סדר מועד פקודי ה' כו' סדר נשים מצות ה' כו' סדר נזיקין יראת ה' טהורה כו' סדר קדשים משפטי ה' אמת כו' סדר טהרות ולפי דרשת רז\"ל ע\"פ חוסן ישועות חכ' ודעת יראת ה' היא אוצרו הרי דעת סדר טהרות כו' וכמ\"ש במ\"א ובכאן בבחי' ו\"ק דנוק' הוא מחסד עד יסוד ובחי' הדעת אינו נמנה דדעת דנוק' כלול בדכורא שהיא תושב\"כ כידוע ולפי שסדר טהרות הוא ביסוד דנוק' ששם עיקר גמר הבירור דרע לפתח חטאת רובץ ע\"כ הוא גבוה מכולן כמ\"ש במ\"א וד\"ל. (וגם זה אמת דדעת זה ס\"ט שהוא עיקר המברר שאם אין דעת אין הבדלה כו' ולזה נמשך בתושבע\"פ מדעת דאבא ע\"כ גבוה מכולן וכמ\"ש במ\"א וד\"ל):\n(נז) <b>ועוד</b> שם בזוהר (דף קל\"ז ע\"ב) וז\"ל. ועל דא סיהרא אתמליא ואשתלים בסידורא עילאה כדקא יאות ודא איהו ביומא דשבתא דכולא אשתלים כדקא יאות ברזא דשבתא עילאה ותתאה וע\"ד ביומא דא אתוסף נהירו בכולא כדקאמרן שמים נטלי ממקורא דחיי בקדמיתא ואינהו מנהרי ומתקני לכבוד עילאה מרזא דספר עילאה אבא דכלא ומרזא דספר אימא עילאה ואיהו מרזא דסיפור. ובג\"כ מספרים כדקאמרן ברזא דתלת שמהן אילין דשלטין ביומא דשבתא על כל שאר יומין ע\"כ. הנה מבואר למעלה בפי' השמים מספרים דהיינו בבחי' ג\"ר דאו\"א עצמן שמאירים בפנימי' ז\"א ביומא דשבתא. ז\"ש השמים מספרים וחוזר כאן לתחילת המאמר הראשון לפי שסיים כאן במילוי שלימות אור המל' בכל קומתה מאו\"פ דיסוד אבא שנתגלה ביסוד ז\"א לאחר שנבקע יסוד אימא כנ\"ל בפי' ותקופתו כו' עד תורת ה' תמימה כו'. וע\"כ חוזר לראש דבריו בפי' השמים מספרים כבוד אל שמשם בא שרש סיבת מלוי אור המל' שנק' סיהרא. וז\"ש וע\"ד סיהרא אתמליא ואשתלים כו' עד ברזא דשבת עילאה באו\"א עצמן ותתאה במל' דאצי' שנק' סיהרא והיינו דאתוסף נהירו בכולא ומפרש ואזיל סדר הוספת האור מראש לסוף והוא מ\"ש שמים נטלי ממקורא דחיי כו'. פי' מקורא דחיי הנה ידוע שבינה נק' אלקי' חיים בחי' התגלות אור וחיות להיות שבחי' בינה הוא בחי' התפשטות ההשגה וההבנה בכלי הקבלה עד שיחי' למי שמשיג היטב בחיות גמור כמו מפיו אנו חיין חמרא וחיי כו' והוא לפי שבהשגת ועיון התורה נא' חיים הם למוצאיהם כו' חיים ממש ונק' ארחות חיים. וכך למעלה נק' התורה חיי עולם בחי' גילוי האור וחיות באור וכלי כמו אמרתך חייתני כו' ואנו אומרים כי הם חיינו כו' וכה\"ג. אך כ\"ז בבחי' התפשטות דבינה אבל בחי' אין דחכ' שלמעלה עדיין מבחי' השגה דבינה כי הוא רק בהעלם כח מ\"ה לא שייך לומר"],[2400650226,"בו בחי' אור וחיות מורגש בגילוי גמור אלא הוא בחי' מקור הנעלם לגילוי אור וחיות המורגש הזה שבבינה ונק' חיים בעצם שלמעלה עדיין מבחי' התפשטות גילוי חיות אלא שהוא בחי' מקור מוצא כל גילוי אור וחיות שבא בהשגה כו'. (ומ\"ש והחכ' תחי' לא חיות בגילוי אלא הוא בחי' מקור חיים דוקא). וז\"ש כאן בהפרש שבין אור אבא דאצי' שנק' מקורא דחיי בבחי' אין והעלם ובין בחי' בינה שנק' חיים בהתפשטות החיות להיותו בא בבחי' השגה למקבל כו'. וז\"ש שמים נטלי ממקורא דחיי שהוא בחי' פנימי' דאור אבא מבחי' הג\"ר שבו וכמ\"ש כי עמך מקור חיים כו' בקדמייתא לפי שאין גילוי אא\"ס עצמו רק בכח מ\"ה דחכ' תחילה כו'. ופי' שמי\"ם אש ומים היינו בחי' חו\"ג דאו\"א כי אור אימא שהוא ההשגה נכלל באור אבא כי מה שהבינה נק' אלקים חיים בהתפשטות נכלל בעצם שהוא החכ' שנק' חיים כו'. ולכך א' ואינהו מנהרי ומתקני כו' ואינהו לשון רבים שהוא קדש דחכ' שכלול מבינה שנק' מקרא קודש ונק' שמים בכלל ומ\"ש מנהרי ומתקני להאי כבוד כו' הנה מבואר למעלה באריכות שהוא בחי' הבירורי' דאו\"ח שביומין דחול שנק' כבוד שבא מלמטה למעלה והוא בחי' עיגולים שנק' עזקא כו'. וז\"ש מנהרי ומתקני כו' בבחי' או\"י ואו\"ח שנק' נהירו ונציצו כו' כמ\"ש שם באריכות וד\"ל. והנה כללות המכוון ממ\"ש שמים נטלי כו'. הוא רק לפרש דבריו שא' תחילה במאמר זה דביומא דא אתוסף נהירו בכלא ור\"ל שנתוסף בכל ספי' וספי' דזו\"נ בפרט נהירו ותוס' זה הוא העיקר ושרש והיינו בחי' חב\"ד דכל ספי' ומדה דזו\"נ ששורש זה נמשך מבחי' הארת פנימי' דאו\"א עצמן בכל האורות דז\"א משא\"כ ביומין דחול שהי' בהעלם דבחי' חב\"ד דכל ספי' מלובש בקטנות דבחי' יניקה כו' כמבואר למעלה באריכות ובחי' פנימי' דאו\"א זהו בחי' עצמות ומהות הארת אור המוחין עצמיי' שמובדלים בערך מהיות מקור מוחין למדות כלל וכמו עצם המושכל טרם יבוא ממנה איזה נטי' להורות ע\"י איזה טעם לחוב או לזכות וכה\"ג והוא הנק' בחי' מוחין דגדלות דאו\"א כנ\"ל. ומזה נמשך בחי' מוחין דגדלות בפרט בכל ספי' וספי' ביומא דשבת דוקא ולזה א' דאיתוסף נהורא בכולא שהוא ע\"י הארת פנימי' ועצמי' המוחין דאו\"א בכל בחי' חב\"ד דכל ספי' וספי' ולכך הוא מפרש איך הוא חוזר לתחילת הוספת אור העצמי' בשמים עילאין עצמן והוא מ\"ש דשמים נטלי ממקורא דחיי אור אבא כו' כנ\"ל עד דאינהו מנהרי כו' וד\"ל. ומ\"ש מרזא דספר עילאה אבא דכולא כו'. הנה מבואר למעלה בענין ספר [וסיפור] וסופר כו'. ובכאן דיבר דרך קצרה בחו\"ב דאצי' שהמה נק' ספר בכלל רק שהחכ' שנק' אבא דכולא נק' ספר עילאה ומלובש ברזא דספר אימא עילאה ונכללים שניהם בבחי' הדעת שנק' סיפור וז\"ש מרזא דסיפור הכוללם יחד והן"],[2400650227,"רזא דג' שמהן דשלטין ביומא דשבתא על כל שאר יומין. פי' ג' מוחין הללו חב\"ד לפי שמהם נמשכים ג' מוחין דחב\"ד לכל ספי' וספי' בפרט לכל ימי החול דלהבא בבחי' המשכה דוקראת לשבת עונג כו' וכמ\"ש למעלה בענין ב' שבתות כהלכתן כנ\"ל באריכות הנה לזה א' דג' שמהן הללו שלטין ע\"כ שאר יומין דחול וד\"ל. ובג\"כ תושבחתא דא קאמר דוד ברוח קודשא על נהירו ונציצו ושולטנא שלימא דיומא דשבתא ע\"כ שאר יומין. פי' לנגד ג' שמהן הנזכרים למעלה שהן ג' מוחין דחב\"ד העצמי' הנ\"ל שנמשכים להיות בחי' חב\"ד בכל ספי' בכל יומין דחול ע\"כ א' ג' מדריגות נהירו ונציצו ושולטנא נהירו בבחי' אור החכ'. ונציצו בבחי' אור הבינה שבא בהשגה כו' ושולטנא הוא בחי' הדעת שכוללם יחד שנק' סיפור כנ\"ל. והטעם שנק' הדעת שולטנא יותר מחו\"ב עצמן (וגם מ\"ש תחילה דשלטין כו' קאי על בחי' הדעת שכוללם יחד כו') היינו לפי שענין השליטו הוא ע\"ד שלמטה ממנו שיומשך לפי אופן שירצה ויגזור עליו המושל וכמו כשגגה היוצאת מלפני השליט כו'. והנה ידוע דהמוח שליט על הלב להטותו ולהפכו מן הקצה לקצה שעיקר השליטה הוא להפוך ולהטות הדבר מאשר כבר נמשך לאופן היפוכו כך המוח שליט על הלב להטותו ולהפכו לאופן היפוך מאשר כבר נדבק ונתפעל כמו מאהבה לשנאה או להיפוך משנאה לאהבה וכה\"ג. וזהו הנק' לבו ברשותו שהוא ברשות המוח. ואמנם עיקר זה ששולט המוח על הלב הוא במוח הדעת דוקא והטעם הוא כי הדעת כולל חו\"ג ע\"כ הוא שיכול להטות מדין כלפי חסד כמו משנאה לאהבה או להיפוך וטעם ההטי' הזאת במוח הדעת דוקא אינו רק מפני השכל ומוחין של המדה כפי רצונו מהיפוך להיפוך דהיינו גם אותו שכל שיחייב לזכות וחסד יטהו אל ההיפוך שיחייב הדין והעונש וכן להיפוך משכל המטה כבר כלפי דין ועונש יטהו אל ההיפוך שיחייב החסד והטוב ולזה יש בכח הדעת להטות המדות מן הקצה אל הקצה ונמצא שבמוחין שבמדות הוא שליט וזהו מפני שהדעת כלול מחו\"ב וחו\"ג שבהן ולזאת שליט על הלב שיקבל המוחין שיהי' כפי הוראת הדעת דוקא (וכמ\"ש במ\"א בענין ד' בתים דתפילין שהדעת מתחלק לחו\"ג בב' מיני מוחין להטות שכל זה כלפי זה או כו' ונעשה חו\"ב ד' מוחין ומשם יפרדו לכמה מיני הטיות שונות והן ל\"ב חדרים שבמוח שע\"י הדעת כו'). וז\"ש שולטנא בבחי' הדעת דוקא שבחי' הדעת שכלול מחו\"ב הוא עיקר השליט על אופן המשכות המוחין דחו\"ב במדות לכל וי\"ו ימי החול והג' שמהן הנזכרים למעלה דשלטין ע\"כ שאר יומין היינו בחי' הדעת. וז\"ש השמים מספרים כבוד אל בבחי' סיפור דדעת שכלול מחו\"ב וע\"י יומשך לכל וי\"ו ימי החול מבחי' המוחין דאו\"א שבשבת כו' וד\"ל:"],[2400650228,"<h3>רננו צדיקים</h3>\n(נח) <b>ובגין</b> רזא דשמא עילאה דקא נהיר בנהירו ונציץ בנציצו ואשתלים בשלימו עילאה ותתאה. פי' שמא עילאה הוא בחי' אור הכתר שמאיר בחו\"ב נק' שמא עילאה להיותו נבדל ומרומם בערך כי הוא בחי' ממוצע בין עצמות המאציל לנאצלים כידוע ולכך כולל לג' שמהן הנ\"ל שהן ג' מוחין דחב\"ד. וז\"ש דשמא עילאה זה נהיר בנהירו דחכ' ונציץ בנציצו דבינה ואשתלים בבחי' הדעת שכולל לחו\"ב שנק' שלימא ומ\"ש עילאי ותתאי היינו בזו\"נ דז\"א נק' עילאה. והמל' נק' תתאה דאתייחדת בכורסיי' כו'. ומ\"ש בגין רזא דשמא כו' קאי אדלעיל מני' דא' דאיתוסף נהירו בכולא כו'. והוא תוס' דחב\"ד שבכל ספי' דז\"א וקאמר שכ\"ז התוס' בא בשביל רזא דשמא עילאה שהוא בחי' הכתר דחו\"ב והוא בחי' הרצון והעונג כמ\"ש כי בו שבת וינפש. וכמ\"ש למעלה (והוא המאיר גם בכל ספי' והיינו בחי' כח\"ב דכל ספי' וע\"ז רמז במ\"ש ואשתלים בשלימא עילאה כו'):\n<b>ואתקינו</b> אנשי כנה\"ג סידורא ושירותא דתושבחתא מאינון תושבחתין דדוד מרזא דא השמים מספרים כבוד אל דאיהו נטיל ברישא ונהיר לכל שאר ולבתר ההוא נהר דנגיד ונפיק מעדן ודא איהו רזא רננו צדיקים בה' בגין דהאי נהר כניס ונטיל כולא ושמשא אתתקן לאתנהרא ביומא דא. פי' במאמר זה בא לגלות סוד וטעם הסדר דאנכה\"ג שסידרו בשבת לומר מזמורים ותשבחות דדוד כמו בסדר שסדרו לומר אחר השמים מספרים מזמור דרננו צדיקים כו' ואח\"כ מזמור מזמור דלדוד בשנותו דסמיך לי' ומסתמא כוונו אנשי כה\"ג בסדר זה איזה סוד וטעם ומפרש הטעם דתחילה יאמרו השמים דאיהו נטיל ברישא כו' שהוא בחי' המשכת מוחין חדשים דאו\"א עצמן בפנימי' ז\"א. וזהו השמים דאיהו נטיל ברישא ונהיר לכל שאר ספי' ואח\"כ מזמור דרננו צדיקים בה' שהן בחי' יסוד ז\"א בכלל ובפרט יש בחי' יסוד בכל ספי' בפרטיות. והיותר נכון מה שקורא צדיקים אינו לשון רבים אלא קאי על ב' צדיקים צדיק עליון יסוד ז\"א בכלל וצדיק תחתון בחי' יסוד דנוק' כידוע וכללותו הוא רק בחי' יסוד ז\"א והוא מ\"ש ולבתר ההוא נהר דנגיד ונפיק מעדן כו'. (ויותר נכון לפי פשט המאמר שקורא נהר דנגיד כו' לבחי' יסוד אימא והשמים הן בחי' ג\"ר דאו\"א כו' ושמשא אתתקן הוא יסוד ז\"א כנ\"ל בפי' והוא כחתן כו'). ולהבין ביאור הדברים הנה יש להקדים תחילה בביאור ענין יסוד דדכורא שנק' צדיק עליון ויסוד דנוק' שנק' צדיק תחתון שע\"ז אמר רננו צדיקים כו'. להיות ידוע דכל בחי' יסוד אינו ענין מציאת ומהות ומדה בפ\"ע כמדת החסד או כמדת הדין. אלא הוא רק כח המביא את כל שפע איזה מציאת דבר מה אם חסד או שכל לבחי' גילוי למקבל דוקא. ואותו כח המביא להשפעה"],[2400650229,"למקבל נק' בחי' יסוד (ובדרך פרט יש בחי' יסוד בכל מציאת מדה כמו יסוד שבחסד שהוא הכח שמביא לחסד לידי השפעה וכן יסוד שבגבורה ושבנצח ושבת\"ת כו' וכה\"ג יסוד דחו\"ב כו'. וט\"ו יסודות שהן ט\"ו ווי\"ן שבאמת ויציב וט\"ו דיינו כו'. לפי שבה' פרצופים בכ\"א יש ג' יסודות בג' מדריגות דחב\"ד חג\"ת נה\"י כו' כמ\"ש במ\"א ויסוד דא\"א נק' טובך הגדול כו'). וכתי' אמרו לצדיק כי טוב שהכח הזה המביא לידי גילוי נק' צדיק וטוב ליתן מעצמותו לזולתו כידוע. וזהו בחי' יסוד דדכורא שהוא בולט על היות שבכחו להביא בליטת אור השפע לחוץ עד\"מ הידוע בפי' ה' נתן לי לשון למודים. וכן כל בניך לימודי ה' כו'. כמו בכל השפעות שכל מרב לתלמיד שאנו רואים שיש אדם שיוכל להשפיע אור אותו השכל והסברא שמשיג לעצמו להסבירה בטוב טעם לזולתו ברוב הרחבת דברים מאוד בכמה מיני אופנים שונים ובלשון צח ונקי' ונקל להבין עד שגם התינוק יכול להבין עומק השכל והסברא ההיא לפ\"ע ג\"כ לפי שהורידה באופן שיוכל גם התינוק לפ\"ע להבינה וזהו הנק' לשון למודים שהוא לשון שיכול ללמוד לכל כל דבר חכמה. משא\"כ אדם אחר אעפ\"י שחכם יותר ממנו יוכל להיות שאין לו לשון למודים כלל כי הגם שלעצמו מבין לתכלית העומק והחריפות אבל לזולתו לא יוכל לפרש ולהסביר כלל כי לא ימצא לשון שיפרש בהרחבת דברים כלל רק יאמר בדיבור א' ושתיים כפי מה שהבין לעצמו שלא יבין מזה זולתו כלל וכלל. והעיקר אין כאן רק ענין בחי' הבליטה מה שבזה יש כח הבליטה שיעשה לשפע כל שכל וחכ' בבחי' בליטה לחוץ מכמו שהוא בעצמו (בל\"א ער קאן ארוס שטעלן בולט בתכלית) עד שהכל יכולי' להבינו וכמו באותיות הכתב יש אדם שיוכל לבאר לשכל וחכ' להיות בולט בהשגה בנקל לכל כו'. והוא דמיון לבחי' יסוד דדכורא שהוא בולט להשפיע לחוץ ממנו כו'. כך הוא כח המסביר לכל דבר בהרחבת דברים ברורים (שנק' פטיט וכה\"ג) שזהו רק ענין כח בליטת השפע להגלות לכל. (וכמ\"ש בפי' אשר יאמר הגי שהוא בחי' יסוד דדכורא כמו ההוגה את השם כאשר הוגה כו'). אבל בחי' יסוד דנוק' שהוא שקוע שאינו רק בחי' בית קיבול דוקא שהוא כח כלי הקליטה שבתלמיד שקולט היטב אור שפע השכל ששומע דקליטה זו אם לעומק או לרוחב כו' הוא לפ\"ע השקיעה של בחי' בית קיבול שבמוחו. וכמו שאנו רואים שיש תלמיד שיוכל לקלוט הרבה ולא יתבלבל כלל וזהו ברוחב ואינו קולט לעומק כ\"כ וזולתו יקלוט לעומק יותר אבל לא ברוחב כי הרבה דברים לא יוכל לקלוט ולקבל ביחד כי יתבלבלו הדברים אצלו וכן יש בענין הזכרון שזוכר הכל ולא ישכח מאומה ויש קולט ושוכח כו' כי לא נקלט ונקשר בו היטב כמו פולטת כו'. (ויש קולט את השמרים ויש קולט את המובחר"],[2400650230,"אעפ\"י שאינו ברוחב כו') וכמבואר בד' מדות שבתלמידים כו'. וכ\"ז דמיון להבין למעלה בחי' יסוד דנוק' שהוא שקוע דוקא להיפוך מיסוד דדכורא כו'. וזהו בכל עו\"ע משפיע ומקבל בכלל ובפרט בחי' יסוד דעלול הוא שקוע לקבל כל שפע הבולט דדכורא וד\"ל. ומעתה יובן ג\"כ בענין ב' צדיקים. ב' יסודות דזו\"נ דיסוד ז\"א הוא כח אור עליון המביא כל שפע אור לחוץ למקבל שהוא בחי' המל'. וצ\"ת הוא בחי' יסוד דנוק' שקולט היטב לכל שפע מ\"ד דז\"א ונק' צדיק וצדק כידוע. ומ\"ש רננו צדיקים בהוי' ביומא דשבתא דוקא לפי שכל יומין דחול אור הזרוע לצדיק במל' בא למטה בבי\"ע לברר בירורי' דרפ\"ח כו' וכתיב הלוך ילך ובכה נושא משך הזרע אך בשבת בוא יבוא ברינה נושא אלומותיו אחר הבירורי' שבחול שהוא בחי' ההעלאה. וזהו ענין הרננה דוקא כמו המצליח במלחמה או עסק מו\"מ שירנן על טוב הצלחתו שניצל מן ההיזק ובא לעילוי כו' כמ\"ש במ\"א וד\"ל. וזהו ביאור פרטי דברי המאמר השמים פנימי' או\"א שבז\"א נטלי ברישא ואח\"כ נהיר ונגיד בבחי' יסוד ז\"א וע\"ד רננו צדיקים ב' יסודות דזו\"נ בהוי' העצמי' דאו\"א שבז\"א שנק' הוי' סתם מצד שלימותו העצמי' כנ\"ל. ומ\"ש ושמשא אתתקן היינו בחי' יסוד ז\"א כנ\"ל. והוא נהר דנטיל וכניש כולא כמ\"ש ותקופתו כו' ולהיותו ממולא מכל מיני מדריגו' דאורות העצמי' דאו\"א שבז\"א ע\"כ א' אתתקן לאתנהרא ביומא דא וד\"ל. וזהו כל עיקר הסוד והטעם שסידרו אנכה\"ג לרננו צדיקים אחר השמים מספרים שזהו כפי סדר ההשתלשלות בתחילה מוחין חדשים דאו\"א עצמן בז\"א ואח\"כ רננו צדיקים בחי' יסודות דזו\"נ ואח\"כ לדוד בשנותו שהוא בחי' המל' שבבי\"ע כמשי\"ת וד\"ל:"],[2400650231,"<h3>לדוד בשנותו</h3>\n(נט) <b>ולבתר</b> סיהרא דקא מתפרשת מסט' אחרא ביומא דא בגין לאתנהרא מן שמשא ודא איהו לדוד בשנותו את טעמו כו'. פי' סיהרא הוא בחי' מל' דאצי' כמו שהיא מסתתרת בבי\"ע להיות ראש לשועלים ונק' מאור הקטן לממשלת הלילה כמ\"ש לכי ומעטי א\"ע כו' דבהיות המל' בבחי' האצי' מקבלת מז\"א מבחי' פב\"פ כידוע עז\"א תחילה רננו צדיקים ב' צדיקים. צדיק וצדק שהוא ב' יסודות דזו\"נ כמ\"ש למעלה ולבתר ההוא נהר כו' עד ושמשא אתתקן כו' שהוא בחי' יסוד ז\"א ובחי' המל' בבחי' האצי' מקבלת מיסוד ז\"א ונק' צדיקים ואח\"כ א' לדוד שזהו גם בחי' המל' שמסתתרת בבי\"ע שזהו אחר הפסקת המסך המפסיק בין אצי' לבריאה כמ\"ש בע\"ח דהמל' דאצי' בוקע המסך ונעשה כתר וראש לבריאה וכמ\"ש במ\"א שז\"ש באורך נראה אור בחי' הארה דהארה ונק' דמות ומראה כבוד ה' ונק' כבוד תחתון כבוד נברא להיות בחי' מקור לבריאה יש מאין וכידוע שזהו בחי' שם אלקים בק\"ך צירופים דהיינו בחי' כהפב\"נ שמשתלשל בריבוי צירופי' עד שמחיה גם לע\"ש דנוגה דעשי' שנק' אלקי' אחרים שמקבלים"],[2400650232,"רק מבחי' אחוריי' דאחוריי' דשם אלקי' כמאן דשדי בתר כתפוי כו' והן מ\"ח צירופי' אחרונים שנק' אדמת בני חם כו'. וכמ\"ש מלך אלקי' על גוים כו' דמלכותו בכל משלה. וז\"ש דסיהרא מתפרשת מסט\"א כו' שהוא יניקת החיצוני' דע\"ש דנוגה שמקבלים מבחי' חיצוני' ואחוריים בבחי' גבו' קשות דנוגה שנק' סט\"א כו' דלפתח חטאת רובץ כו' ובשבת דמעלי שבתא כל דינין מתעברין מינה כו' שמתפרשת מכל דיני' קשים דנוגה (ולכך גם הגיהנם שובת מיד בקידוש ליל שבת). והטעם דמתפרשת מסט\"א הוא בגין לאתנהרא מן כו' משום דצריכה המל' לעלות בבחי' האצי' לאתנהרא מן שמשא שהוא בחי' יסוד ז\"א כו' דלא יגורך רע כתי' שלא יוכל לבוא לשם מבחי' הרע דנוגה כמ\"ש וכבודי לאחר לא אתן ע\"כ בהכרח דסיהרא המסותרת בע\"ש דנוגה להחיותם בחיצוני' ואחוריי' כו' שתתפרש מהם לגמרי בעלותה בבחי' האצי' לאתנהרא מן שמשא כו'. וזה תוכן פשט המאמר הזה. אך עדיין י\"ל מה שייכות יש לזה עם מזמור דלדוד בשנותו כו'. וגם לכאורה לא הי' צריך להפסיק במזמור דרננו צדיקים כו' דאחר השמים מספרים הי' מהראוי לסמוך מיד מזמור זה דלדוד בשנותו כו' כדי שגם המל' בבריאה תעלה ותקבל משמשא כו' ועוד דגם לפי דברי המאמר הזה בלדוד בשנותו כו' דסיהרא מתפרשת מסט\"א למה א' זה ביומא דשבתא הל\"ל בליל שבת דוקא שאז עיקר עליות המל' מבי\"ע כידוע. אך הנה תחילה י\"ל מהו ענין לדוד בשנותו את טעמו לפני אבימלך כו' בהיות מבואר בפע\"ח דפי' בשנותו את טעמו כו' דהיינו שהמל' פושטת בגדי חול ומתלבשת בבגדי שבת דוקא וכמאמר אפשיטת מלבושהא כו' דהנה ענין מלבושים דחול הוא לבוש שמתלבשת המל' לפי אופן העסק והמלאכה והעבודה שביומין דחול לברר לק\"נ לאהפכא כו'. ע\"ד שאמרו בגדים שבשלו בהן קדירה לרבו אל ימזוג בהן כוס כו'. שהבישול מלאכה גרוע וצריך להתלבש בלבוש גס ביותר משא\"כ למלאכה ושימוש דמזיגת הכוס וכה\"ג שצריך להתלבש בלבוש נאה כו' כך יובן בבחי' הבירורי' דנוגה דבי\"ע שהמל' מוסתרת בסוד גלות השכינה לבררם שצריכה להתלבש בלבושי' פחותים לפי אופן המלאכה והעבודה פחותה (וכמו בתרומת הדשן שצריך להפשיט הבגדים כו' וכמ\"ש במ\"א בענין מי זה בא מאדום חמוץ בגדים כו' וכל מלבושי אגאלתי כו') וכמ\"ש לעבוד עבודת נכרי' כו' וכשיורדת המל' עד היכלות דנוגה דעשי' לברר שם וכמ\"ש ותקם בעוד לילה ותתן טרף רפ\"ח ע\"ה כו' ומשם מביאה טרף ומזון לביתה ונערותיה כו' הרי הלבושי' פחותים ביותר ועוד שנדבק בהן מבחי' הרע דנוג' (וכמ\"ש וכל מלבושי אגאלתי משום דויז נצחם על בגדי כו') ולכך בהיות המל' עולה לבחי' האצילות והוא בליל שבת אז אפשיטת מלבושהא דהיינו שפושטת מלבושי' דחול הגרועים שהי' בשביל הבירור"],[2400650233,"והעבודה ולובשת בגדי שבת כאדם למטה שכל היום שעובד עבודתו לבוש בלבושי' הגרועי' וכשבא לקבל שבת פושט לבושי החול להורות על השביתה מן העבודה דחול ולובש בגדי שבת שהן מורין על עצמי' שלימות נפשו כמו שהוא לעצמו שאינו בגדר וסוג עבודת מלאכה כלל אלא הן לבושי עצמו והגם שלעצמו בלתי מלאכה לא הי' לובש בגדי יקר ות\"ת. אך בהיותו צריך לעלות במקום הגבוה ונכבד הימנו אז יתלבש בלבושי יקר שיגבהו ויעלהו כו' כמו ר\"י קארי למנא מכבדותא כו' שהת\"ת שבלבושים מגביהים לנפה\"א ומכבדים אותו יותר מכפ\"ע בעצם מדריגתו כו'. וכך יובן בענין בגדי שבת בבחי' המל' דאפשיטת מלבושי דחול מיד בקידוש היום שנפסק העבודה והמלאכה בבירורי' דנוגה כו' (ובפרט כי אין לבוא אל המלך בלבוש שק דנוגה דעשי' דכתיב ושק אשים כסותם כו' וכמ\"ש במ\"א בענין הרועי' יוצאי' בשקי' כו') ומה שלובשת בגדי שבת היינו כמ\"ש ותלבש אסתר מל' כו' בהיות שבחי' המל' יש לה עלי' גדולה לעלות מכל הצמצומים שמתצמצמת בבי\"ע לבוא בבחי' האצי' לאתנהרא משמשא שהוא בחי' שם הוי' דז\"א שבו מלובש בחי' יסוד אבא כו' ע\"כ צריכה להתלבש בבגדי יקר ות\"ת ונק' בגדי שבת ע\"ש כי בו שבת וינפש שהלבושי' מכבדים ומגביהים אותו כמ\"ש עוז והדר לבושה כו'. אך זהו דוקא בהגיע לפני הוי' דאצי' ממש שהוא ביומא דשבת ע\"כ א' לדוד בשנותו את טעמו ביום כי בליל שבת אפשיטת מלבושהא דחול. וביום כשעולה בבחי' האצי' ממש לפני אבימלך שהוא בחי' יסוד אבא שביסוד ז\"א שנק' מלך כמשי\"ת אז בשנותו את טעמו דהיינו בחי' מל' שהוא נפש דוד משנה את טעמו מבגדי חול לבגדי שבת כי צריך לקבל משמשא שהוא בחי' הוי' דז\"א. וז\"ש כאן ולבתר סיהרא דקא מתפרשת מסט\"א מיניקת החיצוני' כמו ע\"ש דנוג' דעשי' דאחידן בלבושי' דחול דוקא כמ\"ש בזוהר ע\"פ הנה מטתו שלשלמה דבלבושהא אחידא (ונק' שמלת שבי' כו') בגין לאתנהרא כו' היינו ביום השבת דוקא והוא לאחר שא' רננו צדיקים שגם יסוד דנוק' קיבל מיסוד ז\"א אז יש כח ועוז גם בסיהרא שהוא בחי' הסתר דבחי' המל' במיעוטה בתכלית בהיכלות דנוגה להפשיט א\"ע מלבושי' דחול ולעלות באצי' לאתנהרא מן שמשא כו' וזהו שסדרו אנכה\"ג רננו צדיקים תחילה קודם לדוד בשנותו כו' כדי שעי\"ז יוכל להיות עלי' המל' בב' דברים. הא' שתפשוט בגדי חול. והב' שתעלה ותבוא למעלה בבגדי שבת כו' וד\"ל. (ומבואר במ\"א בדרוש דועתה ה' אלקינו מודים אנחנו לך כו' דבגדי שבת הוא אור הבריאה כמו שהוא בלא העלם ביצי' משא\"כ לבוש דחול הוא מה שנעלם ביצי' כדי לברר כו' כנ\"ל. וכמ\"ש בפע\"ח דאפשיט' מלבושהא דיצי' ומתלבשת באור הבריאה שנק' בגדי שבת לגבי אור האצי' וכמשי\"ת בסמוך בעז\"ה):"],[2400650234,"(ס) <b>אך</b> הנה י\"ל שרש וביאור הענין דלדוד בשנותו כו' וגם למה קורא ללבושי' דחול בשם טעמו כמ\"ש בשנותו את טעמו כו'. הנה תחילה י\"ל מהו בחי' אבימלך למעלה דהנה ידוע דבחי' ז\"א נק' מלך עילאה ובחי' אור אבא שבז\"א נק' אב\"י מל\"ך והוא כמ\"ש מה שמו מה שם בנו דז\"א הוא בחי' ברא בוכרא לאו\"א כו' ובחי' מ\"ה דאור אבא עצמו מלובש בז\"א ונק' מה שם בנו דהיינו בחי' מוחין חב\"ד דז\"א שהוא בדומה לאב שהוא בחי' אור אבא עצמו וכידוע דכל אב הוא בבחי' החכ' כמו כי אתה אבינו כו' ובחי' אבימלך הוא בחי' מוחין דאבא שבז\"א דוקא והוא דוקא בשבת שפנימי' המוחין דאו\"א מאירים בז\"א כנ\"ל ואז בחי' המל' שהיא בחי' דוד משנה את טעמו לפני אבימלך זה והוא שמשנה ופושט א\"ע מבחי' מוחי' דקטנות דחול שהמוחין נק' טעמו שהטעמים בחכ' וכמו טוב טעם ודעת למדני כו' שבחי' מוחין דגדלות דאבא נק' טוב טעם כו'. ובהיות שבחי' המל' עולה בשבת לפני אבימלך זה שהוא לפני בחי' מוחין דאבא עצמו שבז\"א ע\"כ פושט מוחין דקטנות דחול ומתלבש במוחי' דגדלות כו'. וזהו ויגרשהו וילך דבחי' אבימלך זה מגרש כל בחי' לבושי' ומוחי' דחול שהן בבחי' הקטנות מאוד עד שבחי' דינים קשים מסתעפי' ונאחזים בו כו' שהוא בחי' אלקי' דקטנות ובשבת כל דינין מתעברי' מיני' משום דאנפהא דמלכא זה שהוא בחי' ז\"א נהירין בבחי' פנימי' המוחין דאבא שהוא מקור החסדים העליונים כו'. ולכך ויגרשהו וילך וד\"ל (ובאמת כ\"ז היפוך מן הפשט הפשוט דשינוי זה דדוד בשנותו את טעמו לפני אבימלך עפ\"י הפשוט הרי הי' שינוי זה מה שנתהלל בידם כו' שהוא שינוי לגריעותא ולא שינוי למעליותא וכפי הדרש עפ\"י הקבלה שהוא פושט בגדי חול ולובש בגדי שבת שזהו שינוי לעילוי גדול כו'. ועוד דגם לפי מה שהוא ידוע עפ\"י הסוד להיפוך מן הפשט דהיינו דאבימלך זה הוא בסט' דקדושה ברום המעלות כו'. עכ\"ז אין מקרא יוצא מידי פשוטו ושינוי זה דבשנותו את טעמו לגריעותא וגם עפ\"י סוד יש לו שרש באופן זה דוקא ולא להיפוך שפושט בגדי חול כו'. ועוד סיפי' דקרא סותר לרישא לפי הפי' עפ\"י הסוד הנ\"ל שהרי אם שינה ופשט בגדי חול ולבש בגדי שבת לפני אב\"י מל\"ך זה למה ויגרשהו וילך ומה שמן ההכרח לפרש דמגרש כל לבושין דחול זה דוחק ואינו עולה לפי הפשט כלל שהרי ויגרשהו וילך לדוד קא' שגרשו לדוד וילך לו מפניו שזהו היפוך גמור מכל עיקר ענין רישא דקרא שמטעם שצריך לעמוד לפני אבימלך נתלבש בבגדי שבת וטעם ויגרשהו הוא מפני שהוא בבגדי חול ע\"כ גרשו וילך לו שזהו אדרבא עוצם ירידת המל' בלבושי' דחול בבי\"ע כו' וד\"ל). והנה להבין ביאור הענין הנ\"ל. דהנה ילה\"ק משל א' מבחי' הדיבור שיש בו ב' מדריגות. א' בחי' הקטנות שבדיבור"],[2400650235,"והב' בחי' הגדלות שבדיבור. והנה בחי' הקטנות שבדיבור הוא מה שאנו רואים באדם שלפעמים יהי' הדיבור שלו בתכלית הקטנות והוא מפני שהדיבור שלו מובדל ומופרש לגמרי מן אור השכל וההשגה שבמוחו עד שנק' מדבר בלא דעת דהיינו שאין הדעת מאיר בקירוב בכל דבריו לכלכל דברו בעין שכלו בכל פרט ופרט שהוא מדבר אלא אדרבה אינו משים דעתו ולבו כלל בכל מה שמדבר רק איך שבא ונופל בפיו לדבר דבריו יהי' מה שיהי' ידבר בלי השגחה שכלי' ושימת לב עליהם כלל וכמו שאדם מדבר דברים בטלים שאין בהם דבר ממש שיהי' נוגע לפרנסתו או לכבודו או שיהי' ענין חשוב מצד עצמו רק ענינים בטלים שאין בהם ממש כלל ונק' דברים של מה בכך שבוודאי אינו משים לבו ודעתו כלל בשעה שמדבר רק מדבר איך שיפול ובא בפיו ושולח לשונו ומדבר בלי שום השגחה בדעת ולב כלל עד שכמעט בלתי מרגיש כלל בכל פרטי הדברים שיוצאי' מפיו כידוע וכ\"ז רק מצד שהענייני' קטנים הם בעיניו מאד בתכלית הקטנות עד שאינו כדאי אצלו לשום דעתו ולבו עליהם ולכלכל דבריו במשפט השכל כלל וכלל וזה הנק' בחי' הקטנות שבדיבור כשמדבר בבחי' קטנות המוחי' מאד דהיינו שעצם כח ואור פנימי' שכלו ולבו מובדלים ומופרשי' לגמרי להאיר בדיבור זה אלא דיבור זה נבדל לעצמו לדבר איך שיפול בפיו בלבד. ואמנם עכ\"ז אם לא הי' בו דעת כלל הי' מדבר בדברי שטות ודברי הבאי ושיגעון שיוצא חוץ לגדר טבע העולם והרי הוא מדבר בענינים קטנים הללו בסדר נכון. א\"כ בהכרח שיש בזה קצת דעת ולב רק שהוא בבחי' האחוריי' והחיצוני' מאד כי בהעברה בעלמא מאוד מעביר שכלו עליהם כמו הטרוד בעומק חכ' ומזכירין לו ענין קטן מאד שאינו כדאי לשום דעתו עכ\"ז בהעברה חיצוני' מאד מעביר אור שכלו עלי' הגם שכל פנימי' שכלו טרוד כו'. והנה זהו הנמצא גם בחכם גדול כשעניניו הם בתכלי' הקטנות אצלו ידבר בהם בלא דעת ולב כלל וכלל וכנ\"ל רק בחי' רשימו חיצוני' בעלמא מאיר ומלובש בסדר הדברים כשמדבר דב\"ט לגמרי כנ\"ל. והנה הגם שמצד בחי' רשימו בקטנות שכל ולב שמאיר בדיבור לא יצא לחוץ לגדר בדיבורו בדברי הבאי ושיגעון אבל בחי' מותרות הרבה נופל בדבריו הנק' פסולת ונובלות דברים שאין בהם דעת ושכל כלל ואינם לצורך הדבר של ענין זה גם בהיותו בבחי' הקטנות ונק' דיבור של בטילה לגמרי (כמו נשים דברניות הן שדרכם בדיבור יותר שאין מהצורך כלל וכלל לגוף הענין רק דיבור זה בשפת יתר ופטפוטי מילי שנק' פטיטא כו' וכמו בנשים שהשיבו לשאול בריבוי שפת יתר כו' שזהו בנשים דוקא משום שדעתן קלות ירבה הדיבור יותר וכן בקטנים דלאו בני דיעה נינהו וכל שיש בו דעת יותר ידקדק בדבריו יותר ולא ירבה הדיבור מכפי"],[2400650236,"הצורך כלל זהו מה שאין בו מותרות ונובלות כלל שהוא בבחי' ומדריגה בגדלות הדיבור כמשי\"ת בסמוך) וסיבת ריבוי המותרות והפסולת הזה שבדיבור אינו בא רק לפי ערך מיעוט וקטנות השכל שבדיבור שהרי כל מי שהוא חכם ביותר גם הנובלות והמותרות שנופל בדברו דברים בטלים אינן לבטלה כ\"כ כמו במי שאינו חכם וכמ\"ש דשיחת חולין של ת\"ח צריכי' לימוד שנא' ועליהו לא יבול כו' דמשמע שיש מותרות ונובלות גם בחכם כשמדבר בדברי שיחה בדברים בטלים לגמרי שאין בהם חכ' כלל אך עכ\"ז שיחתן צריכין לימוד שבשיחתן בדב\"ט ניכר חכמתן במה שהמותרות שבשיחתן אינו לבטלה כ\"כ מטעם שגם בחי' רשימו דקטנות שבדיבורו גדול הרבה מגופו של אור השכל של הקטן בחכ' כשמדבר בדעת כו'. (ולזה אמר צריכה לימוד שיש בזה שכל וחכ' עמוקה כמ\"ש במ\"א דאין נובלות כלל בחכם כי נובלות שלו חכ' היא עד\"מ מדבר הלצה (בל\"א גלייך ווערטיל) שהלצות החכם חכמה היא וצריכה לימוד והלצה של חסר דעת וחכ' פתיות הוא כי נובלות שלו שטות גמור משא\"כ בחכם נובלות של חכמתו נעשה חכ' גדולה לזולתו הקטן ממנו וז\"ש ועליהו לא יבול כו') ולמעלה יובן בזה בעמל שיחה דיו\"ד מאמרות שנק' מילין דהדיוטא כמשי\"ת בסמוך בעזר\"ה:\n(סא) <b>והמדריגה</b> הב' בדיבור הוא בחי' הגדלות שבדיבור והוא כאשר האדם מדבר דברי חכ' או ענינים גדולים וחשובים או שצריך להציע דברים לפני שר ומלך או חכם גדול שאז יכלכל דבריו במשפט עין השכל ושימת לבו ודעתו איך לדבר והוא ברוב השגחה יתירה דהיינו שמדקדק מאוד בדברים בכל דיבור ודיבור שלא יהי' דבור וחצי דבור שלא יהי' נגד המכוון העיקרי ולא יסתיר כל עיקר העומק שבאותו ענין הגדול והיקר וגם יהי' משגיח ומדקדק מאוד בדברי' בכל פרט שלא יהי' אפי' דיבור א' שלא לצורך ולבטלה רק עפ\"י השכלת הדבר שנצרך לו לדבר ישים עין שכלו היטיב בדברים שמדבר לכלכלם במשפט וסדר נכון בדקדוק גדול מאד מאד עד שלא יהי' אפי' דיבור א' ואות א' לבטלה רק הכל נצרך אל עומק ההשכלה והצטרכות הביאור להמכוון או בענין יקר ונעלה שנצרך ונוגע לחיי נפשו ביותר או כשמדבר לפני גדול כו'. והנה ודאי שהשגחה זו מאור השכל בעצמו שלמעלה הרבה מגופו של אור שכל זה הפרטי הבא בדיבור והוא מכח המשכיל כל שכל מן ההעלם לגילוי שהרי יומשך משם השגחה באופן הדיבור שיהי' מכוון לפי עומק זה השכל שא\"ז רק מכח המשכיל לשכל זה מן העלם לגילוי וכמ\"ש במ\"א ומלבד זה הנה אור השגחה זו מתלבשת בדיבור בהתקשרות וחיבור וקירוב גדול מאוד דהיינו שכח השכלי הזה המדוקדק בכל דיבור בפרט הוא מקושר היטב בכל פרטי הדיבור"],[2400650237,"שמדבר ואז יהי' הדיבור בדקדוק גדול דברי' ברורי' מאד עד שלא יהי' דיבור א' לבטלה והכל עפ\"י עיקר עומק השכל. ונמצא שיש עלי' לדיבור אז במקור השכל הזה שבא בדיבור ומחובר ומקושר בו בתכלית. וזהו ממש היפוך בחי' הדיבור שבקטנות בלא השגחת הדעת כלל שמופרד הדיבור מן השכל לגמרי רק בבחי' חיצוני' ואחוריי' שבו מאיר בהעלם בדיבור. וגם זה אינו רק מחיצוני' מחשבת השכל שבמוח ששייך לשכל זה שבדיבור כו'. אבל בדברי חכ' ודברים גדולים הוא להיפוך שאור השכל העצמי דוקא מקושר מאוד בדיבור לכלכל כל דבריו בדקדוק גדול להיות הכל דברים ברורי' ולא יהי' בחי' מותרות ונובלות כלל ולזה ודאי הדיבור בא בקצרה שיהי' דברי' מועטים ולא באריכות הדברים כדי שלא יצא מהמכוון (ולפעמים לא יוכל לבא אל עיקר המכוון אלא דוקא ברוב הסבר ואריכות דוקא והוא בחי' יסוד דדכורא שנק' לשון למודים כו'. אבל לא נמצא גם בזה מותרות כלל אדרב' כל שמאריך יותר לפרט יותר בא מזה הביאור יותר ולא לחנם הוא כי עדיין לא יובן מהדברים הראשונים עיקר המכוון). והנמשל המובן מכ\"ז למעלה הנה ידוע למעלה בבחי' דיבור העליון שיש ב' מדרגות ע\"ד דוגמא הנ\"ל בדיבור התחתון. והנה בחי' דיבור דקטנות שבימי החול הרי ידוע שזהו בחי' אותיות וצירופים הרבה שמסתעפים מע\"מ דדיבור העליון כמ\"ש בדבר ה' שמים נעשו כו' דבר מלך כו'. ובחי' המוחין הבאים בצירופים הוא בא בתכלית הקטנות מאד להיות כי כל עיקר בחי' אותיות וצירופים הללו אינו רק המשכת התהוו' הבריאה יש מאין שהוא ערך פחות ונבדל לגבי עצמות אור אלקי ונק' מילין דהדיוטא עד\"מ גם החכם שמדבר דברים בטלים שאין בהם ענינים רק בתכלית הקטנות מאוד (וכמארז\"ל ע\"פ לעמל יולד וא\"י אם לעמל תורה או לעמל שיחה ועמל שיחה היינו ע\"מ שהן כמו שיחת חולין של ת\"ח שיש בזה נובלות ומותרות) ובחי' הנובלות הנופלים בדיבור דקטנות זה הם הצירופים היותר אחרונים דעשי' שמקבל משם ע\"ש דנוג' דעשי' מבחי' אחוריים דאחוריי' דאלקי' מבחי' מ\"ח צירופי' האחרוני' כידוע והיינו מעוצם מיעוט הארת המוחין בדיבור רק בבחי' רשימו והעברה בעלמא ע\"כ אין בנובלות שום הארה כלל וכלל ולזה מקבלים ממנו החיצוני' (משא\"כ בצירופים העליונים יותר שעדיין אינו בחי' נובלות ולא לבטלה לגמרי ומאיר שם מבחי' הרשימו דקטנות עכ\"פ לא יוכלו החיצוני' דנוגה לקבל משם שנא' וכבודי לאחר כו' שכל שיש שם הארת המוחין דחכ' גם שהוא בתכלית הקטנות לאחר לא אתן וכמ\"ש במ\"א בפי' המאמר בשערהא אחידא כו' פסולת גמור שיוצא בנקבי ה[ע]ור כו') והוא בחי' גבו' קשות דנוג' שמקבלים יניקתם מבחי' הנובלות ופסולת הדיבור העליון בחי' המל' ונק' לבושי' זרים מאד כמו לבוש שק וכמ\"ש ושק"],[2400650238,"אשים כסותם כו'. אבל בשבת הוא בחי' עלי' המל' דהיינו עליות הדיבור מבחי' הקטנות אל בחי' הגדלות שבדיבור והוא המדריגה הב' דלעיל שהדיבור בא בתכלית הדקדוק כו' כי בשבת א' לאו אורחא דמלכא לאשתעי במילין דהדיוטא קטנות הדיבור דע\"מ בכלל ובפרט עד בחי' נובלות שבו כו'. וכמ\"ש ממצוא חפצך ודבר דבר כו'. (וכמ\"ש דט\"ס דמל' עולין למעלה בכתר כו') עד\"מ שאין הדיבור בענינים קטנים אלא בענינים גדולים וחשובים מאוד שמכלכל דבריו כו' ואז דוקא מבחי' עצמי' כח החכ' שלמעלה מגילוי השכל מקושר ומחובר היטיב בדיבור כנ\"ל. וכך בשבת יש עלי' בדיבור בפנימי' אור אבא דאצי' שבז\"א שנק' מוחין דגדלות דאבא שבז\"א כו' והם מקושרים היטב בדיבור בכל פרט עד אשר אין שם בחי' נובלות כלל ואין החיצוני' מקבלים שם כלל כמו המדבר דברי חכ' עמוקה שכל דבריו בהשכל מאד דברים ברורים ונעלמים מהעלם קדמות אור השכל הזה שבדיבור כנ\"ל וז\"ש דהמל' אפשיטת מלבושהא כו' דהיינו מלבושי זרים דנוגה מפני שבשבת עולה המל' מבחי' הקטנות הדיבור לגמרי עד\"מ כאדם שפוסק מלדבר דב\"ט כשצריך לדבר דברי חכ' או דברים חשובים או בבואו לפני מלך גדול שיזהר לדבר דברי מותרות כלל כו'. וזהו אפשיטת מלבושהא לבושים זרים דנוגה והיינו ג\"כ ענין מ\"ש דכל דינין מתעברין מינה כו' שאין מקום לדיני' קשי' רק מבחי' הקטנות ובשבת מפשטת כל בחי' לבוש הדיבור דקטנות וכמ\"ש ודבר דבר כו' וזהו פי' לדוד בשנותו את טעמו שהוא בחי' המוחין שנק' טעם כמו טוב טעם ודעת כו' רק בבחי' מוחי' דקטנות דחול פושט בבואה המל' לפני אב\"י מל\"ך שהוא פנימי' אבא שבז\"א כנ\"ל. והיינו בחי' עליות הדיבור בבחי' גדלות המוחין דאבא שנק' גדלות שבדיבור כנ\"ל ונק' טוב טעם ודעת (בחי' כתר דחכ') ויגרשהו וילך דפנימי' אבא גדלות המוחין שבדיבור הנ\"ל מגרש כל בחי' לבושי' דקטנו' שבדיבור עד שאין שם בחי' מותרות ונובלות כלל שהוא מפני שבשבת לאו אורחא דמלכא לדבר מילין דהדיוטא וממילא נגרש מפניו כל בחי' קטנות דדיבור (ובזה יתורץ גם פשט הפשוט דשינוי לדוד הי' לגריעותא ע\"כ ויגרשהו לבחי' הקטנות וילך [ליומין] דחול להסתתר אז עד בחי' צמצומים האחרונים דעשי' שנק' נובלות ומותרות כי אין לבוא אל שער המלך בלבוש שק זה בשבת כו'):\n(סב) <b>והנה</b> כדוגמא זאת דלדוד בשנותו שהוא בחי' עלי' הדיבור בפנימי' אבא כנ\"ל כך הי' ענין כריתו' ברית דאברהם עם אב\"י מל\"ך כו'. דהנה ידוע בשרש האבות שהן המרכ' לבחי' חג\"ת דז\"א ואברהם הי' מרכבה לבחי' חסד דז\"א. כמ\"ש אברהם אוהבי כו' כידוע ובחי' אב\"י מל\"ך הוא בחי' אור אבא עצמו שממנו מקור המשכו' המוחין לז\"א כנ\"ל בפי' אבימלך כו' ופיכו\"ל"],[2400650239,"שר צבאו הוא בחי' יסוד אבא שנק' פ\"י כ\"ל דכל הוא בחי' יסוד בכ\"מ ויסוד אבא נק' פ\"י כ\"ל להיות כולל כל התולדות נשמות שעתיד להיות מבחי' אור אבא כי מוח אבא שבז\"א הוא עיקר המוליד כמשל טיפה שבמוח האב כו'. ואמנם הגם שזהו מוחין דחב\"ד דז\"א שמשם נמשך בחי' מ\"ד שלו אבל מה שיש בכח מוחין שלו להמשיך מ\"ד כו' הנה זה בא מאור אבא שהוא מקור המוחין שלו שממשיך לו מוחין חדשי' בשביל כח התולדה כידוע בע\"ח שכל בחי' תולדה א\"א להיות כ\"א ע\"י המשכות מוחין חדשים במשפיע ומקבל (וזהו ענין ג' ברכות ראשונות דש\"ע להמשיך בחי' תוס' בו\"ק דז\"א שהוא בחי' חב\"ד כדי שיוכל להיות בחינת משפיע בברכות אמצעו' כמ\"ש במ\"א בפי' אל עליון כו'. וקונה הכל וזוכר חסדי אבות להמשיך מוחין בתוס' ובזה מביא גואל בחי' יסוד ז\"א לב\"ב כו') והיינו בחי' אבימל\"ך שהוא הארת מוחין דאבא בז\"א ליתן לו כח התולד' של הנשמות והוא ע\"י פיכו\"ל שר צבאו שהוא בחי' יסוד אבא שע\"י יהי' כל כח התולדה ביסוד ז\"א שהוא אור הזרוע לצ\"ע כו' מאין ליש ע\"כ נק' פיכו\"ל (כי ביוסף נא' פי המדבר פי סתם אבל זה נק' פ\"י כ\"ל) ולהיות שבחי' אבימלך זה אעפ\"י שהוא מקור הראשון אל כח המוליד שבז\"א להוליד נשמות ביחודים תמיד אבל כאשר נשלם כבר המוחין דז\"א ויוכל להוליד בכל יחוד אז יוכל לשכוח על מקורו שהמשיך לו כח זה שממנו נגדלו ונשלמו המוחי' שלו היינו כאשר ירבה להוליד ביחודו מצד אא\"ס שמברך אותו בכל יחוד. וכמ\"ש ויקרא שמם אדם ויברך אותם פרו ורבו כו' משום דאדם אדמה לעליון כו' והיינו ביחוד זו\"נ דוקא שהוא יחוד מ\"ה וב\"ן כללא דדו\"נ בהתכללותם כו'. ולזה א' אבימלך לאברהם איש החסד שיכרות ברית עמו ולא ישכח על שרש המוחין שלו שנגדלו מכחו דוקא וגם ביחודו כשמוליד יש שם ממוחין דאבא דוקא ואם לא לא הי' מוליד ולזה א' כחסד אשר עשיתי עמך להגדיל ולהשלים המוחין כו' (וכענין זוכר חסדי אבות שיהי' בהם כח התולדה ביחודם כו') תעשה עמדי ועם הארץ אשר גרתה בה שהוא בחי' יסוד אימא שהי' בז\"א בהעלם בדעת שלו כו'. ולא תשקור לי ולניני ולנכדי שהוא בחי' נה\"י שבנה\"י שנק' בני בנים (וכענין מביא גואל לב\"ב כו') גם שם מאיר מאור אבא דוקא וע\"ז הי' הכריתות ברית אבל כ\"ז רק בהעלם עכשיו שאור אבא מאיר עד סוף השפעת נה\"י שבנה\"י דז\"א ונוק' בסוף העשי' וכמ\"ש כולם בחכ' עשית. וכמ\"ש במ\"א בפי' אל אדון על כל המעשים דאל נהירו דחכמתא שבחסד דז\"א אדון עד סוף כל ההשתלשלות דעשי' כו' אמנם לע\"ל הרי א' בהיפוך ממש כי אברהם לא ידענו וישראל לא יכירנו שזהו לא מבחי' חסדים דאברהם ולא מבחי' ת\"ת דישראל רק כי אתה אבינו בחי' אור אבא עצמו שמשם מקור מחצב הראשון של כללות נש\"י"],[2400650240,"כמו שהם במקורם הראשון ששם גילוי עצמות אא\"ס (כידוע דפנימי' אבא הוא פנימי' ע\"י) וכך הוא ענין לדוד בשנותו את טעמו לפני אבימלך שמגרש כל לבושי' דחול ועולה המל' בפנימי' אבא דוקא שזהו כדוגמא דלעתיד כמ\"ש כי אתה אבינו שבכל שבת ושבת יש הארה ומדרגה מיום שכולו שבת שהוא אלף הז' שיתעלו כנס\"י במקורם הראשון שהוא מ\"ש כי אתה אבינו דוקא וד\"ל. ולבתר דאתפרישת מינה הא אתחברת בשמשא. ותושבחתא דא בכ\"ב אתווין דאעיל בה שמשא בסיהרא ותושבחתא דא פרישא דסיהרא מסט\"א ותושבחתא דכ\"ב אתווין בנהירו פי' כ\"ז שהמל' מלובשת בלבושי' זרי' דנוגה לא תוכל לבא בבחי' האצי' ולהתייחד בבחי' ז\"א שנק' שמשא אלא לאחר שמתפשטת מלבושים דחול ואתפרש מינה לגמרי הא אתחברא סיהרא בשמשא ותושבחתא דא דלדוד כו' בכ\"ב אתווין שזהו הא\"ב שבמזמור זה המתחיל אברכה את ה' כו' בה' תתהלל נפשי כו' גדלו לה' כו'. ונז' שם הוי' דוקא בכל פסוק שהוא בחי' גדלות המוחין דאבא שבז\"א שנק' הוי' הוא שמקבלת המל' שנק' דוד ולכך א' אברכה את הוי' בהוי' תתהלל נפשי. וכן גדלו לה' דרשתי ה' הביטו אליו דוקא וכה\"ג בכל הפסוקים מדבר רק בשבח דשם הוי' דפנימי' ז\"א שמקבל משם בשבת דוקא וכמו זה עני קרא בחי' מל' שנק' דל ועני כמ\"ש דוד כי עני ואביון כו' וכן והוי' שמע כו' וכן חונה מלאך ה' סביב ליראיו טעמו וראו בבחי' המוחי' דז\"א כי טוב כו' יראו את הוי\"ה ודורשי הוי\"ה יראת הוי' אלמדכם ומכאן ואילך מדבר בהפרש' הלבושי' זרים דנוגה דבי\"ע שמזמור זה כולל ב' דברים הפרשה מלבושים זרים דנוגה. וענין קבלתה מפנימי' מוחין דז\"א. ומי האיש כו' ונצור לשונך מרע כו' סו\"מ כו' פני ה' בעושי רע כו' דקאי הכל בהבדל' הטוב מן הרע לגמרי ומותרות ופסולת עד רבות רעות צ\"ע (מחיצוני' דיסוד ז\"א בבי\"ע כמ\"ש במ\"א בענין הנפילים כו' אשר מעולם כו') עד תמותת רשע רעה ושונאי צדיק [עליון] יאשמו כמו קודש ישראל כו' כל אוכליו יאשמו כו' שיבורר מהם הכל עד פודה ה' נפש עבדיו שהוא בחי' המל' בתכלית ההסתר שלה בגלות בע' שרים כו' וד\"ל. וז\"ש ותושבחתא דא בכ\"ב אתוון דהיינו כ\"ב אתוון רברבין דז\"א שנמשכי' מבחי' גדלות המוחי' דאבא שבז\"א כידוע בג' מדרגות דאותיות גדולות מפנימי' אבא ואותיות בינונים בבינה וז\"א ואותיות קטנים במל' והגם שהמל' מקבלת ג\"כ בימות החול מאותיות דז\"א שהן בחי' אלקי' דז\"א דכל ספי' כמו מל' שבחסד דז\"א מזה נמשך בחי' חסד שבמל' כידוע אבל בשבת מקבלת מפנימי' אבא שבהוי' דז\"א וע\"כ א\"ב זה בחי' מל' מרומם ומשבח ומפאר כמו אברכה כו' גדלו כו' וממילא נבדל כל לבושים זרים דגבו' קשות דנוג' דבי\"ע כנ\"ל בפי' ויגרשהו וילך ולזה"],[2400650241,"מאות מ\"ם נו\"ן שהוא אמצעי' מתחיל לגרש כל רע שנדבק ביסוד דזו\"נ שנק' צ\"ע וצ\"ת כו' וד\"ל. (ומה שמתחיל באות א' בברכה אברכה את ה' בכל עת מבואר במ\"א בענין ברכת ה' היא תעשיר זה שבת דכתי' ויברך את יום הז' ולכאורה אין ברכה יתירה בשבת יותר מבחול. אך הענין דעליות העולמות דשבת הוא בחי' הפנימי' שעולה מצמצומם בחיצוני' ונשפע בשבת מחיצוני' בלי שום הלבשת הפנימי' בה כלל עד\"מ כמו הטרוד להסביר שכל לתינוק שפנימי' השגתו לעצמו מצומצם בהסבר זה וכאשר שובת מזה עולה פנימי' כח השגתו לעצמו ונפשט מהלבשתו בחיצוני' הצמצום שפע זו לתינוק וכן העובד ומתקן בל\"ט מלאכו' שמצמצם פנימי' שכלו ומדותיו בעסק זה ואם לא לא הי' מתקן כלום אך תיקון זה שבחכמתו הוא מצמצום פנימי' שכלו בזה החיצוני' ובשביתה נבדל ונפשט הפנימי' מהחיצוני' ויאירו פניו כו'. וכך בל\"ט מלאכות דחול מלובש בזה פנימי' דמל' כדי לברר ולתקן כו'. ובשבת שבת וינפש דבורר אסור הרי אתפשטת מלבושהא דפנימי' נפשט מן החיצוני' ועולה לעצמו כו' וזהו שבחי' המל' פושט בגדי חול כו' דהיינו שבחול מלובש ומצומצם אור הבריאה ביצי' כדי לתקן וכן מיצי' בעשי' כו' ובשבת נפשט אור הבריאה ועולה לעצמו כמו שהוא בבחי' פנימי' עצמו' טרם ירידתו ביצי' ונמצא שנק' אור הבריאה בשבת דוקא בחי' בגדי שבת לגבי אור דאצי' משא\"כ בחול יורד אור הבריאה ומתעלם ביצי' נק' לבושין דחול כדי לתקן כו' כמו בגדים שמבשל קדירה כו'. וז\"ש ה' מלך גאות לבש שבשבת מתלבשת מל' אצי' באו\"פ דבריאה שנק' בגדי שבת או בגדי מל' כמ\"ש ותלבש אסתר מל' אסתר הוא בחי' מל' שמוסתרת בבריאה ובשבת עולה באצי' אמנם אור הבריאה כמו שהוא עולה מצמצומו ביצירה ומתלבשת בהן ונק' בגדי מל' למל' דאצי' כו'. וז\"ש ברכת ה' היא תעשיר בשבת לפי שהברכה הוא בחי' השפעה עצמי' ומקורי' כמו שהוא בפנימי' עצמו' שלמע' מבחי' אור שאינו רק בחי' התפשטות כו'. והיינו אור הבריאה כמו שהוא משא\"כ בהתלבשות שלו ביצי' בחול שאינו נק' ברכה רק בחי' התפשטות אור כדי להאיר החשך לתקן ולברר בל\"ט מלאכות וה\"ז כמו הברכה במעשה ידיו שהוא פנימי' ועצמי' השפע כו' שלאחר התיקון והעבודה כו' ומי שטרח בע\"ש כו'. וז\"ש אברכה את הוי' בחי' ברכה זו בשם הוי' דפנימי' ז\"א ממקור הראשון שהוא יותר עצמי ומקורי והוא אור אבא שבז\"א כו' ונק' ברכת הוי' היא תעשיר לזו\"נ שבבי\"ע וד\"ל. (וא\"ב זה יש בו רת\"ס סת\"ר שהן אותיות אמת ואלף מתחיל בברכה דהוי' עד אות מ\"ם ומנו\"ן ועד תי\"ו לביעור כל רע שזהו עיקר האמת שלא יהי' נפסק לבסוף דוקא כמ\"ש במ\"א בפי' וגם נצח ישראל לא ישקר וכמ\"ש אם תשקור לי ולניני ולנכדי שאור החס' אינו מתעבה אבל נפסק משא\"כ כי"],[2400650242,"אתה אבינו גואלנו מעולם כו'. וז\"ש פודה ה' נפש עבדיו כו' אחר תי\"ו דתמותת בתשלום הבירורים כו'):\n(סג) <b>ולבתר</b> אתחברותא וסליקא דמטרוניתא עם בעלה ודא איהו תפלה למשה כו' לאפרשא ימינא ושמאלא לקבלא לה ולמהוי כחדא בחבורא חדא כו'. פי' מ\"ש תחילה בענין הא\"ב דמזמור הקודם לדוד בשנותו כו' אברכה את ה' כו' שהן בחי' כ\"ב אתוון דז\"א מבחי' גדלות דאבא שבו שמאירים וממשיכים למל' מבחי' יסו\"א שביסוד ז\"א שנק' שמשא כמ\"ש ך\"ב אתוון דעאיל שמשא בסיהרא כו' היינו רק להגדיל בנין המל' להיות בבחי' פרצוף שלם בבחי' האצי' שתוכל להתייחד בז\"א בבחי' פב\"פ כו' אך מ\"מ עדיין לא יש בחי' היחוד ובמזמור זה דתפלה למשה מדבר בבחי' יחוד זו\"נ בבחי' האצי'. וז\"ש ולבתר אתחברותא וסליקא דמטרוניתא עם בעלה כו' כי לאחר שעלתה בבחי' האצי' ממש וכבר הופרשה והובדלה לגמרי מלבושים זרים דנוגה (ע\"י כ\"ב אתוון דבחי' גדלות דהוי' דז\"א כמ\"ש אברכה את הוי' בהוי' תתהלל נפשי כו' וכנ\"ל שמזה בא סיבת ההפרשה דדינין קשין עד תי\"ו דתמותת כו' פודה כו') ונתלבשה בלבוש מל' כמו ותלבש אסתר מל' (שהוא אור הבריאה בבחי' פנימי' שלו שעולה באצי' כנ\"ל) אז נק' בשם מטרוניתא דוקא לשון מלוכ' בבגדי מל' דאצי' כו' ואזי מתייחדת בבעלה שהוא בחי' משה שנק' איש האלקים בעלה דמט' והוא בחי' יסו\"א שבתוך יסוד ז\"א בבחי' גדלות המוחין כו' וזהו ענין תפלה למשה איש האלקים כו' תפלה הוא בחי' המל' וכמ\"ש ואני תפלה כו' אך בחול בחי' המל' נק' תפלה סתם ולא תפלה למשה כי בחול בחי' המל' מלביש רק לבחי' נה\"י דז\"א בבחי' הקטנות שבו כידוע דבחול הוא רק בחי' יעקב ורחל שהוא בבחי' קול ודבור שנק' קלא דמשתמע דיבור מורגש בהבל הפה בע\"מ בגילוי השפע להחיות בע\"ג מאין ליש ממש (והגם שבש\"ע יש יחוד דמל' שנק' תפלה בלחש שאין הדיבור מורגש כלל וכידוע בפי' אדני שפתי כו' אין מלה בלשוני כו' אך מ\"מ אינה מקבלת רק מבחי' החיצוני' דהבל החזה דז\"א שזהו בחי' קול דיעקב כו' אבל בשבת עולה לקבל מבחי' הפנימי' המדות דז\"א כמשי\"ת) אבל בשבת נק' תפלה למשה שמתייחדת המל' בבחי' הפנימי' דז\"א שהוא בחי' משה יסוד אבא שבז\"א כנ\"ל ולכך אומרי' תפלה למשה בשבת דוקא ואחר לדוד בשנותו דוקא מטעם הנ\"ל וד\"ל:\n<b>וז\"ש</b> ודא איהו תפלה למשה כו' לאפרשא ימינא ושמאלא לקבלא לה פי' ימינא ושמאלא כו' הוא בחי' חו\"ג דז\"א שהמל' עולה למעלה באצי' להתייחד בבחי' פב\"פ שאז ימינא ושמאלא דז\"א מקבלי' לה כמ\"ש ימינא ושמאלא ובינייהו כלה ונק' כלת משה דוקא כו' שזהו בבחי' גדלות המוחין דחו\"ב שבמדות דז\"א (וכמש\"ל שהיחוד בשבת הוא יחוד ישראל"],[2400650243,"ורחל ונק' ברא בוכרא כו' ונק' קלא פנימאה כו' ומבואר שם ההפרש בין ישראל למשה שאינו רק מצד בחי' אור אבא שבדעת דז\"א כו'). ולהבין ביאור הדברים הנה כמו שמבואר למעלה בב' מדריגות שבדיבור קטנות וגדלות שמצד השכל שבדיבור כך יובן ב' מדריגות הללו בבחי' המדות שבדיבור כי אנו רואים שיש דבור שלבו בל עמו כלל וכלל בדיבור זה ואין בו חיות כלל כמו דברים שמדבר בעניני פחותי הערך מאוד שאין כדאי לשום לב עליהם כלל והן כמו דברי שיחה בטילה וכה\"ג שבודאי רק רשימו הארה מעט מזעיר מן הלב בדיבור זה ונק' קטנות המדות שבדיבור והוא בחי' דיבור דחול בעשרה מאמרות שנק' מילין דהדיוטא שמאיר שם בחי' הקטנות דמדות העליונות דאצי' רק מה שצריך לדיבור דחול זה בשביל בנין העולמות שהן ענין פחותי הערך כמאמר אין ערוך כו' אך בשבת דאתפשטי' מלבושין דחול אז הדיבור עולה לקבל מבחי' פנימי' המדות מאוד כמו עד\"מ דברים שיוצאים מהלב מנקודת פנימי' הלב הנה נמשך חיות גדול מן הלב בדיבור זה ואז מתאחד הדיבור בפנימי' נקודת האור והחיות שבמדות שבלב (כנ\"ל בגדלות שבדיבור שמתאחד עם מקור השכל שלמעלה מגופו של שכל זה שבא בדיבור כו' כך דברים היוצאי' מהלב שרשם בנקודת הלב שנק' כתר דז\"א רעו\"ד והוא מבחי' ג\"ר שבמדות דז\"א שיוצא ומתגלה לחוץ ע\"י בחי' יסוד אבא שביסוד ז\"א שזהו בחי' משה כו' והיינו תפלה למשה ונק' ג\"כ קולו של משה דהיינו למעלה גם מבחי' קלא פנימאה שבדעת דז\"א שהוא התפעלות שכל שבלב שמושך התפעלות המדות אחר התפעלות המוח שזהו נק' ישראל בלבד כו' אבל קול צלותא דלחש דמשה שנק' תפלה למשה דוקא הוא בחי' גדלות דג\"ר דאבא שבפנימי' דז\"א שמלובש ביסוד ז\"א כו' וז\"ש אדני מעון כו' אותיות נועם בבחי' פנימי' ועצמות דע\"י בטרם הרים יולדו ותחולל ארץ ותבל כו' דהיינו העלם העצמות דג\"ר דע\"י בשרשם בטרם יולדו המדות והדיבור שהמדות נקרא הרים והדיבור נק' ארץ וקאי גם בהרים העליוני' דא\"א וע\"י כי בבחי' ג\"ר דע\"י עדיין אין שם שרש למוחין שבמדות ודיבור כמבואר לעיל בענין עולת שבת בשבתו כו' וד\"ל). ותושבחין אילין אתקינו בתיקונא דשבתא דאיהו סליק ואתעטר בעטרוהי כדחזי פי' סליק ואתעטר בעטרוהי הן כל הכתרים שנק' עטרין בזוה\"ק פי' אתעטר בעטרוהי היינו בחי' כשב\"כ שנק' עטרה בראש כו' כמ\"ש כליל ת\"ת בראשו כו' דהיינו בחי' עלי' דפנימי' דז\"א לקבל מבחי' ג\"ר דאו\"א מבחי' כשב\"כ שעז\"א עולת שבת בשבתו כו' דהיינו בעצם התעה\"פ שמאיר בכל אורות דאו\"א וא\"א כו' וכולן נמשכי' בי\"ס דז\"א ע\"י תושבחי' הללו דאתקינו אנכה\"ג בשבת שנק' תיקונא דשבת דוקא וז\"ש ותושבחן אילין אתקינו אנכה\"ג בתיקונא דשבתא דאיהו סליק ואתעטר כו' לקבל כל המקיפים העצמיי' מבחי'"],[2400650244,"כתר שבכתר כו' ומז\"א נמשך למל' בכל תושבחי' אילין שבא בבחי' הדיבור במל' וכמו\"כ ממילא נמשך כ\"ז לכנס\"י למטה ששרשם בבחי' מל' דאצי' כידוע בענין כל ישראל בני מלכים הם והיינו בחי' נשמה יתירה שמאיר בכאו\"א מישראל בשבת ששרשה בעצמות התעה\"פ שנק' שעשועי המלך בעצמותו כו' שנמשך בשבת דוקא מטעם המבואר לעיל בענין ב' שבתות כהלכתן כו' שהוא מבחי' כשב\"כ ומתחיל בשבת ברכות הללו שהן תושבחא דאתקינו אנכה\"ג כפי הסוד למע' בשרש דכנ\"י בזו\"נ דאצי' כו' ובתפילת מוסף בקדושת כתר נגמר. ע\"כ מענוגין דישראל בסעודת השבת מתענג למעלה כו' (ולזה אין העונג בתבשיל שבת מזיק כלל דגם המותרות נבלע בקדושה כמ\"ש במ\"א) ובמנחה דשבת אז עיקר שלימות הארה הזאת כמ\"ש ועל מנוחתם יקדישו את שמך ששורה בבחי' יחידה שבכאו\"א שבכחו למסו\"נ על קה\"ש דוקא וזהו כי מאתך ממש מנוחתם דכאו\"א מישראל כי עי\"ז יקדישו את שמך במס\"נ והוא מצד שרשם בבחי' העצמות ממש כידוע וזהו ויהי נועם ה' אלקינו עלינו כו' דמעון דתפלה למשה הוא מלמטה למעלה ומזה נמשך נועם ה' העצמי' מלמעלה למטה על כללות נש\"י וכמו שמסיים אורך ימים יום שכולו ארוך כו' ואראהו בישועתי כו' בחי' ישועה עצמי' ממש וד\"ל:"],[2400650245,"<h3>מזמור שירו לה' שיר חדש </h3>\n(סד) <b>מזמור</b> שירו לה' שיר חדש אתערו בי' חברייא בתושבחתא דא שפיר דדא איהו כד הוי נטלי פרות ארונה דכתי' וישרנה הפרות בדרך כו' הלוך וגעו כו' דהוי אמרו מזמור שירו לה' שיר חדש רזא דא כגוונא דלעילא בשעתא דחיות נטלי' כורסייא לארמא לעילא אמרי תושבחתא דא ע\"כ. והנה להבין ביאור זה המאמר ילה\"ק תחילה בביאור שרש ענין ארון הברית בכלל שהוא בחי' מל' דאצי' והטעם שנק' ארון הברית לפי שהלוחות שבו הוא בחי' יסוד אבא שמלובש ביסוד ז\"א שנק' ברית וארון הברית הוא בחי' המל' שמקבל בחי' הברית העליון שבלוחו' העדות כידוע דאורייתא מחע\"נ שהוא בחי' פנימי' אור אבא וכמ\"ש והחכ' מאין כו' והיינו בחי' הכתר שהוא הכפורת כו' והלוחות מכתב אלקים כו' כלול מחו\"ג כו' שהוא בחי' המדות דז\"א שבתוכו בחי' יסו\"א והוא הנק' ברית שנק' לוחות העדות כו' שבא בבחי' כריתות ברית שבתורה לכנס\"י וכנ\"י מקבלים הכריתות ברית זהו בחי' ארון הברית שהוא בבחי' מל' כו' כידוע ומבואר במ\"א בענין ויהי בנסוע הארון כו' שהוא בחי' עליות המל' כו' ומ\"ש אורייתא מחע\"נ היינו דנפקת שרשה מח\"ע אבל אורייתא עצמה בבחי' המדות דז\"א כמ\"ש להבדיל בין כו' (וגם בלוחות הרי כלול מחו\"ג ונכתב באש שחורה כו') והנה הארון שהי' בהיכל ק\"ק היינו בבחי' היכל ק\"ק דבריאה שהוא היכל הז' ששם יחוד דזו\"נ כו' כידוע בענין סמיכות גאל\"ת והגם שהיכל ק\"ק דבהמ\"ק הי' בבחי'"],[2400650246,"היכל ק\"ק דעשי' אבל בחי' יחוד דזו\"נ דאצי' שבארון הברית למעלה כמו שהן בהיכל ק\"ק דבריאה הי' שורה בהיכל ק\"ק דבהמ\"ק בזה העולם (וכמ\"ש בביאור המאמר שאמר לר' ישמעאל כה\"ג ישמעאל בני ברכני וא\"ל יהר\"מ כו' דשרש נשמת ר' ישמעאל כה\"ג בחסד דמל' דבריאה ואמר יהר\"מ מבחי' כתר מל' דאצי' לבחי' כתר מל' דבריאה כו'). ומעתה י\"ל בענין זה המאמר דמזמור זה אמרו הפרות כד הוי נטלי ארונא כו' דהנה ידוע שבחי' המל' בהיותה יורדת למטה מטה בבי\"ע להחיות רוח שפלים ולברר בחי' רפ\"ח כו' כמו ותקם בעוד לילה ותתן טרף רפ\"ח ע\"ה כו' שיורדת למטה עד היכלות דנוגה לברר ולתקן כו' אז אין בחי' יחוד דזו\"נ רק בבחי' עליות המל' שתעלה אחר יריד' מבי\"ע להיכל ק\"ק דבריאה והוא מחצות לילה ואילך עד עה\"ש ובק\"ש ותפלה כו' כידוע ונמצא יש בבחי' המל' ב' מדריגות הא' הוא בחי' הירידה למטה מטה והב' בחי' העלי' למעלה מעלה ובין בירידה ובין בעלי' הכל הוא ע\"י בחי' המרכבה עליונה כמו שמבואר בזוהר בענין מסעות דארון במדבר דכתי' עפ\"י ה' יחנו עפ\"י ה' יסעו שהוא יריד' ועלי' במימרהא נטלין ובמימרהא שריין כו' עד\"מ הרוכב על המרכבה שלפעמים יורד בו מלמעלה למטה מגבוה לנמוך ולפעמים עולה בו מלמטה למעלה כו' וכך ע\"י בחי' המרכבה יורדת השכינה למטה מטה שהרי מעולם לא ירדה שכינה למטה בלי התלבשו' במרכבה גם לנביאים כמו לישעי' ויחזקאל רק שזה ראה מרכבה דבריא' וזה מרכבה דיצי' וזכרי' ראה ירידת המל' במרכבה דעשי' כו' וכמו\"כ לא תעלה למעלה מעלה כ\"א ע\"י המרכבה כמ\"ש והחיות נושאות את הכסא שהמל' בבי\"ע נק' כה\"כ וכמו וישב שלמה על כסא ה' כו' ונושאו' הכסא דמל' בבחי' עלי' למעלה מעלה עד בחי' היכל ק\"ק דבריאה כו' והוא מה שראה ישעי' שרפים עומדים כו' והחיות דיצי' בנבוא' דיחזקאל כו' וכה\"ג וכמ\"ש רכב אלקים רבותיים כו' וכמ\"ש במ\"א בביאור הפסוק אד' בם סיני בקודש ששם אד' דבחי' מל' מלובש במרכבה עליונה כמו פני ארי' פני שור כו' עד שיש בכחם לנשאות ולהגביה הכסא וכמ\"ש והחיות נושאות כו' והוא מצד עוצם בחי' ביטולם מיש לאין בהעלאת מ\"ן המה מרוממים ומנשאים לבחי' המל' מירידתה למעלה מעלה וכמו ויהי בנסוע הארון ויאמר משה קומה ה' בעילוי אחר עילוי ויפוצו אויביך כו' ובנוחו למטה כמ\"ש במימרהא שראן לירד למטה אמר שובה ה' כו'. (וכמ\"ש במ\"א בפי' שם מ\"ב דאנא בכח כו' שזהו בכל עלי' כמ\"ש שש כנפים לא' בשתיים יעופף כו' ולכך אומרים א\"ב קודם קב\"ש ולפני השינה בק\"ש שעהמ\"ט כו'). (ואעפ\"י שארז\"ל ארון נושאיו נשא וכמ\"ש נושאות ומנושאו' כו' עכ\"ז ג\"ז אמת שנושאות את הכסא אעפ\"י שנושאיו הוא נושא וכמ\"ש במ\"א באריכות). ובכ\"ז יובן ג\"כ בענין"],[2400650247,"הפרות שהיו נושאין הארון שעל העגלה החדשה כו' שהוא מפני שאז הי' מלובש בפרות גשמיות הללו משרש שרשם הראשון שהוא בחי' פני שור שבמרכבה כו' וכגוונא דלעילא ממש שבחי' המל' מלובש במרכבה דפני ארי' פני שור כו' והם בתכלית הביטול בהעלא' למעלה לא יסבו בלכתן מצד גילוי אור האלקי דבחי' המל' אשר עליהם כך ממש הי' בארון הברית שלמטה בהיותו על העגלה גשמי' מיד כשראו הפרות הי' בהם בחי' הביטול העליון דמרכבה עליונה ממש כי לגבי אלקות עצמו שוה מרכב' הרוחני' העליונה עם מרכבה הגשמיי' דפרות הללו מאחר שבארון הברית זה הי' שורה מבחי' מל' ממש שנק' ארון הברית למעלה כו' וז\"ש הלוך וגעו כו' לא סרו ימין ושמאל בלכתן כמו המרכבה העליונה ממש משום דכתי' עפ\"י ה' כו' משום דהלוך וגעו זה הי' בבחי' ביטול גדול שלא עפ\"י טבע גשמי' שהרי אמרו שירה דמלאכים דמרכבה עליונה ממש וכמ\"ש דהוי אמרי מזמור זה דשירו לה' כו' והיינו לפי שהי' מעלין לארון הברית לירושלים להיכל ק\"ק שזה ממש כמו עלי' המל' למעלה ע\"י מרכבה דפני ארי' כו' לעלות להיכל ק\"ק דבריאה כנ\"ל מאחר שהי' בארון הברית זה גילוי אור במל' כמו שהוא בהיכל ק\"ק דבהמ\"ק שהוא כמו היכל ק\"ק דבריאה ממש כו' וא\"כ בעלות הארון הזה לירושלים ע\"י הפרות הללו כתי' וישרנה הפרות בדרך כמו השיר שאומרים במרכבה עילאה שהוא שיר זה דמזמור שירו לה' כו' מפני שהי' מאיר עליהן אותו בחי' ביטול עליון האלקי דמרכב' עליונה דעולם הבריאה ממש מטעם הנ\"ל וד\"ל. (וא\"ז פלא מה שהי' יכול להיות באותה שעה הארה אלקי' בגשם נפש הבהמ' שתאמר שירה אלקי' כו' שהרי קודם החטא שלא הי' בחי' תערובות טו\"ר כלל גם הבהמות הי' בהם בחי' הביטול אלקי יותר מביטול דאדם גדול עכשיו וראי' מחמורו דרפב\"י שנשארו מאותן בהמו' בהררי אלף כו' שאמר אנו כחמורים ולא כחמורו כו' שלא אכל שאינו מעושר כו') ולא עוד אלא גם בסט\"א כמו בבהמות הטמאות כאתון דבלעם נוק' דקליפה שרבצה בראותה מלאך ה' ותפתח פי האתון כו' ואיך יהי' לפלא במה שפרות טהורות אמרו שירה בהגלות נגלות אור האלקי בארון הברית שעל עגלה דפלשתי'). ומעתה ית' דברי המאמר מ\"ש דאתערו חברייא שפיר דדא איהו פרות לפי שזה הי' בעלות הארון לירושלים דשייך לומר אז מזמור זה דוקא ופרות יאמרוהו לפי שהי' מאיר עליהם ממרכבה דפני שור כשמעלים הכסא כו' וז\"ש דא כגוונא דלעילא בשעתא דחיות נטלי כורסייא שהוא כה\"כ דמל' בבי\"ע דנטלי' לנשאות אותה לארמה לה לעילא בהיכל ק\"ק דבריאה שהוא ענין א' עם עלי' הארון לירושלים מטעם הנ\"ל וד\"ל (וכמו שאנו אומרים פנות צבאיו קדושים"],[2400650248,"רוממי שדי וכו' וגם בלשון הגמרא בלילה מאי עביד קוב\"ה רוכב על כרוב קל שלו ושט בח\"י כו' וזהו בתכלית העילוי בח\"י אלפיים עולמות דבחי' א\"א כו' א\"ת שאנן אלא שאינן כו' וכמ\"ש במ\"א ולפעמים אמר הנה ה' רוכב על עב קל כו' ובא מצרים כו' שהוא תכלית הירידה למטה בע' שרים דעשי' כו' וכמו מרכבה תתאה דמל' דעשי' דסוסים שחורים ואדומים דזכרי' שהיו בזמ\"ג השכינה בע' שרים כו' משום דקמי' כחשיכא כאורה וגם חושך כו' ידע מה כו' וכמו ויאמר ה' אל הנחש או אל בלעם וכה\"ג וכמ\"ש אם אסק שמים שם אתה אציעה שאול הנך כו' ונהורא עמי' כו' וכמ\"ש יונה מבטן שאול כו' כי בארץ מתחת אין עוד כמו בשמים ממעל ממש כו' וד\"ל:\n(סה) <b>ואי</b> תימא אמאי שיר חדש והא תדיר קאמרי תושבחתא דא אלא חדש באתחדתותא דסיהרא מן שמשא דא איהו שיר חדש ע\"כ. הנה בא לדקדק ב' דברים הא' מ\"ש כאן אמאי שיר חדש והא תדיר קאמרי שהרי המלאכים אומרים שירה בכ\"י ובכל עת וזמן בלי הפסק כלל כידוע (ומבואר במ\"א דג\"פ קדוש נמשך בי\"ב שעות כו'). והב' מה שקורא לו שיר חדש שיר ל' זכר וגם חדש לשון זכר ולא אמר שירה חדשה לשון נקבה שהרי כאן מדבר בבחי' עלי' המל' שהוא ארון הברית להיכל ק\"ק כו' והמל' הוא בחי' נוק' והל\"ל שירה חדשה ל' נוק' ולא שיר חדש ל' זכר והנה מתרץ לב' הדקדוקים בדבר א' והוא מ\"ש אלא חדש באתחדותת' דסיהרא כו' מפני שעלי' זאת היא בחידוש הלבנה שהוא בתחילת החודש שנק' מולד הלבנה שזה האור בא בלבנה מאור השמש דוקא כידוע בטעם פגימת הלבנה שאינו רק מצד העדר אור השמש בלבנה ומולד הלבנה הוא נקודת אור השמש בלבנה בתחילת החודש שזהו נק' אתחדתותא דסיהרא משימשא דוקא ע\"כ ע\"ש השמש נק' אור חדש זה כי שלו הוא ולא של לבנה שאינו רק בחי' מקבל מאור השמש וללמג\"כ ולזה הטעם נק' שיר חדש לשון זכר שהשמש הוא בבחי' דכר ולא בבחי' נוק' כידוע בענין שמש ומגן ה' אלקים כו' כמו וזרח השמש כו' השמש יצא כו' וכן ויזרח לו כו' וכן לשמש שם כו' והוא כחתן כו' ובזה מתורץ גם הדקדוק הא' אמאי חדש הא תדיר קאמרי כו' שהרי אור זה של השמש חדש הוא בלבנה שעד הנה לא קיבלה עדיין אור השמש כלל ומה שנק' חידוש הלבנה א\"ז רק חידוש אורה מה שמקבלת מחדש מהשמש ולא מחמת חידוש אור עצמה ע\"כ נק' חדש ונק' שיר חדש ל' זכר דוקא ולא שירה חדשה כו' וכך יובן למעלה בבחי' ז\"א דאצי' שנק' שמשא והמל' נק' סיהרא דמולד הלבנה הוא בחי' חידוש אור דז\"א במל' בקירובה לעילה שלה להתייחד בו כו' ומפני שלא האיר אורו עדיין במל' בהיותה עדיין בבחי' ההסתר בבי\"ע בבחי' מיעוט הירח כמאמר לכי ומעטי א\"ע כו' ע\"כ נק' אור זה דז\"א"],[2400650249,"במל' בשם חדש ע\"ש התחדשות אור דז\"א והוא בחי' דכר כידוע ע\"כ א' שיר חדש ל' זכר ולא שירה חדשה לשון נוק' אך עדיין אין מובן זה שהרי השיר בבחי' העלאה הוא כידוע והעלאה הזאת היא של בחי' המל' להיכל ק\"ק דבריא' הל\"ל שירה חדשה מפני שהוא עליי' המל' ולמה נק' שיר חדש כנ\"ל. אך הענין הוא דשיר זה הוא בבחי' דכר ולא בבחי' הנוק' מצד שהוא בחי' חידוש אור דז\"א במל' שבחי' עלי' המל' מחמתו בא ועד\"מ מה שנמשך הניצוץ בפני האבוקה שזהו כח האבוקה שמושכו אליו וכן מ\"ש משכני אחריך כו' וכל עליי' עלול בקירובו לגבי עילתו מכח העילה דוקא בא שמושכו אליו משא\"כ בריחוקו שאז עלייתו מצ\"ע וזהו ענין ב' מיני שיר שירה דנוק' מצד בחי' ביטול היש בהיותה בריחוק עדיין והב' בבואו בקירוב שבטולו מצד העילה שמאיר בו ע\"כ נק' שיר על שמו לשון זכר כמבואר במ\"א בענין עמוד שבג\"ע כו' בב' מיני ביטול הללו וז\"ש כאן שיר חדש אעפ\"י שהוא עליית המל' אבל מאור קירוב דז\"א הוא בא כו' וד\"ל. הושיעה לו ימינו וזרוע קדשו הא אתערותא בימינא ושמאלא לקבלא לה ותושבחתא דא כד נטלי ארונא דקא משבחן לה כדסלקין לבית שמש כגוונא דעגלות דסלקי לבית שמש וכולא ברזא חד סליק ע\"כ. פי' אתערותא דז\"א בימינא ושמאלא בבחי' חו\"ג שבו לקבלא לה לבחי' המל' בעלותה אלי' משום דמדקדק במ\"ש הושיעה לו דמשמע לו לעצמו שימינו יושיע לו דכל ישועות הוא בבחי' החסדים הגוברין על הגבו' כמו כוס ישועות אשא דעיקר הישועה הוא להתגבר על המנגד שהוא בחי' הדין וכך באתערותא דז\"א לקבלא לה בא מבחי' החסדים שנק' ישועות והן ביד ימין דוקא שהמה עוזרים לו לעצמו כמו ימינך ה' נאדרי בכח כו' וגם כאן שצריך להעלו' לבחי' המל' שהוא למטה לקבלה ולקרבה אליו שזהו כמו הפושט ידיו למט' לקבל דבר הנמוך ממנו שצריך לזה תוקף ועוז בתגבורת כח שהוא בימין וזהו כאשר השמאל נכלל בימין שהוא המוסיף עוז וכח בימין ומתחברים כא' ונק' גבו' שבחסד וכמ\"ש כי גבר עלינו חסדו (כמ\"ש במ\"א בענין ובידך כח וגבורה כו' שהכח בימין וגבורה בשמאל שזהו בחי' גבורה דיצחק שנכללים בבחי' חס' דאברהם שאז החסדים באים בתגבורת גדולה וז\"ש וזרוע קדשו וכמו ובזרוע עוזו שהוא בחי' יד שמאל בבחי' העוז וגבורה כשמתחבר בימין ונעשה אתערותא כלול מחו\"ג לקבלא לה כו' וכמש\"ל לאפרשא ימינא ושמאלא לקבלא לה כו' ועד\"מ הנ\"ל במדות שבלב שכאשר פנימי' החיות שבמדות מאיר בדבור אז מושך את הדיבור אליו ומתייחד בו והוא מה שהדבור הולך במהירות ומתקרב מאוד אל המדות כו' והנמשל יובן בבחינת שיר חדש שבא מצד אור קירוב המשכות המשפיע אל המקבל שהמקבל נמשך ממילא וכענין משכני אחריך נרוצה דאחר המשכה של המשפיע ביד ימין אז נרוצה כו'). באתחדתות'"],[2400650250,"דסיהרא מן שמשא שהוא בחי' ז\"א שהוא על ידי אתערותא דמדות דז\"א בבחינת חו\"ג שבו לקבלא לה לבחינת המל' שהוא בחינת הדיבור כידוע וד\"ל ומה שאמר כגוונא דעגלות סלקין לבית שמש לכאורה א\"ז דומה לזה כלל שהרי א' בפי' הושיעה לו דקא באתערותא דמשפיע אל המקבל ועגלות דסלקין הוא בחי' עליי' המל' ע\"י המרכבה כו' אך פי' כגוונא זה הוא בדומה לבחי' העלאת מ\"ן דמל' במרכבה שלה שהן עגלות ופרות דסלקין כמ\"ש הלוך וגעו בבחי' ביטול גדול שכלול מאהוי\"ר יחד שזהו התכללות דחו\"ג כתגבורת גדולה כמו והחיות נושאות את הכסא כך נמשך בחינת חו\"ג דז\"א מלמעלה למטה לקבלה לה לבחינת המל' (ואף על פי שסיבת עליי' המל' רק משמשא בא דאל\"כ למה נק' שיר חדש הל\"ל שירה חדשה כנ\"ל וא\"כ איך א' כגוונא דעגלות סלקין לפי אופן העלאה שלהם כך נמשך כו' הרי נהפוך הוא דכגוונא דאתערותא דחו\"ג דז\"א כו' כך העגלות סלקין בהעלאה לבחינת המל' הענין הוא שיש הפרש בין העלאת מ\"ן דמרכבה לעלות למל' להעלאות המל' עצמה דעליות המל' בא מכח אור דז\"א כנ\"ל אבל העלאה וביטול היש לאין דמרכבה בא מכח עצמה ומ\"מ השיר שלהם בעלותם נקרא שיר חדש וכמ\"ש וישרנה ולא א' ותשרנה ל' נקבה משום דהוי אמרו מזמור זה והעלאה שבא מכח המקבל עצמו נק' שירה חדשה הרי כבר מבואר [למעלה] שיש ב' מיני ביטול היש א' ביטול היש בהיותו בריחוק כו' ומה שאמר כאן כגוונא דעגלות כו' הוא מדבר בריחוקם עדיין אבל כאשר הלכו אל בית שמש אמרו שירו לה' שיר חדש ע\"ש חידוש האור דשמשא בסיהרא שזה שיר חדש גם מטעם דקדוק הא דלא תדיר קאמרי לשיר כזה (וא\"ז מתיישב לפי הפשט). ובגין דשבת איהו סליקו דכורסייא לעילא פי' בחינת עליי' המל' שבבריא' בבחינת האצי' ממש ע\"כ תיקונא דתושבחתא דא בשבת דוקא לפי שכל התשבחות הללו אינם רק בשביל בחינת עליי' המל' כמש\"ל ובשבת הוא עיקר עליית העולמות כמ\"ש בפע\"ח (ודוקא עליית פנימית העולמות ולא חיצוני' ולע\"ל יהי' עלי' גם בחיצוני' כמו חיצוני' הדבור והמדות והמוחין כו' שאם הי' עלי' ושביתה גם בחיצוני' לא הי' השפע אלקי' נמשך כלל בעולמות בשבת ע\"י הדבור ואנו רואים שמצמיח תבואות ומוריד גשמים כו' לפי שהדיבור נמשך בחיצוני' כמו בחול רק הפנימית עולה ועד\"ז עד רום המעלות כידוע וד\"ל):"],[2400650251,"<h3>מזמור שיר ליום השבת</h3>\n(סו) <b>מזמור</b> שיר ליום השבת תושבחתא דא אדה\"ר קאמר לה בשעתא דאתתרך מג\"ע ואתא שבת ואגין עלי' ואוקמא חברייא תושבחתא דא עלמא תתאה קא משבח לגבי עלמא עילאה יומא דכולא ביה איהו שבת מלכא דשלמא דילי' ודא איהו מזמור שיר ולא כתיב מאן קאמר לי' ליום השבת יומא עילאה שבת עילאה דא שבת ודא שבת שבת עילאה שבת תתאה מה"],[2400650252,"בין האי להאי אלא שבת סתם דא שבת דמעלי שבתא יום השבת דא שבת דלעילא דא יום ודא לילה ע\"כ. והנה תחילה י\"ל כללות ענין המאמר דמ\"ש עלמא תתאה קא משבח לגבי עלמא עילאה כו'. דהנה בא לדקדק במ\"ש מזמור שיר ליום השבת דמשמע מזמור שיר זה יום השבת אמרו. וזהו אא\"ל דלא מצינו שיום השבת עצמו א' איזה שיר כו'. וא\"כ בהכרח לפרש כך כאן מזמור שיר ששיר הזה לגבי יום השבת אמרוהו ולא שיום השבת עצמו אמרו ולפ\"ז למה לא נז' מי הוא האומרו לגבי יום השבת וז\"ש ודא איהו מזמור שיר ולא כתי' מאן קא' לה מאחר דלא יום השבת עצמו אמרו ולזה בא לפר' דעלמ' תתא' אמר מזמור שיר זה לגבי עלמא עילאה (ומ\"ש מזמור שיר סתם כדמפרש ואזיל בסמוך כמו ויקרא אל משה סתם כו') וביאור ענין עלמא תתאה ועלמא עילאה ידוע דבחי' מל' דאצי' שמחי' כל העולמות מאין ליש בבחי' גבול באותיות דע\"מ כו' הוא הנק' עלמא תתאה ולהיות שבשבת הוא עליית המל' מבי\"ע בבחי' האצי' שנק' עלמא עילאה לזה א' דעלמא תתאה קא משבח לגבי עלמא עילאה כמ\"ש למען יזמרך כבוד כו' כבוד תחתון דמל' יזמרך בבחי' שיר לפי שכל העליות הם באים בבחי' שיר דוקא כשיר של המלאכים וגם ההעלאה דמל' הוא בשיר ונק' מזמור שיר סתם שהוא שיר דמל' שנק' עלמא תתאה כשעולה פנימי' שלה מן הצמצום בחיצוני' דאותיו' הדיבור (והגם שבחול ג\"כ בחי' המל' עולה בבחי' הגבו' דשם אלקים כמ\"ש בזוהר ע\"פ אלקי' אל דמי לך דנהו\"ת קארי תדיר לנהו\"ע ולא שכיך לעלמין כו' וכן לא ידום וכן אש תמיד תוקד כו' לא תכבה ונק' עולת תמיד העשוי' כו' והיינו בחי' ה\"ג דנוק' כמ\"ש ואל אישך תשוקתך בתמידות כו' ומה זה שא' מזמור שיר זה דמל' בהעלאה לגבי ז\"א שנק' עלמא עילאה אינו אלא בשבת דוקא. הענין הוא דבשבת ההעלא' הוא להיות יחוד פב\"פ כו' דהיינו בהיותה בבחי' המוחין דגדלות שבמדות כו' שזהו בחי' שבת אלא שנק' שבת תתאה שבת דמע\"ש כו' קא' שיר זה לשבת עילאה דז\"א כו' משא\"כ בחול שלא נק' המל' שבת תתאה אלא נהו\"ת בצמצום דשם אלקי' ועולה מן הצמצום דבי\"ע להיות בבחי' נקודה תח\"י בלבד כידוע וד\"ל) ומ\"ש דאדה\"ר קאמר לה כו' הענין הוא דאדה\"ר קודם החטא הי' ראשו בג\"ע דבריאה ורגליו בעשי' ונקרא אדם דבריאה כו' וכשחטא גרשו כו' לפי שגרם בחטא עה\"ד כו' להיות בחי' פגימת הלבנה שמקבלים משם חיצוני' כו' (שזהו ענין בא נחש על חוה בבחי' גבורות קשות כו') אך זה בחול דוקא שהמל' מוסתרת בבי\"ע בבחי' מיעוט הירח כו' (כמ\"ש דא יום ודא לילה כו') אבל בשבת שהוא עליי' המל' מבי\"ע להיות בבחי' אצי' ממש ביחוד דפב\"פ בשמשא כמש\"ל בפי' שיר חדש הרי אין שם ענין פגימה ומיעוט הירח כלל אלא מתמלאת"],[2400650253,"מאור השמש כו' (כי באצי' לא פגם מאומה שהוא בבחי' עה\"ח שלמעלה מעה\"ד טו\"ר שבמל') ע\"כ אדה\"ר א' שיר זה בשעתא דאתתרך מג\"ע ואתא שבת ואגין עלי' בשבת דוקא כי בשבת אין עליו חטא כלל כי לא חטא שם מאומה כי לא גרם בחטאו רק בעה\"ד טו\"ר שלמטה בעלמא תתאה אבל כשהמל' עול' לגבי עלמא עילאה עולם האצי' ממש שאין שם פגם כלל לכך השבת מגין עליו ולזה א' אדה\"ר תושבחתא דא (שגם הוא עולה בשיר זה גם לאחר שגרשהו מג\"ע כידוע דנשמות דבריאה ויצי' עולין ג\"כ באצי' מדי שבת וחודש להשתחוות לפני ה' וכידוע בענין עליות הנשמות בע\"ש ביה\"ש כו' וכל הנשמות כלולות באדה\"ר כידוע וד\"ל). והנה להבין מ\"ש בענין עלמא עילאה שהוא בחי' ז\"א דאצי' שנק' יומא דכולא בי' כו' שבת כו' דהיינו יום שכולו שבת וכמשמעות ל' יום השבת שכולו שבת ואיך יתכן שיהי' כולו שבת הרי אין שבת בלא חול שבו שבת וינפש מן העבודה ונק' מנוחה אבל יום שכולו שבת היינו בחי' מנוחה עצמי' שלא מן העבודה דקודם וכמו לע\"ל שיהי' מנוחה לחה\"ע בחי' מנוחה עצמיות ולא משום ששבת וינפש כמ\"ש במ\"א ולזה מתרץ באומרו יום דכולא בי' איהו שבת מלכא דשלמא דילי' פי' לא מצד בחי' ז\"א עצמו גם לא מצד בחי' המוחין שבמדות שהרי אינו בא רק מן העבודה דבירורים דחול אלא מצד בחי' עצמי' ופנימי' דאו\"א שמאיר בז\"א בשבת דנק' מלכא דשלמא דילי' כו' איהו כו' מפני זה נק' יום שכולו שבת לפי שבחי' פנימי' דאו\"א למעלה מן בחי' הבירורים דחול לגמרי דהגם שבחכ' אתברירו היינו בבחי' החיצוני' דאבא ולא בבחי' הפנימי' (דגם שהפנימי' מלובש' בהעלם בחיצוני' עד\"מ הנ\"ל דחכם שמצמצם פנימי' שכלו להסביר לתלמידו או להתחכם בפנימי' שכלו בדבר תיקון איזה מלאכה ועבודה היינו רק ירידת בחי' הפנימי' ממקומו להתלבש בחיצוני' כו' משא\"כ בשבת הרי עולה בחי' הפנימי' למקומו שלמעלה לגמרי מבחי' הבירורים והתיקון כו' וד\"ל. וכדוגמא דלחה\"פ שכולו פנים בחי' פנימי' כי בשבת בורר אסור להיותו למעלה מהבירורים מטעם זה) כי הלא ידוע דבחי' זו\"נ דאצי' הרי הן באין מאצי' לבי\"ע לברר בירורים דרפ\"ח כו' וכמו בחי' המל' דכתי' בה ותקם בעוד לילה ותתן טרף רפ\"ח ע\"ה והוא בחי' שם ב\"ן שיורד לברר ניצוצים שנפלו בנוגה כו' כך גם מבחינת מוחין דמדות דו\"ק דז\"א יורדין בכל יומין דחול לברר וללקט ניצוצין דרפ\"ח כו' וכמ\"ש ה' איש מלחמה כו' שהאיש דרכו לכבוש כו' שיש בכח הדכר לברר יותר והוא בחי' שם מ\"ה דחכ' דז\"א שנותן עוז לאלקים בחי' ב\"ן לברר כו' וכמ\"ש בזוהר ע\"פ הנה מטתו שלשלמה ששים גבורים סביב לה מגבורי ישראל דלעילא שהן ס' גבורות דו\"ק דז\"א שהן גבורי ישראל סביב למטת שלמה כו' מלומדי מלחמה כו' לברר בירורים דרפ\"ח כו' (והן י\"ב אלפי צבא שצובאין על"],[2400650254,"מדין שהן ששה כפולין וביום א' יורד מחסד דז\"א וביום ב' מבחי' הגבו' כו'). אך הנה בחי' פנימי' או\"א שלמעלה מבחי' מ\"ה דחכ' שבז\"א אינן יורדים בחול לברר בירורים כלל וכלל (כי בחי' הבירורים דחול הן ל\"ט מלאכות חורש וזורע שהן בחי' תיקון ובבחי' פנימיות החכ' כמו שהוא בפנימיות ע\"י אין שם בחי' הבירורים וכמ\"ש בזוהר באתי לגני אכלתי יערי כו' אבל באתרי' לאו אורחא למיכל כו') והיינו ענין יום שכולו שבת שאינו בא מצד העבודה ותיקון כלל כנ\"ל והוא שמאיר בז\"א בכל שבת ע\"כ נק' גם הוא יום השבת יום שכולו שבת כו' ולא מצד עצמו רק מפני שפנימיות מוחין דאו\"א מאירים בו בשבת כנ\"ל וז\"ש יומא דכולא בי' איהו שבת מלכתא כו' וד\"ל:\n(סז) <b>אך</b> הנה יש להבין בתוספות ביאור וטעם למה אין פנימיות או\"א באין למטה בבי\"ע בחול לברר בירורים רק ע\"י התלבשות שלהם בז\"א מבחינת חיצוני' שלהם כו' ולמה אינם מבררים בבחי' פנימי' עצמותם כו'. וילה\"ק תחלה הידוע בע\"ח דעיקר השביר' הי' רק בבחי' המדות בלבד כענין אמרם אברהם חסד דקדושה יצא ממנו ישמעאל מותרי החסדי' (וכידוע בענין נט\"י לסעודה להסיר יניקת חסדים דקליפ' דמקבלים מציפרני' דיד כו') ויצחק שהוא בחי' גבורה יצא ממנו מותרי הגבורות קשות דעשו כו' והוא שורש להתהוות מדות רעות דקליפה שזהו מצד בחי' השבירה שהי' בז' מדות דתוהו אבל בחו\"ב לא הי' בחי' שבירה כלל רק בחי' נפילה בלבד שנפל מהם למטה וגם זאת רק מבחינת החיצוני' שלהם נפלו למטה בעולם הבריאה כו' כמ\"ש בע\"ח (וביאור ענין ההפרש בין שבירה לנפילה מבואר במ\"א כמו שאנו רואים למטה במדות רעות בתאוה רעה ורציחה וכה\"ג הוא רע גמור אבל חכ' חיצוני' אינו כן כחכ' התכונה וכה\"ג ואינו מטמא הנפש כ\"כ אבל לא חכמת בני מוקדון שהוא המנגד ממש לחכ' דקדושה וכידוע בענין נס דחנוכה) ולהיות כי רק בחי' אחוריים דאו\"א נפלו למטה בעולם הבריאה אבל בחי' הפנימי' שלהם גם בחי' נפילה לא הי' בהם כלל הרי הן בעצמם א\"צ תיקון ובירור שכבר הן בבחי' מדרגה העליונה שא\"צ לתיקון (כמו כל אור ושפע שאין בהם פסולת וחיצוני' כלל אלא כמו בחי' פנימי' ועצמי' בלי חיצוני' כלל כדוגמא דמן שלא הי' בו פסולת כלל שהרי נבלע ברמ\"ח אברים לפי ששרשו בבחי' פנימי' חכ' דאצי' שלא הי' בו נפילה למטה כלל וכמו כן במשה נאמר לחם לא אכל אלא לחם אבירים אכל לחם שמה\"ש כו' דהיינו גם לא בבחי' לחמה ש\"ת שבא למטה בבחי' הבירורים לברר לעה\"ד טו\"ר שהוא בחי' החיצוני' דחכ' אלא כמו שהתורה הוא למעלה בבחי' פנימי' אבא וזהו לה\"פ שכולו פנים כו' והוא ענין"],[2400650255,"סעודות שבת כו') ולפי שהמברר צריך להתלבש בלבוש המתברר דוקא ואם לאו לא יוכל לבררו ע\"כ אין פנימי' דאו\"א יורדין לברר בחול מאחר שבעצמם א\"צ תיקון ובירור ערכם רחוק לבא בהתלבשות וירידה כ\"כ לבא למדרגת המ[ת]ברר לברר[ו] ולתקנו אלא רק בחיצוני' שלהם שהי' בהם בחי' נפילה למטה יורדים למטה בהתלבשות לברר בירורים (כמו אורייתא דמח\"ע נפקת שבאה בהתלבשות לברר בירורים דעה\"ד כמ\"ש להבדיל בין טמא לטהור ולכן נק' נובלות חש\"מ כידוע (אבל באמת זהו לשבח קאמר משום דמה שיש בכח החכ' לברר מטה מטה זה בא מפנימי' כח דחכ' יותר וכמ\"ש למע' וכמש\"ל בענין הירושלמי דבקושי התירו לדבר ד\"ת בשבת כו' ואדרבה מצינו במ\"א שהוא ההיפוך מכלל הנ\"ל דאדרבה כל מי שהוא מבורר כבר בעצם וא\"צ בירור ותיקון לעצמו הוא היורד למטה מטה לברר למי שצריך בירור כי יש בכחו לירד למטה הימנו לבררו אחר שכבר הוא בבחי' הבירור כענין קשוט עצמך תחלה ואח\"כ קשוט לאחרים כו' אבל מי שצריך תקון לעצמו אין יכול לבא לברר למטה הימנו כו' כמו משה שהי' בבחי' פנימי' חכ' שכבר הוא מבורר בא למטה לתקן לישראל ע\"י תומ\"צ וכמ\"ש בו מן המים משיתיהו (משמיטת החסד שהוא אחר התיקון כו') וכן התור' שירדה למטה לברר לפי שבשרשה כבר היא בבחי' הבירור וכמ\"ש כל אמרת אלוה צרופה כו' ונק' חכ' ברורה וכמ\"ש ואהי' אצלו אמון כו' (וכמ\"ש במ\"א) וכן הנשמה בגוף שירדה לברר ולתקן הנה\"ב דהיינו בחי' מ\"ה דאדם שמברר לב\"ן בחי' בהמה כידוע בפי' אדם ובהמה תושיע כו' וזרעתי בנ\"י זרע אדם כו' והיינו דוקא לפי שהנשמה א\"צ תיקון לפי שבאה מעולם התיקון (שהוא אדם דאצי' כו') ע\"כ בכחה לברר לבחי' נוגה דנה\"ב כו'). ולהבין ביאור הדברים הנה ילה\"ק תחלה בשורש ענין הבירורים מהו בהיות ידוע שכל ענין הבירור והתיקון הוא לאהפכא חשוכא לנהורא שזהו לעשות בחי' ביטול היש לאין כי בהיות ידוע בעיקר ענין השבירה שהוא בבחי' הגשמת וירידת האור ושפע ממדרגה למדרגה ע\"י רבוי הצמצומים במיעוט אחר מיעוט עד שיוכל להיות בחי' יש נפרד לגמרי בבחי' הגסות והישות ביותר וכל שהאור יורד בצמצום ומיעוט ביותר יותר יהי' הבריאה המסתעפת שם בבחי' הרגשות הישות והגסות ביותר (וכל הקרוב יותר לבחי' גילוי האור והשפע האלקי בלי צמצום והסתר כ\"כ יותר יהי' בו בחי' הביטול של הישות לאין האלקי כמ\"ש במ\"א) וכמו ע' שרים דנוגה דעשי' ששם צמצום האור האלקי היותר אחרון בבחי' אחוריים דאחוריים דשם אלקי' דמלך על גוים כו' הרי שם ירד האור בהגשמה כ\"כ מצד עוצם ההסתר עד שהן בבחי' ישות וגסות ביותר להחזיק עצמו לבחי' יש ודבר נפרד בפ\"ע לגמרי כמו שר של מצרים שא' לי יאורי ואני עשיתני כו' וכן יאמרו הגוים"],[2400650256,"ידינו רמה ולא ה' פעל כו' וכה\"ג כו' (והגם שלפרקים אומרים שירה כמו שרו של עשו כו' כי מיעוטו טוב ורובו רע בנוגה דעשי' ולכך כתי' הללו את ה' כל גוים כו' משום שיש בחי' ביטול בהן לפרקים וכידוע דקרו לי' אלקא דאלקיא ומ\"מ אמרו שיודעים רבונם ומכוונים למרוד בו כו') והנה זהו בחי' הבירורים ולהפוך היש והגסות לבא לבחי' אין וביטול והוא מ\"ש בזוהר לאהפכא חל\"נ כו' וכד אתכפיא סט\"א כו' כי אתכפייא בהודאה בלבד כמו יתרו שא' עתה ידעתי כו' וכן מ\"ש במצרים וידעו כו' ואתהפכא הוא בחי' ביטול ממש מיש לאין כמו וצבא השמים לך משתחוים כו' וכה\"ג אך הנה א\"א להיות בחי' ביטול היש לאין כ\"א ע\"י המברר שהוא בחי' החכ' דקדושה דבחכ' אתברירו דהיינו בחי' כח מ\"ה דאין האלקי שהוא היפוך היש לגמרי וכל שיש בחי' אין ומ\"ה דחכ' יותר שם מתברר ומתהפך בחי' היש לאין שנק' ביטול וכמו במסעות שבמדבר בארון ולוחות דכתי' קומה ה' ויפוצו אויביך שנכנעו גקה\"ט שבמדבר נחש שרף ועקרב כו' וע\"ד דוגמא באור פני מלך הרי יתבטל כל בחי' יש וגסות כו' וזהו כל עיקר בחי' חכ' כח מ\"ה שהוא לעשות בחי' ביטול היש לפ\"ע הבחי' אין דחכ' ולזה אמר דבחכ' אתברירו דוקא וזהו כל עיקר התו' דאורייתא מח\"ע נפקת לברר לבחי' נפרד דטמא ופסול כו' אך כ\"ז כח המברר א\"א רק לבחי' חיצוני' דחכ' שנק' כח מ\"ה שהוא לעשות בחי' ביטול היש והמשכת הביטול תלוי לפ\"ע המשכה וירידת האור דחכ' כח מ\"ה עד גם בע\"ש להמשיך בהם בחינת ביטול והיותר קשה לברר מכולם הוא בחי' מקור ושורש כל הישות וגסות דקליפה והוא בחי' חכ' דקליפה שנאמר בה ארמי אובד אבי שהוא לעומת ממש לנגד חכ' כח מ\"ה דקדושה וכמ\"ש במ\"א במ\"ש ופילגשו ושמה ראומה ראו מ\"ה כו' שהוא בחי' ההרגשה בעצמו ליש דוקא וזה כל חיותו ממש כמו איש חכם בעיניו גם שהוא בטל מרגיש בבחינת יש לעצמו לומר ראו מה ראו בחינת המ\"ה והביטול שניכר ובולט בו ביותר כי עיקר נקודתו הוא בחי' הרגשת עצמו דוקא ומסתעף מזה מקור כל בחי' יש נפרד בגסות גמורה כנ\"ל. (והוא הי' בימי חשמונאי שגברה חכמת יון חכ' הפילסופיא לעשות שכלו ליש והוא שמבטל הכל לגבי עצמו כו' היפוך בחי' ביטול דכח מ\"ה האלקי חכ' דקדושה שהוא חכ' קבלה האלקי' להשיג בבחי' אין האלקי כו' שכל שמשיגו יותר יותר בא לבחי' ביטול היש דעצמו כמו לך ה' הגדולה כו' וכה\"ג) אמנם בחי' חכ' דקדושה שהוא מקור כל בחי' אין האלקי הוא דוקא המברר לחכ' דקליפה כמו יעקב עם לבן דהיינו להפוך גם למקור כל בחי' יש שהוא בחי' חכ' דקליפה כי לפ\"ע רבוי האור [דמ\"ה] דחכמה דקדושה כך יהי' ערך השפלת יש דחכ' דקליפה כמו יתרו ראש בחכ' דקליפה הרי נתבטל"],[2400650257,"כל מקורו לגבי משה חכ' דקדושה ואמר עתה ידעתי כי גדול ה' מכל האלקים כמ\"ש במ\"א דעיקר יניקת החיצוני' רק מאלקי' אחר הצמצום ובהסיר המסך דשם האלקים לגבי שם ה' דאצי' יתבטלו כולם גם חכ' דקליפה וכמ\"ש כי בכל חכמי הגוים כו' מי לא ייראך מלך הגוים כו' וד\"ל. ואמנם צריך המברר להלביש עצמו בלבוש המתברר וא\"ל לא יוכל לבררו כנ\"ל א\"כ אין המברר ליש דחכ' הקליפה שהוא מקור כל יש דמדות דקליפה בע\"ש רק ע\"י בחי' חיצוני' חכ' דקדושה שהוא בחי' אחוריים דאו\"א שנפלו בבריאה שיוכלו להתלבש ביש חכ' דקליפה לבררם אבל בחי' פנימי' דחכ' דקדושה שהוא בחי' עצם פנימי' אין האלקי מקור החכ' כמ\"ש והחכ' מאין תמצא בחי' פנימי' אבא שלא נפלו למט' כו' רחוק ערכו מירידה גדולה כזאת לבוא למטה לעשות בחי' ביטול היש ובפרט ליש דחכ' דקליפה מאחר שנבדל ומרומם מאוד לא יוכל להשפיל א\"ע להיות בחי' אין של היש הנק' ביטול דחכמה כו' כי הוא בחי' אין בעצם כידוע (וז\"ש וכבודי לאחר לא אתן גם לבררו כו') וראי' מחכ' דתו' שירדה לברר הרי א' וראית את אחורי שירד לברר ופני לא יראה כו'. וז\"ש כאן דיום השבת יומא דכולא בי' כו' שהוא בחי' פנימי' או\"א שמאיר בז\"א בשבת שהוא למע' מבחי' הבירורים לגמרי ולכך כולו שבת בלי הקדמת חול מקודם כנ\"ל לפי שבחול אין יורדין לברר למטה רק מחיצוני' דאו\"א ולא מבחי' הפנימי' שלהם כלל מטעם הנ\"ל וד\"ל. (ולפי המבואר במ\"א נהפוך הוא דדוקא מכח פנימי' ג\"ר דאו\"א בא כח הבירור דחיצוני' חכ' וכמש\"ל בשורש התורה כו' ואפשר לחלק בין פנימי' הכתר שלא בא בבחי' ח\"ס כלל ובין המשכות בחי' פנימי' הכתר בח\"ס כדי שיוכלו לברר ושניהם אמת וד\"ל):\n(סח) <b>והנה</b> מ\"ש מלכא דשלמא דילי' לכאורה אין לו שייכות לענין עיקר הכוונה במאמר זה דשיר ליום השבת שהוא לגבי בחי' פנימי' אבא שבז\"א שהוא יום שכולו שבת בחי' שבת עילאה כנ\"ל. הנה יובן בהקדים תחילה בפי' שלום שהוא בחי' יסוד דדכורא דוקא דהיינו בחי' התקשרות והחיבור דמשפיע במקבל כמו שמבואר במ\"א בפי' יעשה שלום לי שלום יעשה לי ב' שלימות שלום בפש\"מ בחי' יסוד דמשפיע למקבל כמ\"ש וידעת כי שלום אהלך כו' משים שלום בבית כו' וכן אדברה נא שלום בך ובפנחס דכתי' בריתי שלום וכן ת\"ח שנא' בהם ורב שלום בניך שמרבים שלום בעולם וכה\"ג הכל בבחי' ההתחברות דמשפיע במקבל (ובחי' התקשרות דמקבל במשפיע שלום בפמשמ\"ט הוא בחי' יסוד דנוק' וז\"ש שלום יעשה לי כו'). אך הנה מלכא דשלמא דילי' שזהו מלך שהשלום שלו דהיינו שהוא נבדל בעצם ואין לו שיתוף וחיבור שיתייחס השלום בלבדו שהשלום שלו בלבד כי יש שלום סתם שאין השלום דמשפיע לבד רק בא"],[2400650258,"מאמצעות וחיבור דמשפיע במקבל ג\"כ (עד\"מ השלום בין ב' הפכים או במחלוקת ופירוד בין ב' אנשים שנעשה השלום ביניהם כענין עושה שלום במרומיו בין מיכאל וגבריאל ב' הפכים הרי מהות ועצם זה השלום נעשה מאמצעות וחיבור ב' הפכים או ב' אנשים הנפרדים במחלוקת וא\"א שיהי' לשלום שלימות כשאינו רק מצד א' וכך בחיבור דמשפיע במקבל שיש גם בשלום דדכורא כשמתחבר עם המקבל שיתוף מכח חיבור של המקבל דאם לא התחברות המקבל אליו אין זה שלום מצד עצמו לבד מאחר שנק' חיבור ואין חיבור בא אלא מכח ב' נפרדי' או משפיע ומקבל יחד כו') משא\"כ שלום שאינו מתייחס רק לא' א\"כ א\"ז בא בחיבור דמשפיע ומקבל וזהו דמיון להבין בפי' מלך שהשלום שלו בלבד בלי עירוב בו מכח שלום וחיבור זולתו כלל להיותו נבדל בעצם ואין לו שיתוף וחיבור שיתייחס חלק בשלום זה מזולתו וחוץ ממנו כלל וד\"ל. וזהו ההפרש בין בחי' יסוד ז\"א שגם הוא בחי' שלום וחיבור דמשפיע ומקבל אבל לא נק' מלך שהשלום שלו בלבד כי בא מכח אמצעו' חיבורו במל' בחי' המקבל שיש לו בה חיבור ומתייחס החיבור ע\"ש שניהם אבל בחי' יסוד אבא שמלובש ביסוד ז\"א הוא הנק' מלכא דשלמא דילי' בלבד שנק' שלום דאור אבא מצד עצמו לבד שלא בא בו מבחי' חיבור בזולתו כלל והגם שבחי' יסוד אבא הוא המתחבר ביסוד אימא בחי' המקבל כידוע בבחי' יחוד דאו\"א שיש לו חיבור בזולתו שהוא בחי' אימא והיינו נקודת אור חכ' שבא בהשגה דבינה מאין ליש ונק' תרין ריעין כו' אמנם זהו דוקא בהיות או\"א בהתחברותם ביחוד עצמן דוקא אבל כשיורד אור אבא בז\"א היינו אחר התלבשות דאו\"א בז\"א מחיצוני' שבהן ולאחר שנבקע בחי' יסוד אימא ונולדו המדות כו' אז יוצא אור אבא מהעלמו בבינה להמדות דז\"א ונמשך ומגיע עד בחי' יסוד ז\"א כידוע בע\"ח דאור אבא ארוך משל אימא דאור אימא מסתיים בחזה דז\"א כו' ויסוד אבא מאיר עד יסוד ז\"א (וז\"ש הנה ה' יוצא ממקומו וכנ\"ל באריכות) ונמצא יסוד אבא שביסוד ז\"א אין לו חיבור באימא כלל כי כבר נסתיים אור דאימא בחזה כו' והיינו שנסתלקו בחי' נה\"י דאימא למעלה (וכמ\"ש בע\"ח וראיתן על האבנים שהירכים מצטננות בשעת לידה כו' כנ\"ל). ולא נשאר רק בחי' הארת יסוד אבא ביסוד ז\"א ואז הוא נק' מלכא דשלמא דילי' בלבד שאינו רק מכח אור אבא עצמו מצד שרשו בפנימי' אבא שהוא פנימי' ע\"י שנק' יום שכולו שבת ונק' שבת עילאה כנ\"ל. וכידוע דמלכא עילאה הוא אור אבא ומלכא תתאה בחי' ז\"א וכמ\"ש מה שמו מה שם בנו ודוקא מצד בחי' מ\"ה דפנימי' אבא שביסוד ז\"א שמתגלה בחי' יסוד אבא שמלובש בו בלי שיתוף דאור אימא כנ\"ל אז נק' ז\"א מלכא דשלמא דילי' משא\"כ יסוד ז\"א לבדו כנ\"ל (ולא"],[2400650259,"ביסוד אבא כשהוא בהעלם ביסוד אימא שגם אז לא נק' מלך שהשלום שלו בלבד וד\"ל). ולהבין ביאור כ\"ז הנה ביאור מה שיסוד אבא מגיע ביסוד ז\"א ואור אימא מסתיים כו' כידוע (וכבר מבואר למע' קצת באופן אחר) להיות שהבינה נק' אם הבנים שהן המדות שנולדו מן ההתבוננות והוא מבחי' יסוד אימא שהוא בחי' ההתקשרות בכלי הקליטה למושכל וכאשר נקלט עדיין ביסוד אימא בית קבול לההשגה עצמה אזי עדיין לא נולדו התפעלות המדות אוי\"ר בלב וכמו בחי' חסדי' המכוסים ונעלמים ביסוד אימא שהוא אה' הכלולה בשכל כידוע. אך כאשר נבקע יסוד אימא כו' היינו שנתקצר ונסתלק כל האריכות המושכל מכלי הקליטה שבמוח הבינה אז יוצא התפעלות המדות לגלוי בלב במהות בפ\"ע וכנראה בחוש בהתפעלות אהוי\"ר שבלב בתפלה אינו אלא לאחר שנתקצרה ההתבוננות (שמחמתה תולד ההתפעלו' בלב) ונסתלק ונתעלם כאלו לא הי' (וזהו צינון דנה\"י דאימ' בשעת לידה דוקא) וסיבות הסתלקות אור ההשגה דבינה הוא מצד היותה מבחי' הגבורות ברשפי אש בשמחה והתלהבות שעולה מלמט' למעלה כמ\"ש במ\"א אבל בחי' יסוד אבא הוא בא מכח אור החכ' שהוא מבחי' החסדי' שיורדים מגבוה לנמוך מלמעלמ\"ט והוא בחי' המשכת ביטול דכח מ\"ה שיורד ונמשך עד למטה מטה דוקא והוא עד בחי' יסוד ז\"א בהבל החזה המורגש בלב והוא בחי' ראי' השכל שבלב שבא במורגש בחזה דהבל הלב (בל\"א דיא הארץ דער זעט דעם תמצית הענין כו' וכמ\"ש במ\"א) וכמ\"ש ולבי ראה הרבה חכ' כו' וכמ\"ש ברע\"מ דבעין השכל דבלבא אתחזא כולא כו' (שהרי גם דבר הנעלם או מה שעתיד להיות הלב מרגיש דוקא כמו הלב יודע מרת נפשו ולהיפוך מרגיש בשמחה ובשורה טובה שבהעלם העונג שבנפשו כמו שיודע במרת נפשו כו'). ומעתה יובן בענין מלך שהשלום שלו בלבד כנ\"ל שהוא דוקא בבחי' יסוד אבא שמלובש לבדו ביסוד ז\"א אחר שיצא מהעלמו ביסוד אימא כנ\"ל להיות מבואר במ\"א בענין למרבה המשרה ולשלום אין קץ כו' שיש כמה מיני שלום והוא בא במספר כפי מספר היחודים דמשפיע ומקבל בפרטי פרטיות כמו ביחוד דאו\"א בדרך פרט נק' שלום דיסוד אבא ביסוד אימא וכן בזו\"נ ביסוד ז\"א ונוק' בכמה פרטים יחודים (וגם למע' בא\"א וע\"י וא\"ק כו' יש בחי' מ\"ה וב\"ן מאחר שבחי' עילה ועלול שייך בהן בסדר השתלשלות מעליון לתחתון כמו ממל' דא\"ק נעשה כתר דע\"י כו') אבל מ\"ש לשלום אין קץ כלל הוא בבחי' עצמיות אא\"ס שנק' עילת כל העלות כו' אפילו אור צח כו' כי הרי בחי' אח\"פ אין לו חיבור זולתו שישלימנו וכל מה שמתחבר עצמו למטה הוא רק מצד עצמו ממש שנק' שלימותא דכולא לכך לשלום שלו אין קץ וכמו שלמטה עד אין תכלית כך למעלה עד אין קץ בעא\"ע בעצמותו ע\"כ נק' מלך שהשלום שלו בבחי'"],[2400650260,"עצמותו ממש (וכן מ\"ש ורב שלום שמרבים שלום כו' עד אין שיעור למעלה ולמטה מטעם דשורש התורה בעצמותו ממש) וזהו יום שכולו שבת בחי' מנוחה לחה\"ע בבחי' עצמותו ממש שלא מצד השביתה כנ\"ל. ולזה א' כאן מלכא דשלמא דילי' על בחי' יסוד אבא שהוא לבדו בכלות הכל דוקא ביסוד ז\"א דוקא שנעתב\"ס וסוב\"ת דהיינו בשורש הראשון לכולם והוא בעצמיות ממש שהשלום שלו ממש (משא\"כ בשלום דיסוד אבא באימא ולמעלה הימנו וגם ביחוד וחיבור היותר עליון א\"ז שהשלום שלו בלבד) והיינו בבחי' שיר והעלאה דשבת תתאה דכלות הכל כמ\"ש וירא כו' כי טוב מאוד שמגיע בשלום שלו הנ\"ל. משא\"כ העלאה [ושיר] דבחי' המל' בחול לגבי ז\"א כמ\"ש למען יזמרך כו' אלקים אל דמי כו' היינו רק לבחי' יסוד ז\"א שלא מצד בחי' יסוד אבא שבו כלל אבל בשבת נאמר צדיק כתמר כו' כארז בלבנון ישגה כו' בבחי' טוב מאוד שבעצמות ממש שהשלום שלו ממש (וכמ\"ש במ\"א בענין שיר השירים אשר לשלמה מלך שהשלום שלו כו'):\n(סט) <b>ליום</b> השבת יומא עילאה שבת עילאה דא שבת ודא שבת מה בין האי להאי אלא שבת סתם דא שבת דמעלי שבתא יום השבת דא שבת דלעילא דא יום ודא לילה ושמרו בני ישראל את השבת דא לילה רזא דנוק' זכור את יום השבת דא יום רזא דדכורא ע\"כ. פי' הטעם דשמור לנוק' דוקא הנה יובן בהקדים תחילה שורש הרמ\"ח מ\"ע ושס\"ה ל\"ת דארז\"ל שמי עם י\"ה שס\"ה וזכרי עם ו\"ה רמ\"ח כו' להיות ידוע בשורש מ\"ע ול\"ת שהן ב' מדות אהוי\"ר האהבה שורש כל המ\"ע והיראה שורש כל הל\"ת דהנה א' בזוהר לית פולחנא כפולחנא דרחימותא וי\"ל איך שייך העבודה שנק' פולחנא באה' ורחימותא שיהי' נק' פולחנא דרחימותא הרי אהבה תלוי' בלב והעבודה הוא בעול המעשה בלבד. אך הענין הוא עד\"מ העבודה שעובד העבד לאדון מאהבה יותר מתכשרת ורצוי' בלב האדון מעבודה שעובד מצד היראה שהרי עובד מאהבה אין עבודתו בדרך כפי' ובע\"כ כלל אלא דוקא מרצונו ולבבו הטוב ונאמן מצד ששלם לבבו בבחי' ברית והתקשרות אה' חזקה מקרב ולב עמוק עד שמחמת זה בלבד עובד בכל כחו ונפשו ולא תכבד עליו העבודה כלל אדרבה יוכל למס\"נ וכל אשר לו כדי לעשות נח\"ר לאדונו כמו אברהם שהי' כל עבודתו רק מצד האהבה דוקא אברהם אוהבי כו' וכתיב עקב אשר שמע אברהם בקולי וישמור משמרתי מצותי כו' ונסהו בי' נסיונות ועמד בכולם גם בבנו יחידו (והגם שא' עתה ידעתי כי ירא אלקים אתה ולא חשכת את בנך את יחידך כו' ולא א' אוהב ה' היינו לפי שכבש רחמי האב כו' שזהו בא מצד יראת אלקי' בבחי' הגבור' שבחס' כמ\"ש במ\"א בענין עקדת יצחק שנכללו גבו' דיצחק בחס' דאברהם כו') וזהו"],[2400650261,"פולחנא דרחימותא ואין הכוונה שאהבה היא באה בדרך עבודה שאהבה תלוי' בלב אלא הכוונה על העבודה שמסתעפת רק מכח האהבה הגדולה שבלב עז\"א לית פולחנא כפולחנא זו שמסתעפת מצד האהבה דוקא שנק' פולחנא דרחימותא לפי שמוכשרת ורצוי' יותר לפני ה' מן העבודה שמסתעפת רק מצד היראה שהיא בעול ובע\"כ ואינה נק' עבודה תמה כ\"כ כעבודה שמצד האהבה דוקא (וז\"ש לית פולחנא דמשמע שיש עוד פולחנא שמצד היראה בעול מ\"ש בלבד אבל לית פולחנא ועבודה תמה כפולחנא זו שמצד האהבה כו' ובמ\"א מבואר שהעבודה בעומ\"ש גבוה יותר מהעבודה שבאהבה והוא בחי' עבד שלמעלה מבחי' בן כו' וז\"ש הקים על עול תו\"מ כו' והיינו א\"ח עט\"ב כו' למעלה מבחי' ז\"א שהוא בחי' זכור לדכורא שא' כאן והתירוץ ידוע דשניהם אמת שיש ב' מיני יראה יר\"ת קבלת עול בע\"כ שזהו בחי' שמור לנוק' דכאן שלמטה מעבודה דמ\"ע מאהבה כמ\"ש לית פולחנא כו'. והב' יראה עילאה בחי' ביטול העצמיות וכמ\"ש דו\"ר רו\"ד כו' והוא עומ\"ש שמצד בחי' הביטול בעצמו בתכלית עז\"א א\"ח עט\"ב כו' למעלה מרחימו זו שנק' פולחנא דרחימותא כו' וז\"ש שמי עם י\"ה כו' דגם שמירת ל\"ת מצד בחי' הביטול רצון שבזה הרי מגיע בי\"ה שלמעלה מו\"ה דמ\"ע כו'). והנה מאחר דלית פולחנא כפולחנא שמצד האהבה דוקא ולא מצד היראה ממילא יובן ג\"כ בענין העבודה ברמ\"ח מ\"ע שנזכר ל' עבודה בהן כמה פעמים שהרי עיקר אמיתת העבודה שלהם דוקא כשמסתעפים מצד האהבה שנק' פולחנא דרחימותא ולא כשהן באין מצד היראה בלבד שאינו עבודה תמה כ\"כ כמו עבד לאדון הגם שישמור כל עבודתו מצד היראה אך אינה רצויה לאדון אחר שרואה בו שאינו אלא בעול וכפי' ולא מלב שלם כו'. אמנם בענין הל\"ת נהפוך הוא שעיקר ענין שלהם במדת היראה ופחד אלקים ולא במדת האהבה וכמו שא' בעבודה דמ\"ע דלית פולחנא שלהם ביראה אלא באהבה כך להיפוך בענין שמירות דמל\"ת אין אמיתית ענין שלהם רק ביראה ולא באהבה והטעם הוא לפי שכל עיקר הענין במל\"ת אינו רק השמירה לשמור את נפשו להיות סור מרע בפו\"מ בתכלית בזהירות יתירה הרי לזה אינו מועיל רק היראה דוקא שמחמת היראה ישמור נפשו ביותר וכל שאינו ירא אלקים כ\"כ לא ישמור את נפשו כו' כי הזהירות היתירה שלא לעבור על ציווי ה' שצוה לסו\"מ אינה מסתעפת רק לפ\"ע היראה שבלבו אם רב או מעט כן ירבה השמירה או ימעט כו'. אבל א\"ז תלוי באה' שבלב שיוכל להיות שלא ישמור א\"ע כ\"כ גם אם יש בלבו אהבה כי השמירה והריחוק תלוי ביראה דוקא וע\"י האהבה לא ישמור א\"ע כ\"כ וכמו שאנו רואים בעבד לאדון בענין השמירה שלא לסור מציווי האדון במעשה"],[2400650262,"היפוכו ליזהר בנפשו שלא לעשות זה תלוי בערך יראתו ופחדו ממנו ולא מצד אהבתו (אדרבא מצד אהבתו יוכל להקל בנפשו שלא לשמור א\"ע לעשות ההיפוך לציווי האדון כו') וזהו שנאמר בעבודה דמ\"ע לאהבה את ה' ולעבדו בכל לבבכם שתלוי באה' שבלב כן תהי' העבודה בכשרון כל לבבו שרצויה אז ביותר כנ\"ל. אבל מצות ל\"ת שעיקר ענין שלהם אינו כשרון לבב במעשה הטוב רק הזהירות והשמירה בלבד שלא לעבור על רצונו כו' זהו ביראה דוקא שהוא עומ\"ש יתירה (ולפי\"ז אינו מובן לכאורה בענין ב\"פ דק\"ש בפ' שמע מקבל עליו עומ\"ש תחילה ואח\"כ מקבל עליו עומ\"צ בפ' והי' אם שמוע ובפ' שמע אמר ואהבת שהוא שורש העבוד' דמ\"ע ואיך א' שהוא קעומ\"ש שהיא שורש הל\"ת ובפ' והי' עומ\"צ שהיא היראה שהוא בעול בלבד כנ\"ל ושם נאמר לאהבה את ה' ולעבדו כו' הרי נהפוך הוא. והתירוץ מבואר במ\"א שב\"פ דק\"ש הוא ענין לאכללא שמאלא בימינא וימינא בשמאלא שהוא בחי' התכללות דחו\"ג כידוע ולכך בפ' שמע הוא בבחי' שם מ\"ב שהן מ\"ב תיבות מואהבת עד ובשעריך בחי' כלי הגבו' והאור דהכוונה הוא בבחי' החסד דואהבת ובפ' והי' שם ע\"ב דחס' ע\"ב תיבות עד ושמתם בחי' כלי החס' והאור דהכוונה בבחי' עומ\"צ ביראה כמ\"ש השמרו לכם כו' (או להיפוך שהשם הוא האור והכוונה הוא הכלי ושם מ\"ב בפ' שמע הוא אור הגבו' בכלי החס' ובפ' והי' שם ע\"ב האור דחס' בכלי הגבו' בכוונה דעומ\"צ והכל ענין א'). ובזה יתורץ ג\"כ במ\"ש בעבודה דמ\"ע בפ' והי' לאה' ולעבדו שמקבל עליו עומ\"צ ביראה לאכללא ימינא בשמאלא בחי' ה\"ח דרמ\"ח בה\"ג דיראה בל\"ת ובפ' שמע בקעומ\"ש דיראה א' ואהבת שזהו לאכללא שמאלא בימינא אבל לעולם שורש בחי' החסדי' ברמ\"ח מ\"ע ושורש בחי' הגבו' בל\"ת. (אך מה שמחלק לב' דברי' עומ\"ש ועומ\"צ ובכאן משמע שעומ\"ש דיראה הוא עומ\"צ כמשי\"ת בענין שמור לנוק' כו' הנה באמת עומ\"צ הוא עול העבודה במ\"ע ג\"כ שהוא מ\"ש והי' א\"ש תשמעו אל מצותי כו' והוא בחי' ביטול רצון שלמע' מאהבה שבמ\"ע כנ\"ל. ומפני שנעוץ סופן בתחילתן מקבל עליו עומ\"ש ואח\"כ עומ\"צ דהא בהא תליא כנ\"ל בענין דו\"ר ורו\"ד כו' וכמ\"ש במ\"א):\n(ע) <b>ועתה</b> יובן ענין המאמר דשמור לנוק' דוקא דהנה ידוע דשורש היראה כמו שהוא למע' הוא בבחי' המל' שנק' יראה שהרי עיקר בחי' המל' היא היראה ואימת מלך וכמו שום תשים עליך מלך שתהא אימתו עליך וכך בחי' מל\"ש דלעילא בחי' מל' דאצי' הוא בבחי' יראה ונק' אשה יראת ה' כו' ועיקר בנין המל' מבחי' הגבו' וכידוע דהנוק' רובה גבו' ומיעוטה חסדים והדכר רובו חסדים ומיעוטו גבו' כמ\"ש כי זכר חסדו כו' וכמ\"ש בזוהר ע\"פ בזאת יבוא אהרן כו' בזאת"],[2400650263,"דוקא שהוא היראה בחי' נוק' ולא בזה שהוא בבחי' אהבה (ונק' פתח ושער לה' שבזאת דוקא יבוא כו') (ולכך כל שיראתו קודמת לחכמתו דוקא אז חכמתו מתקיימת דאם אין יראה אין חכ' כמ\"ש הן יראת ה' היא חכ' וכתי' ראשית חכ' יראת ה' לפי שנעתב\"ס וסוב\"ת דיראה תתאה בעול מל' שנק' סופן נעוץ בחכ' יר\"ע ביטול במציאו' כנ\"ל בענין דו\"ר כו' ולזה בזאת דוקא יבוא ולא בזה כו') ומבואר דעיקר ענין השמירה בל\"ת הוא במדת היראה דוקא ולא באה' כו' והיינו שמור לנוק' דשמירה דל\"ת דסו\"מ היינו בנוק' דוקא שהוא בבחי' היראה ופחד אלקי' דבחי' המל' שום תשים עליך מלך בקעומ\"ש שתהא אימתו עליך זהו עיקר המועיל לשמירה דמל\"ת ולפי\"ז שורש כל הל\"ת הוא בבחי' המל' שנק' מצות המלך שלא לעבור על מצותיו כו' מצד האימה ויראה גזירת מלך בלבד (וכענין אל יאמר אי אפשי כו' אלא אפשי אבל אבי שבשמים גזר עלי). והנה ידוע דבחי' המל' בחי' נוק' דז\"א הוא היורד למט' מט' להיות ראש לשועלים ברבוי השתלשלות בצירופי אותיות בבי\"ע במיעוט אחר מיעוט עד שמקבלים ממנה גם אלקים אחרים דקליפה וכמ\"ש לפתח חטאת רובץ כו' וכמא' דחוי' קטיר לרגלי' דנוק' והוא בהתלבשות ועוצם ירידת והסתר המל' בע\"ש דנוגה בבחי' המל' דקליפה שעליה א' רגלי' יורדות מות כו' מות דנחש הקדמוני וכמ\"ש ואתה תשופנו עקב וכידוע בענין נחש כרוך על עקבו לא יפסיק דרחב\"ד שלא הפסיק תפלתו משום דמאן דקטיל לחויא יהבין לי' ברתא דמלכא דא צלותא וכמ\"ש במ\"א. והנה לזאת שהחיצוני' יכולים בקל יותר לקבל יניקה מבחי' המל' בהיותה יורדת למטה ביותר שהם קרובים אלי' שם ביותר ע\"כ צריכה שמירה מעולה ביותר שלא יוכלו החיצוני' לקבל יניקה ממל' דקדושה. והיינו טעם בחי' שמור לנוק' דוקא ע\"י שמירה דל\"ת בבחי' היראה דוקא דשומר מצוה לא ידע כו' ועיקר השמירה הוא להיות סו\"מ בתכלית שאז אין מקום כלל ליניקת החיצוני' גם בבחי' ומדריגה אחרונה דמל' דקדושה והיינו שארז\"ל זה שמי לעולם שמי עם י\"ה שס\"ה שמי הוא שם הנק' בפי כל והוא שם א\"ד שהוא בחי' שמור לנוק' בחי' המל' ועם י\"ה הוא בחי' מקיף ושומר כו' כידוע דכל שומר גדול מן המשתמר וכמ\"ש במ\"א והיינו שורש הל\"ת שהן בי\"ה שהן בבחי' שומר למל' דשמור לנוק' מפני שצריכה שימור ביותר מטעם הנ\"ל ובחי' היראה דמל' הוא שורש הל\"ת כנ\"ל ולכך א' זה שמי כו' וד\"ל. אבל הנה שרש המ\"ע הוא בבחי' ה\"ח דדכורא שהוא בבחי' הוי' דז\"א וז\"ש זה זכרי זכרי עם ו\"ה רמ\"ח כו' והיינו זכור לדכורא וביאור הדבר מובן מענין הנ\"ל בשורש המ\"ע שהוא בחי' האהבה והאה' שרשה בבחי' חסד דז\"א כו' וכמ\"ש אהבת עולם אהבתיך ע\"כ"],[2400650264,"משכתיך חסד וכתי' כי אמרתי עולם חסד יבנה שהאה' נמשך מלמעלה למט' כמו החס' שיורדי' מגבוה לנמוך כו' והיינו בחי' ה\"ח דדכורא שהוא המשכות והתקשרות דמשפיע אל המקבל שהוא ע\"י האהבה שבלב עד שנמשך כמים כו' וזהו מבחי' חס' דז\"א כמ\"ש כי זכר חסדו כו' (דעיקר בנין ז\"א רובו מן החסדי' דבן מסט' דאבא קאתי שאור אבא מקור החס' ובת מסט' דאימא מקור הגבורות וכמ\"ש כאמה בתה כו' לכך רובה גבו') והיינו שורש העבודה ברמ\"ח מ\"ע ע\"י האהבה לה' שיומשך בחי' אהבה וחס' עליון דז\"א למל' והוא יחוד קוב\"ה ושכינתי' בכל מ\"ע שנמשך ה\"ח דדכורא לנוק' ומזה נבנה בנין המל' בבחי' החס' דדכורא וכמ\"ש והוכן בחסד כסא וכן עולם חסד יבנה (וכמו דרמ\"ח פקודין רמ\"ח אברים דז\"א שנק' מצותי כידוע ג\"כ בנינם ע\"י ה\"ח המגדילים כידוע בטעם מספר רמ\"ח דט\"ס טפ\"ט בג' כלים הרי ג\"פ פ\"א שעולה רמ\"ג וה\"ח המגדילי' הוא רמ\"ח וכך הוא במ\"ע דמל' הוא ג\"כ ע\"י ה\"ח דדכורא כו'. וז\"ש זה זכרי זכור לדכורא עם ו\"ה רמ\"ח שהן ה\"ח דוי\"ו דז\"א למל' שזהו גילוי אלקות שבכל מ\"ע בבחי' יחוד ברכה וקדושה יב\"ק). וזהו שא' כאן ושמרו בנ\"י את השבת (את ל' טפל) דא לילה רזא דנוק' זכור את יום השבת דא יום רזא דדכורא פי' לילה ויום הוא בחי' זו\"נ דנהו\"ע דאצי' נק' יום ואור המל' בבי\"ע נק' לילה. וזהו מאור הגדול לממשלת היום הוא בחי' חסד דז\"א דחסד אל כל היום ומאור הקטן דמל' לממשלת הלילה בחי' הגבו' כו'. והנה כתי' ויניחהו בג\"ע לעבדה ולשמרה לעבדה רמ\"ח מ\"ע ולשמרה שס\"ה ל\"ת דע\"י רמ\"ח מ\"ע נמשך תוס' אור בג\"ע דעשי' ובריאה וע\"י ביעור הרע דל\"ת נשמר מכל רע דיניקת החיצוני' בג\"ע וכ\"ז בחול שהן שיה\"מ שהוא התיקון והבירור לעבדה ולשמרה והיינו ענין רמ\"ח מ\"ע דה\"ח דדכו' ושס\"ה ל\"ת דה\"ג דמל' שמור לנוק' והיחוד דה\"ח דדכורא וה\"ג דנוק' דזכור ושמור דמ\"ע ול\"ת הוא בכל יום שזהו שארז\"ל שזכור ושמור בדבור אחד נאמרו פי' זכור לדכורא בו\"ה ושמור לנוק' בי\"ה הרי מתייחדים ומתכללים כא' בדבור אחד והוא שם ה' וכמ\"ש שמי עם י\"ה וזכרי עם ו\"ה. וזהו עיקר בחי' היחוד דזו\"נ ע\"י זכור ושמור דמ\"ע ול\"ת שזהו לעבדה ולשמרה בכל יום והיינו מ\"ש בזוה\"ק בכמה דוכתי בפי' אלקים אל דמי לך דנהו\"ת קארי תדיר לנהו\"ע וכן למען יזמרך כבוד וכן אש תמיד תוקד וכה\"ג שזהו התכללות ויחוד דמקבל ומשפיע בה\"ח וה\"ג דהיינו מה שאלקים אל דמי וכן יזמרך כו' הוא בבחינת ה\"ג דאל אישך כו' ואשר נמשך היחוד על ידי מ\"ע הוא מה\"ח דז\"א כו' אך כ\"ז בחול שהן בחינת הבירורים דרפ\"ח בסו\"מ וע\"ט במ\"ע ול\"ת אבל בשבת עולין הנשמות בג\"ע מלמטה למעלה ואינם עוסקים בג\"ע לעבדה ולשמרה כו' רק"],[2400650265,"עבודתם בעונג עצמי והתענג על ה' שלא בדרך עבודה דאהוי\"ר כמ\"ש במ\"א בענין ההפרש תפלה דחול לתפלה של שבת בזה כך בכללות נ\"י בשרשם במל' וז\"א למעלה הרי ג\"כ ענין העלאה ושיר דשבת תתאה בחינת לילה לגבי שבת עילאה בחינת יום הוא שלא בדרך עבודה כמו שיר דלמען יזמרך כבוד בחול כו' אלא הוא בבחינת עצמו' העונג והוא ממה ששבת וינפש ממלאכתו שנקרא שבת דמעלי שבתא בליל שבת רזא דלילה משבח ומזמר ליום השבת בחינת שבת עילאה דז\"א רזא דיומא שבו יום שכולו שבת שלא מן העבודה כלל והיינו גם כן ע\"ד ענין המצות דזכור ושמור זכור לדכורא ושמור לנוקבא כך ושמרו בני ישראל בליל שבת שמור לנוקבא שבת תתאה דמל' וזכור שבת דיומא בעלמא עילאה דז\"א דאצי' וזכור ושמור בד\"א נאמרו היינו זכור ושמור דשבת ממש שהן ב' מיני שבתות שמור דליל שבת וזכור דיומא בד\"א נאמרו שמתייחדים כא' והוא עיקר ענין מזמור שיר זה שזהו מזמור שיר דשבת דלילה שמור דשבת דנוקבא מזמר ומשבח ליום השבת זכור דשבת דדכורא ובמזמור שיר זה מתכללים ביחוד שזהו בד\"א נאמרו כמו זכור ושמור דמ\"ע ול\"ת הנ\"ל והיינו ב' שבתות מתייחדים כא' וזהו פי' עולת שבת בשבתו שבת תתאה בשבת עילאה זכור ושמור כא' וכן מידי שבת בשבתו יבוא כל בשר שזהו עליות הנשמות מג\"ע לג\"ע שעולין ע\"י המל' רזא דלילה ג\"כ בכל שבת בשבתו הנ\"ל אחר עבודתם בחול לעבדה ולשמרה במי שטרח בע\"ש כו' כמו ענין תפלה דחול לברר בהיפוך הרע כו' ובוע\"ט הוא הגורם בחינת ההעלאה דשבת להתענג על ה' שזהו תפלה דשבת שאחר הבירור הוא העלאה והיחוד [העצמי] אבל בשבת בורר אסור כידוע וכך הוא למעלה בנשמות דג\"ע ובכללות דזו\"נ דאצי' שהן זכור ושמור דשבת ודחול על ידי המצות כו' וד\"ל:\n(עא) <b>ובגין</b> כך מזמור שיר ליום השבת ואשכחן בכמה אתר דעלמא תתאה לא סליק בשמא ואתי' סתם כגון האי וכגון ויקרא אל משה וכגון ואל משה אמר עלה אל ה' כולא סתים שמא כו' וכולא בגין דאית בי' דרגא עילאה ולגבי דרגא עילאה איהו לא סליק בשמא, נהורא דשרגא לא סליק ביממא בנהורא דשמשא ע\"כ. הנה בא לתרץ כאן מה שהוקשה לו בתחלת המאמר במ\"ש מזמור שיר ולא אמר מאן קאמר לה ומתרץ כאן דאשכחן כה\"ג בכמה דוכתי כמו ואל משה אמר עלה אל ה' ולא א' מי הוא בעל המאמר שא' למשה עלה כו' וכה\"ג מצינו בויקרא אל משה ולא אמר מי הוא הקורא אותו אלא ויקרא סתם (וכן ויאמר שוב אשוב כו' וה' פקד את שרה כו' כאשר אמר כו' וכה\"ג) ועוד אמר דויקרא א' זעירא דוקא להורות על ענין זה מה שלא נז' מי הוא הקורא"],[2400650266,"לפי שלא סליק בשמא לגבי דרגא עילאה כו'. וביאור הדברים ידוע דבחינת מל' דאצי' נקרא א' זעירא וכן ואל משה אמר סתם הוא בחינת מל' ולפי שהמל' ללמג\"כ רק מה שמקבלת מז\"א שנקרא דרגא עילאה ע\"כ לא סליק בשמא ואתי' סתם כמשל נהורא דשרגא כו'. ולהבין ביאור ושרש הדברים הנה ילה\"ק תחילה בשורש ענין האותיות שהוא בחינת המל' בכ\"מ כמו בחינת מל' שבחכ' הוא בחינת אותיות דחכ' ומל' שבחסד הוא בחינת אותיות דחסד וכן אותיות דכתר שהוא הרצון וידוע דכל בנין המל' הוא רק מבחי' האותיות בלבד דהיינו מבחי' אותיות דע\"ס דז\"א נבנה בנין המל' כמו מבחינת מל' שבחכ' דז\"א נעשה בחינת חכ' שבמל' וממל' דחסד דז\"א נעשה חסד שבמל' (ונקרא עשיראה דכולא וכמ\"ש במ\"א בענין דו פרצופים כו') והנה תחילה י\"ל במהות האותיות שבע\"ס עצמן כמו אותיות דחכ' ואותיות דמדות וכה\"ג דהנה אנו רואים כאשר אדם טרוד בעצם המושכל כמו שהוא בכח שכלו והשגתו בעומק הרי הוא אז רק סברא שכליי' בלי מציאת עדיין בבחינת מח' גם לא נק' מח' שכליי' אלא שכל פשוט וכל זמן שהוא בעוצם טרדתו בעצם אור השכל אין בו שורש להתהוות האותיות כלל רק אחר הצמצום והעלם אור השכל בעצם אז מתהוו' אותיות השכל לחשוב לשכל זה באותיות (וגם מחשבת עיון בהשגה שבא באורך ורוחב עדיין יוכל להיות שהוא בלא אותיות מח' ממש רק נקרא מח' השכל עיון והגיון בלבד עד אשר בא באותיות מח' ממש שנקרא לאה בחי' אחוריים דמל' דתבונה כמ\"ש במ\"א) ולכאורה יפלא הדבר אם אין עיקר מציאות האותיות מתהווים רק לאחר סילוק עצם אור השכל המושג במוחו א\"כ כאשר בא להביא דבר שכל זה לבחי' עומק השגתו כמו שהוא בעצם חוזר ונתבטל ונסתלק מהות האותיות דשכל זה ולהיכן יסתלקו בבוא הארת גילוי עצם השכל אלא מוכרח מזה לומר שיש לאותיות השכל שורש תחילה בעצם השכל דהיינו שהמה כלולים בהעלם בעצם השכל ואינם ניכרים שם במציאות כלל וכלל בהיות האדם טרוד בעצם עומק השכל כלולים האותיות שם ואינם נרגשים במציאות כלל רק כשמביא השכל לידי גילוי אז יוצאים לגילוי בבחי' מציאות ומהות מהעלם בעצם ולזאת כאשר יחזור לעומק עצם השכל יסתלקו האותיות ממציאותם ויתכללו בהעלם בתוך העצם בלתי נכרין במציאות כמקדם כו' ונמצא ב' מיני אותיות הא' אותיות שכלולים בעצם השכל בלתי ניכרין במציאותם עדיין והב' אותיות שבאין בבחינת גלוי מהעלמם במח' כו' וכמ\"ש במ\"א ראי' לדבר זה ממה שכאו\"א כפי כח וטבע השגתו לעצם השכל כך יהי' בחינת אותיות השכל שלו שעל ידם יהי' אופן התגלות זה השכל בצירופי' שונים כי עיקר ענין האותיות בשכל היינו בחינת גלוי השכל להבינו על ידם לזולתו וכה\"ג כי בלתי אותיות"],[2400650267,"השכל לא הי' אור עצם השכל רק במוחו נתפס ולא הי' בא לידי תפיסה וקבלה למטה הימנו כמו להיות מוחין במדות וכמו אדם שרוצה להביא איזה שכל בגילוי שיבינהו הכל באותיות הכתב או בדבור בהכרח שיהי' גלוי שלו על ידי בחינת אותיות השכל אבל בהיות האותיות כלולים בעצם השכל לא יוכל להביאו לידי גילוי בכתב ובע\"פ כלל רק לעצמו מבינו כו' ולכך אנו רואים ששני בני אדם מבינים שכל וסברא א' וכשבאין לדבר ולהבינו לזולתו או לכתבו בכתב זה ידבר ויכתוב בצירופי' אלו וזה יאמרנו ויכתבנו בצירופי' ולשון אחר והמכוון א' משניהם רק שינוי הל' בלבד כמו שינוי לשונות המפרשים בתלמוד כפרש\"י ותוס' ור\"ן בענין מכוון אחד וזה רק מצד שלזה יש לו אותיות השכל באופן הגילוי שלו כך וזה גילוי אותיות שכלו באופן אחר והעצם של השכל א' בשניהם ממש ומובן מזה עכ\"פ דעיקר ענין האותיות הוא רק להביא השכל לגילוי למטה ונקרא בחינת כלים וכשהם כלולים בשכל היינו בשרשם הא' כמו שמתהווים עם עצם השכל ממקור השכל כמ\"ש במ\"א ששורש האותיות בכתר כו' הרי אינם בחינת כלים שהוא גילוי השכל רק הם שורש לגילוי העצם אח\"כ כשבאין לידי גילוי וזהו עיקר ענין ב' מיני אותיות הנ\"ל בכל מציאות דבר מה כשכל וכה\"ג. והנה עד\"ז יובן בכל בחינת אותיות שבכל מציאות דבר מה כמו המדות שבלב הרי כל זמן שהמדות המה בעצם מהותם באהבה שהיא בלב בעצם מציאותה אז עדיין הוא רק בחינת עצמיי' ולא תבוא עדיין לבחינת הרהור אותיות במח' לחשוב באותיות שנקרא הרהורי לבא ומכ\"ש שלא יביאנה לדבור רק אחר העלם וקיצור עצם של אור האהבה שבלב יתהווה ממנה הרהור אותיות במח' לחשוב באותיות מה שאוהב בלבו ואח\"כ ממילא ידבר גם בדבור כו' אבל בהיות האהבה בלב עדיין בבחינת עצמיות שלה אין בה אותיות מח' כלל רק עכ\"ז בהכרח שיש בה בהעלם אותיות ההרהור שמהרהר אחר כך בגילוי במח' רק שכלולין ובטלין שם במציאותם לבלתי ניכרין כלל עדיין במהות אותיות רק אחר כך מתגלין בחינת אותיות הללו שבתוך המדות שבלב ונראים במהות ויש בפ\"ע כו' ונמצא שגם במדות יש ב' מדריגות אותיות כמו בשכל כנ\"ל א' אותיות הכלולים בו בהעלם ונקרא אותיות של המדות בעצם כאותיות שבשכל בעצם הנ\"ל והב' בחינת אותיות שבאין בגלוי (שבהן ועל ידן מתגלין המדות לחוץ כאותיות השכל כנ\"ל שמגלין השכל בהבנה למטה שנקרא בחינת כלים כו' וכך הוא בכל אותיות של כל מציאות כמו רצון ותענוג גם כן יש ב' מדריגות אותיות כנ\"ל ונמצא שעל ידי גילוי אור העצם כמו שהוא בבחינת עצמיות שלו דוקא אזי האותיות כלולים בו ובטלים לגמרי כנ\"ל וא\"כ לא יוכל לבוא לידי גילוי של השפעה למטה הימנו כנ\"ל וכשצריך העצם לבוא לידי גילוי"],[2400650268,"לחוץ מעצמותו בהכרח שיהי' העלם וכיווץ העצם כדי שיבוא לכלל אותיות הללו שבבחינת גילוי להביאו לבחינת גילוי זה של חוץ מעצמותו למקבלים אבל האותיות א' הם כי אותיות שהיו כלולים תחלה הן הבאין בבחינת גילוי להביאו לידי גילוי לעצם הדבר רק שתחילה לא היו פועלין פעולתן אלא להיפוך דהיינו בהיות עצם הדבר כמו שהוא שלא יוכל לבוא למקבלים כלל כו' אזי מה שיש בכח העצם להביא א\"ע לידי גילוי למקבלים בטל ונכלל בעצמותו ממש בביטול א' באלף כו' וד\"ל):\n(עב) <b>והנמשל</b> מכ\"ז יובן למשכיל למעלה בשרש בחינת המל' שהוא בחינת האותיות בכ\"מ בפרט כמו מל' שבחכ' מל' שבחסד וכה\"ג ובד\"כ הרי מכל בחינת אותיות שבע\"ס בכלל מזה נבנה בנין המל' והענין הוא דבחי' המל' דבחכ' ה\"ז כמשל בחינת אותיות שכלולים בעצם החכ' שבמוח שהוא בחינה האחרונה שבו שהוא רק מה שיוכל לבוא לידי גילוי למקבל כנ\"ל ועדיין אין נכרים שם במציאות כלל בהיות עצם החכ' מאיר רק אחר סילוקה והעלמה דוקא מתהווים האותיות בבחינת גילוי מהות כך בחינת מל' דחכ' כלול בהעלם כביטול והתכללות טפל בעיקר ואינו ניכר כלל רק אחר צמצום האור דחכ' בעצם אז בא לידי גילוי באותיות שנקרא כלי החכ' שמגביל האור ונקרא מל' דחכ' וב' מדריגות יש כאן אותיות הכלולי' בחכ' ואותיות שמגלים אור החכמה וכן בשאר הספי' כאור החסד וכה\"ג שהאותיות שבמדה זו כלולים בה בהעלם והתכללות ואחר כך אחר צמצום וכיווץ העצם של המדה מתהווה גילוי האותיות ונקרא מל' שבחסד כמו שצריך לבוא החסד במח' ודיבור וכה\"ג כנ\"ל באריכות. ומובן מזה דבחינת המל' דע\"ס כמו שהן בעצם בבחינת האצי' הרי כלולים שם ובטלים מציאותן כנ\"ל רק כשצריכין לבוא לידי גילוי שפע לחוץ מעצם מציאותן הוא מדריגה הב' דאותיות שבהן שמביאין אותן לידי גילוי לחוץ הרי מהם עיקר הבנין בחינת המל' דאצי' שהוא בחינת אותיות הדבור לגבי מדות דז\"א (או אותיות המח' שנקרא לאה כו') שא\"א שיהי' בחינת אותיות הדבור במהות בפ\"ע כ\"א אחר שנעשה צמצום והעלם בעצם אור המדות שבלב עד שבאין בבחינת הגילוי לחוץ בבחינת אותיות שהן המגלין אותן לחוץ ונק' מל' שבחסד מל' שבגבורה כנ\"ל מזה נעשה כל עיקר מהות הדבור שהוא בחי' חסד וגבורה שבמל' וכן ממל' שבחכמה נעשה חכמה שבמל' כמו מאותיות השכל שמגלה אותו המשפיע כשמשפיע השכל מזה נעשה גופו של השכל בדבור למקבל וכן מאותיות אהבה שבלב דמשפיע נעשה גילוי אור האהבה שבדיבור למקבל (וא\"כ נקרא בחינת הדבור מל' דמל' גילוי דגילוי רק שגילוי אותיות דמדות דמשפיע המה בחינת אותיות עצמיי' שלו שבהם ועל ידם דוקא"]]});
